/* Exam-suite drill content, keyed by exam (1-6 unit exams, 7 = final).
   Authored and adversarially fact-checked per exam.
   Assembled by scratchpad/assemble_drills.py */
window.FINAL_DRILLS_BY_EXAM={"1":{"labs":[{"labs":[["Arterial pH","down"],["PaCO2","up"],["Serum bicarbonate","up"],["PaO2","down"]],"opts":["Partially compensated respiratory acidosis","Metabolic alkalosis with respiratory compensation","Fully compensated metabolic acidosis","Acute respiratory alkalosis"],"c":0,"why":"The pH is acidic and the PaCO2 is high, so the lung is the primary problem: retained carbon dioxide combines with water to form carbonic acid. The raised bicarbonate is the kidney retaining base over several days, and because the pH has not yet returned inside the normal range the compensation is only partial.","week":"1"},{"labs":[["Arterial pH","up"],["PaCO2","down"],["Serum bicarbonate","n"],["Ionised calcium","down"]],"opts":["Acute respiratory alkalosis","Metabolic alkalosis with respiratory compensation","Chronic fully compensated respiratory alkalosis","Metabolic acidosis with respiratory compensation"],"c":0,"why":"Hyperventilation blows off carbon dioxide faster than metabolism makes it, so carbonic acid falls and the pH rises. The normal bicarbonate is the discriminator: the kidney has had no time to dump base, which dates the problem to hours. Alkalaemia also drives calcium onto albumin, so the ionised fraction falls and the patient reports circumoral tingling and carpal spasm.","week":"1"},{"labs":[["Arterial pH","down"],["Serum bicarbonate","down"],["PaCO2","down"],["Anion gap","up"],["Serum potassium","up"]],"opts":["High anion gap metabolic acidosis with respiratory compensation","Normal anion gap metabolic acidosis from diarrhoea","Acute respiratory acidosis","Metabolic alkalosis with respiratory compensation"],"c":0,"why":"Ketoacids are unmeasured anions that consume bicarbonate, so the bicarbonate falls while the anion gap widens. The low PaCO2 is Kussmaul breathing driving off carbon dioxide as compensation, not a second disorder. The high serum potassium is deceptive: hydrogen ions are being buffered inside cells in exchange for potassium moving out, so total body potassium is actually depleted.","week":"1"},{"labs":[["Arterial pH","up"],["Serum bicarbonate","up"],["PaCO2","up"],["Serum potassium","down"],["Serum chloride","down"]],"opts":["Metabolic alkalosis with respiratory compensation","Acute respiratory alkalosis","Partially compensated respiratory acidosis","High anion gap metabolic acidosis"],"c":0,"why":"Loss of hydrochloric acid through vomiting or nasogastric suction leaves bicarbonate unopposed, so pH and bicarbonate rise together and chloride falls. The respiratory centre is suppressed and hypoventilation raises the PaCO2 as compensation. Volume depletion then drives aldosterone, which trades sodium reabsorption for potassium and hydrogen loss, dropping the potassium and sustaining the alkalosis.","week":"1"},{"labs":[["Serum sodium","down"],["Serum osmolality","down"],["Urine osmolality","up"],["Urine sodium","up"],["Blood urea nitrogen","down"]],"opts":["Syndrome of inappropriate antidiuretic hormone","Hypovolaemic hyponatraemia from vomiting","Central diabetes insipidus","Primary polydipsia"],"c":0,"why":"Antidiuretic hormone keeps inserting aquaporins regardless of plasma osmolality, so water is retained and the plasma is diluted while the urine stays inappropriately concentrated. Because volume is expanded rather than depleted, aldosterone is switched off and the kidney keeps excreting sodium, which is why the urine sodium is high and the urea is diluted rather than raised.","week":"1"},{"labs":[["Serum sodium","up"],["Serum osmolality","up"],["Urine osmolality","down"],["Urine specific gravity","down"]],"opts":["Diabetes insipidus","Syndrome of inappropriate antidiuretic hormone","Primary polydipsia","Fluid volume overload"],"c":0,"why":"Without antidiuretic hormone action the collecting duct stays impermeable to water, so litres of dilute urine are lost. Free water loss concentrates what remains, lifting serum sodium and osmolality. Primary polydipsia also produces dilute urine, but there the excess intake dilutes the plasma, so serum sodium would be low rather than high.","week":"1"},{"labs":[["Blood urea nitrogen","up"],["Serum creatinine","n"],["Urine specific gravity","up"],["Haematocrit","up"],["Urine sodium","down"]],"opts":["Fluid volume deficit with prerenal azotaemia","Acute tubular necrosis","Fluid volume overload","Syndrome of inappropriate antidiuretic hormone"],"c":0,"why":"Reduced renal perfusion slows tubular flow, so urea is passively reabsorbed while creatinine is not, pushing the urea to creatinine ratio above twenty to one. Aldosterone and antidiuretic hormone conserve salt and water, giving concentrated low-sodium urine, and the haematocrit rises because plasma volume is lost while red cell mass is unchanged. In acute tubular necrosis the injured tubules cannot conserve sodium, so urine sodium would be high and creatinine would climb.","week":"1"},{"labs":[["Serum potassium","up"],["Serum creatinine","up"],["Arterial pH","down"],["ECG","abn"]],"opts":["Hyperkalaemia secondary to acute kidney injury","Hypokalaemia from loop diuretic therapy","Hypercalcaemia of malignancy","Acute respiratory alkalosis"],"c":0,"why":"Failing kidneys can excrete neither potassium nor the daily acid load, so both accumulate, and the resulting acidosis drives still more potassium out of cells in exchange for hydrogen entering them. A high extracellular potassium makes the resting membrane potential less negative, which produces tall peaked T waves and then a widening QRS as sodium channels inactivate.","week":"1"},{"labs":[["Total serum calcium","down"],["Ionised calcium","down"],["Serum phosphate","up"],["Parathyroid hormone","down"],["Serum albumin","n"]],"opts":["Hypoparathyroidism following thyroid surgery","Pseudohypocalcaemia from hypoalbuminaemia","Hypomagnesaemia-induced hypocalcaemia","Primary hyperparathyroidism"],"c":0,"why":"Parathyroid hormone normally pulls calcium from bone, reabsorbs it in the distal tubule and wastes phosphate in the urine. When the glands are removed or bruised during thyroidectomy the hormone falls, so calcium drops while phosphate climbs, a mirror-image pair that is the signature of the disorder. The normal albumin proves this is a true ionised deficit rather than a laboratory artefact of low protein binding.","week":"1"},{"labs":[["Serum magnesium","down"],["Serum potassium","down"],["Total serum calcium","down"],["ECG","abn"]],"opts":["Hypomagnesaemia with refractory hypokalaemia","Isolated hypokalaemia from diuretic therapy","Primary hypoparathyroidism","Hyperkalaemia from a potassium-sparing diuretic"],"c":0,"why":"Magnesium is the cofactor for the sodium-potassium ATPase and is also required for parathyroid hormone release and end-organ response, so a low magnesium drags both potassium and calcium down with it. This is why the potassium keeps failing to correct until the magnesium is replaced first. The ECG shows a prolonged QT interval that can degenerate into torsades de pointes.","week":"1"},{"labs":[["CD4 T-lymphocyte count","down"],["HIV RNA viral load","up"],["CD4 to CD8 ratio","down"],["Total lymphocyte count","down"]],"opts":["Advanced HIV infection meeting AIDS criteria","Acute viral illness with reactive lymphocytosis","Severe combined immunodeficiency","Selective IgA deficiency"],"c":0,"why":"HIV binds the CD4 receptor on helper T cells and destroys them as it replicates, which is why the viral load and the CD4 count move in opposite directions. Losing helper T cells removes the conductor of both cell-mediated and antibody responses, so cytotoxic T cells and B cells are never properly activated. Severe combined immunodeficiency presents in infancy with all lymphocyte lines absent, and IgA deficiency leaves T cell numbers normal.","week":"1"},{"labs":[["White cell count","up"],["Serum lactate","up"],["Procalcitonin","up"],["Arterial pH","down"],["Blood cultures","abn"]],"opts":["Septic shock with lactic acidosis","Anaphylactic shock","Hypovolaemic shock from haemorrhage","Cardiogenic shock"],"c":0,"why":"Bacterial products trigger a cytokine cascade that causes widespread vasodilation and capillary leak, so blood is present in the wrong places and tissue oxygen delivery falls. Cells switch to anaerobic metabolism and lactate accumulates, dragging the pH down. Procalcitonin rises specifically with bacterial infection and positive cultures confirm the source, neither of which occurs in anaphylaxis.","week":"1"},{"labs":[["Complement C3","down"],["Complement C4","down"],["Anti-double-stranded DNA antibody","abn"],["Erythrocyte sedimentation rate","up"],["Serum IgE","n"]],"opts":["Type III immune complex hypersensitivity such as systemic lupus erythematosus","Type I IgE-mediated hypersensitivity","Type IV delayed hypersensitivity","Common variable immunodeficiency"],"c":0,"why":"Soluble antigen-antibody complexes deposit in vessel walls, glomeruli and joints and then fix complement, so C3 and C4 are consumed faster than the liver can replace them. Falling complement with a rising sedimentation rate therefore tracks disease activity. The normal IgE excludes a type I allergic mechanism.","week":"1"},{"labs":[["Pathogen-specific IgM","up"],["Pathogen-specific IgG","n"],["Total white cell count","up"],["C-reactive protein","up"]],"opts":["Acute primary infection during first exposure","Long-standing immunity from a past infection","Artificial passive immunity from an immunoglobulin infusion","Latent infection with no current immune activity"],"c":0,"why":"IgM is the first antibody a naive B cell secretes because it is produced before class switching occurs, so a raised IgM with a still-normal IgG dates the exposure to the current illness and tells you memory has not yet been established. Past infection or a donated immunoglobulin preparation would show the reverse pattern, a raised IgG with a normal IgM.","week":"1"}],"pairs":[{"clue":"Serum sodium 122 with low serum osmolality, urine osmolality 620, urine sodium 55, and a euvolaemic patient with normal skin turgor and no thirst.","a":"Syndrome of inappropriate antidiuretic hormone","b":"Hypovolaemic hyponatraemia from vomiting and diuretics","why":"Volume status plus urine sodium separates them. Water retention in SIADH leaves the patient euvolaemic and switches aldosterone off, so urine sodium stays above 40, whereas true volume depletion turns aldosterone on and drops urine sodium below 20.","week":"1","c":0},{"clue":"Eight litres of urine a day with a urine specific gravity of 1.002 and a serum sodium of 152.","a":"Diabetes insipidus","b":"Syndrome of inappropriate antidiuretic hormone","why":"The direction the sodium moves is the single discriminator. Diabetes insipidus loses free water so the plasma concentrates and sodium rises, while SIADH retains free water so the plasma dilutes and sodium falls.","week":"1","c":0},{"clue":"A serum sodium of 116 present for five days is raised to 132 within 18 hours; two days later the patient develops dysarthria and quadriparesis.","a":"Osmotic demyelination syndrome from over-rapid correction","b":"Cerebral oedema from persisting hyponatraemia","why":"Direction of the sodium change is what decides it. Brain cells had already extruded osmoles to survive chronic hyponatraemia, so raising sodium faster than about eight to ten mEq per litre per day shrinks them and strips myelin; cerebral oedema occurs when sodium is falling, not while it is being corrected upward.","week":"1","c":0},{"clue":"ECG shows flattened T waves, ST depression and prominent U waves in a patient on furosemide.","a":"Hypokalaemia","b":"Hyperkalaemia","why":"The U wave is the tell. A low extracellular potassium makes the resting membrane more negative and prolongs repolarisation, producing U waves, whereas a high potassium partially depolarises the membrane and gives tall peaked T waves with a widening QRS.","week":"1","c":0},{"clue":"Carpopedal spasm develops when the blood pressure cuff is left inflated for three minutes.","a":"Hypocalcaemia","b":"Hypercalcaemia","why":"Ionised calcium stabilises the sodium channels of excitable membranes, so when it falls nerves depolarise spontaneously and give a positive Trousseau sign. A high calcium sedates those membranes instead, producing lethargy, constipation and muscle weakness.","week":"1","c":0},{"clue":"Serum potassium is still 2.9 after three separate potassium replacement infusions.","a":"Hypomagnesaemia causing refractory hypokalaemia","b":"Simple under-dosing of potassium replacement","why":"Magnesium is required for the sodium-potassium ATPase and for closing the renal potassium channels, so without it every dose of replaced potassium is promptly wasted in the urine. Replace the magnesium and the potassium finally holds.","week":"1","c":0},{"clue":"pH 7.30, PaCO2 30, bicarbonate 15 and an anion gap of 10 in a patient with profuse watery diarrhoea.","a":"Normal anion gap metabolic acidosis","b":"High anion gap metabolic acidosis","why":"The anion gap is the discriminator. Diarrhoea loses bicarbonate directly from the gut and chloride is retained to preserve electroneutrality, so the gap stays normal; a widened gap means an unmeasured acid such as ketones or lactate has been added to the blood.","week":"1","c":0},{"clue":"pH 7.48, PaCO2 30, bicarbonate 23 in an anxious patient breathing 32 times a minute.","a":"Acute respiratory alkalosis","b":"Metabolic alkalosis","why":"Identify which value moved in the OPPOSITE direction to the pH, because that value is the primary driver. Here the pH rose while the PaCO2 fell, so the lung is primary and this is a respiratory alkalosis. In a metabolic alkalosis the bicarbonate would move in the SAME direction as the pH and would be the frankly abnormal value; here the bicarbonate is near normal, which confirms the kidney has not yet compensated.","week":"1","c":0},{"clue":"A long-standing COPD patient has pH 7.36, PaCO2 62 and bicarbonate 35 and is alert at his usual mental baseline.","a":"Fully compensated chronic respiratory acidosis","b":"Acute respiratory acidosis requiring immediate ventilation","why":"The pH being back inside the normal range is the discriminator, because only days of renal bicarbonate retention can achieve that. An acute rise in carbon dioxide leaves the pH frankly acidotic with drowsiness, since there has been no time to compensate.","week":"1","c":0},{"clue":"Bilateral pitting leg oedema with ascites, serum albumin 1.8 and heavy proteinuria.","a":"Oedema from reduced plasma oncotic pressure","b":"Oedema from raised capillary hydrostatic pressure","why":"The albumin decides it. Losing albumin removes the inward pull that keeps fluid in the capillary, so filtration exceeds reabsorption throughout the body, while hydrostatic oedema comes from venous congestion or heart failure and occurs with a normal albumin.","week":"1","c":0},{"clue":"Firm, non-pitting swelling of one arm after axillary node dissection, with thickened skin.","a":"Lymphoedema from lymphatic obstruction","b":"Chronic venous insufficiency","why":"Whether the swelling pits is the discriminator, and it reflects protein content. Lymphatics normally return the protein that leaks into the interstitium, so once they are removed the trapped protein holds water in a firm non-pitting mass, whereas venous oedema is protein-poor, pits readily and comes with varicosities and haemosiderin staining.","week":"1","c":0},{"clue":"A newborn is protected against measles for the first six months of life without having been vaccinated.","a":"Natural passive immunity","b":"Natural active immunity","why":"Who made the antibody is the discriminator. The infant received ready-made maternal IgG across the placenta and produced none itself, so there are no memory cells and protection fades as the donated antibody is catabolised.","week":"1","c":0},{"clue":"Erythema, vesicles and intense itching appear 48 hours after nickel earrings are worn.","a":"Type IV delayed hypersensitivity","b":"Type I immediate hypersensitivity","why":"The clock separates them. Type IV is cell mediated, so sensitised T cells and macrophages need one to three days to accumulate at the site, whereas type I is driven by preformed mediators released from mast cells and appears within minutes.","week":"1","c":0},{"clue":"Fifteen minutes into a transfusion the patient develops fever, flank pain and haemoglobinuria.","a":"Type II cytotoxic hypersensitivity","b":"Type III immune complex hypersensitivity","why":"Where the antigen sits is the discriminator. In type II the antibody binds antigen fixed on the red cell surface, so complement lyses those specific cells and the haemoglobin appears in the urine, while type III involves soluble complexes that circulate and deposit at distant sites such as glomeruli and joints days later.","week":"1","c":0},{"clue":"Hypotension with warm flushed skin, urticaria and stridor two minutes after an intravenous cephalosporin.","a":"Anaphylactic shock","b":"Septic shock","why":"Both are distributive, so onset speed and the skin findings decide it. Anaphylaxis follows a specific exposure within minutes and brings urticaria with airway swelling, whereas septic shock evolves over hours with fever, an identifiable source and rising lactate and procalcitonin.","week":"1","c":0},{"clue":"An HIV-positive patient feels well, works full time and has a CD4 count of 180 cells per microlitre.","a":"AIDS","b":"Asymptomatic chronic HIV infection","why":"The CD4 threshold defines the stage, not how the patient feels. A count below 200 cells per microlitre, or the presence of an AIDS-defining illness, is diagnostic even when the patient is entirely well, because cell-mediated defence has already collapsed.","week":"1","c":0},{"clue":"Blood cultures grow Escherichia coli, temperature 38.9, respiratory rate 26, lactate 1.4 and blood pressure 118 over 72.","a":"Bacteraemia without shock","b":"Septic shock","why":"Perfusion is the discriminator. Septic shock requires persisting hypotension needing vasopressors together with a lactate above 2 despite adequate fluid resuscitation, so organisms in the blood with a normal lactate and stable pressure is bacteraemia, not shock.","week":"1","c":0},{"clue":"Temperature 39.2 with shivering and cool peripheries in a patient whose hypothalamic set point has been reset upward.","a":"Fever","b":"Hyperthermia","why":"Whether the set point moved is the discriminator. In fever, pyrogens such as interleukin-1 raise the set point through prostaglandin E2, so the body deliberately generates heat and antipyretics work; in hyperthermia the set point is normal and heat gain simply overwhelms heat loss, so active cooling rather than antipyretics is required.","week":"1","c":0}],"redflags":[{"s":"Serum potassium 6.9 with peaked T waves and a QRS that has widened to 0.14 seconds.","act":1,"why":"Extracellular potassium this high holds the membrane partially depolarised until sodium channels inactivate, so conduction slows toward a sine wave and asystole. Intravenous calcium to stabilise the myocardium is needed within minutes, followed by insulin with glucose to shift potassium back into cells.","week":"1"},{"s":"Serum sodium 117 with a new generalised tonic-clonic seizure.","act":1,"why":"Hypotonic plasma drives water osmotically into neurones, and seizure activity means the swelling brain is now pressing against a fixed skull. Hypertonic saline is given immediately, after which the rate of correction must be capped to avoid osmotic demyelination.","week":"1"},{"s":"Twenty-four hours after thyroidectomy the patient has crowing inspiration and carpopedal spasm.","act":1,"why":"Injury to the parathyroid glands has dropped ionised calcium, and laryngospasm is the airway-threatening extreme of neuromuscular irritability. Intravenous calcium is required before the airway closes completely.","week":"1"},{"s":"Two minutes after an intravenous antibiotic the patient has urticaria, lip swelling, wheeze and a blood pressure of 76 over 40.","act":1,"why":"Mast cell degranulation is producing systemic vasodilation, capillary leak and bronchospasm simultaneously, so both perfusion and the airway are failing. Intramuscular adrenaline reverses all three mechanisms and must not be delayed for antihistamines or steroids.","week":"1"},{"s":"Serum lactate 4.6 with a mean arterial pressure of 58 after 30 mL per kg of crystalloid in a patient with pyelonephritis.","act":1,"why":"A lactate this high with a pressure that will not respond to fluid means oxygen delivery has fallen below cellular demand and metabolism has gone anaerobic. Vasopressors plus cultures and broad-spectrum antibiotics within the first hour are what change survival.","week":"1"},{"s":"ABG pH 7.16, PaCO2 74, PaO2 52 in a patient who has become drowsy and difficult to rouse.","act":1,"why":"Carbon dioxide has risen far faster than the kidney can retain bicarbonate, and the depressed conscious level signals carbon dioxide narcosis with a failing respiratory drive. Ventilatory support is needed before respiratory arrest occurs.","week":"1"},{"s":"Serum sodium has risen from 114 to 130 over the past 14 hours on a hypertonic saline infusion.","act":1,"why":"That is roughly double the safe correction rate of eight to ten mEq per litre in 24 hours, and osmotic demyelination appears a day or two later when it is already irreversible. Stop the infusion now and give free water to bring the total rise back within range.","week":"1"},{"s":"Serum magnesium 1.0 with a QTc of 540 milliseconds and short runs of polymorphic ventricular tachycardia.","act":1,"why":"Magnesium depletion destabilises repolarisation and prolongs the QT, and this rhythm is torsades de pointes, which readily degenerates into ventricular fibrillation. Intravenous magnesium is the immediate treatment regardless of the potassium result.","week":"1"},{"s":"Absolute neutrophil count 0.3 with a single temperature of 38.5 in a patient receiving chemotherapy.","act":1,"why":"Without neutrophils there is no pus, no redness and almost no localising sign, so the usual warning signs of infection are simply absent and colonisation progresses to bacteraemia in hours. Broad-spectrum antibiotics are given within an hour of the fever, before any source is identified.","week":"1"},{"s":"Fever, headache, neck stiffness and a purpuric rash that does not blanch under pressure.","act":1,"why":"A non-blanching rash means blood has already leaked out of vessels, reflecting endotoxin-driven consumptive coagulopathy rather than simple inflammation. Meningococcal disease can progress from this to profound shock within hours.","week":"1"},{"s":"Serum potassium 2.8 in a patient taking digoxin.","act":1,"why":"Potassium and digoxin compete for the same site on the sodium-potassium ATPase, so when potassium falls the drug binds more freely and a therapeutic dose behaves like a toxic one. Life-threatening dysrhythmias can follow, so the potassium must be replaced and the digoxin level checked.","week":"1"},{"s":"Total serum calcium 7.7 with a serum albumin of 2.2 in a patient with no tingling, no spasm and a normal QT interval.","act":0,"why":"About half of circulating calcium travels bound to albumin, so a low albumin lowers the measured total without touching the physiologically active ionised fraction. Correct the value for albumin or measure ionised calcium rather than treating a number that is not causing a deficit.","week":"1"},{"s":"Temperature 38.2 on the second postoperative day with clear lungs, a white cell count of 11.8 and a clean dry wound.","act":0,"why":"This is the expected systemic inflammatory response to surgical tissue injury, where interleukin-1 and interleukin-6 from healing tissue reset the hypothalamic set point without any infection being present. Monitor, encourage deep breathing and mobilisation, and reassess if it climbs or localising signs appear.","week":"1"},{"s":"A long-standing COPD patient has pH 7.35, PaCO2 60, bicarbonate 34 and is alert at his usual baseline.","act":0,"why":"Do not try to normalise his PaCO2, and titrate oxygen to a target saturation of roughly 88 to 92 per cent rather than giving high-flow oxygen. Uncontrolled oxygen in a chronic carbon dioxide retainer worsens ventilation-perfusion matching, blunts the hypoxic drive and pushes the PaCO2 higher, tipping a compensated picture into acute-on-chronic respiratory acidosis.","week":"1"},{"s":"Urine specific gravity 1.030 with dark concentrated urine in an ambulatory patient who has been fasting overnight before a procedure.","act":0,"why":"Concentrated urine here is the kidney working correctly under antidiuretic hormone after a period without intake, not evidence of renal injury. Offer fluids once the fast ends and follow the trend rather than escalating.","week":"1"},{"s":"An itchy erythematous rash confined to where a new antiseptic wipe was applied, appearing 48 hours later, with no wheeze and normal vital signs.","act":0,"why":"The delay of one to three days and the sharp border matching the application site are typical of type IV cell-mediated contact dermatitis, which stays local because it depends on T cells recruited to that spot. Remove the agent and treat symptomatically; it does not progress to airway compromise the way a type I reaction does.","week":"1"}],"chains":[{"title":"Endotoxin to septic shock and multi-organ dysfunction","start":"Gram-negative bacteria release endotoxin into the bloodstream from an untreated urinary source","steps":["Macrophages recognise the endotoxin and pour out tumour necrosis factor alpha, interleukin-1 and interleukin-6 systemically","Widespread nitric oxide production dilates arterioles and makes capillaries leak plasma into the interstitium","Relative hypovolaemia and maldistribution of blood drop the mean arterial pressure below the level needed to perfuse tissue","Cells switch to anaerobic metabolism, so lactate accumulates and a high anion gap lactic acidosis develops","Persistent hypoperfusion combined with microthrombi from disseminated intravascular coagulation produces multi-organ dysfunction"],"why":"This is why sepsis is treated as a perfusion emergency rather than simply an infection: the damage is done by the host's own inflammatory mediators, and lactate is the earliest bedside marker that oxygen delivery has already failed.","week":"1"},{"title":"Re-exposure to allergen to anaphylactic shock","start":"A previously sensitised patient receives a second dose of the same intravenous antibiotic","steps":["The drug cross-links IgE molecules already bound to mast cell and basophil surfaces","Cross-linking triggers degranulation, releasing histamine, leukotrienes and prostaglandins into the circulation","Systemic vasodilation and increased capillary permeability move plasma out of the vascular space into tissues","Bronchial smooth muscle constricts and laryngeal oedema narrows the upper airway","Distributive shock and airway obstruction occur together, collapsing both blood pressure and oxygenation"],"why":"Understanding that sensitisation happened at the first exposure explains why a reaction can be violent on a dose the patient previously tolerated, and why adrenaline, which reverses vasodilation, bronchoconstriction and mediator release at once, is the only first-line drug.","week":"1"},{"title":"Insulin deficiency to ketoacidosis with a falsely reassuring potassium","start":"Absolute insulin deficiency in type 1 diabetes","steps":["Cells cannot take up glucose, so lipolysis accelerates and free fatty acids flood the liver","Hepatic ketogenesis produces beta-hydroxybutyrate and acetoacetate, which are unmeasured anions","Hydrogen ions from these acids consume bicarbonate, so the pH falls and the anion gap widens","Peripheral chemoreceptors in the carotid and aortic bodies sense the rising arterial hydrogen ion concentration and drive deep Kussmaul respirations that blow off carbon dioxide as respiratory compensation.","Hydrogen ions shift into cells in exchange for potassium moving out, so serum potassium reads high while total body potassium is severely depleted"],"why":"The final step is the exam trap and the clinical danger: once insulin therapy pushes potassium back into cells, an apparently high potassium plummets, which is why potassium is replaced early despite the initial number looking safe.","week":"1"},{"title":"Gastric acid loss to metabolic alkalosis with hypokalaemia","start":"Prolonged vomiting or continuous nasogastric suction","steps":["Hydrochloric acid and chloride are lost from the stomach faster than they are replaced","Removing hydrogen ions leaves bicarbonate unopposed, so serum bicarbonate and pH both rise","Fluid loss triggers aldosterone, which drives sodium reabsorption in exchange for potassium and hydrogen excretion in the kidney","Serum potassium falls and the kidney paradoxically excretes acid urine, which maintains rather than corrects the alkalosis","Hypoventilation raises PaCO2 as respiratory compensation while hypokalaemia produces U waves, muscle weakness and dysrhythmias"],"why":"It shows why the alkalosis will not resolve until volume and chloride are restored: as long as aldosterone is switched on the kidney keeps making the problem worse, which is the rationale for saline rather than bicarbonate management.","week":"1"},{"title":"Albumin loss to generalised oedema","start":"Heavy glomerular proteinuria strips albumin out of the plasma","steps":["Plasma oncotic pressure falls because albumin generates most of the inward pull at the capillary","Net filtration now favours movement of fluid out of the capillary into the interstitium along the whole capillary bed","Generalised pitting oedema and ascites develop while circulating intravascular volume actually falls","Reduced renal perfusion activates renin-angiotensin-aldosterone and antidiuretic hormone release","Sodium and water are retained, but with oncotic pressure still low the retained fluid moves straight into the interstitium and the oedema worsens"],"why":"This explains the apparent paradox of a swollen patient who is intravascularly dry, and why giving loop diuretics alone can drop the blood pressure without clearing the oedema.","week":"1"},{"title":"Inappropriate ADH to dilutional hyponatraemia and cerebral oedema","start":"Ectopic or inappropriate antidiuretic hormone secretion, for example from a small cell lung carcinoma or a head injury","steps":["Collecting ducts insert aquaporins and reabsorb water regardless of how dilute the plasma already is","Plasma is diluted, so serum sodium and serum osmolality fall while the urine remains inappropriately concentrated","Extracellular fluid becomes hypotonic relative to the inside of brain cells","Water moves osmotically across neuronal membranes, causing cellular swelling","Rising intracranial pressure produces headache, confusion, seizures and ultimately coma"],"why":"It makes clear that the harm in SIADH comes from tonicity rather than from sodium loss, which is why fluid restriction is the treatment and why correction must be slow once the brain has adapted.","week":"1"},{"title":"HIV entry to AIDS-defining opportunistic infection","start":"HIV binds the CD4 receptor and a co-receptor on a helper T lymphocyte","steps":["Reverse transcriptase copies the viral RNA into DNA, which integrase splices permanently into the host genome","Infected cells produce new virions and are destroyed, so the CD4 count falls as the viral load climbs","Loss of helper T cells removes the signals that activate cytotoxic T cells and macrophages and that drive B cell class switching","Once the CD4 count falls below 200 cells per microlitre, cell-mediated defence is no longer able to contain intracellular organisms","Opportunistic infections such as Pneumocystis pneumonia and AIDS-defining malignancies emerge"],"why":"Tracking the inverse relationship between CD4 count and viral load explains both why antiretroviral therapy is monitored with those two numbers and why prophylaxis is started at specific CD4 thresholds rather than when symptoms appear.","week":"1"}]},"2":{"labs":[{"labs":[["Serum potassium","up"],["Serum phosphate","up"],["Serum uric acid","up"],["Serum calcium","down"],["Creatinine","up"]],"opts":["Tumour lysis syndrome","Humoral hypercalcaemia of malignancy","Paraneoplastic SIADH","Chemotherapy-induced myelosuppression"],"c":0,"why":"Cytotoxic therapy ruptures a large tumour burden all at once, spilling intracellular potassium, phosphate and nucleic acids into the blood, and the nucleic acids are catabolised to uric acid. The released phosphate binds serum calcium, so calcium falls while everything else rises, and urate plus calcium-phosphate crystals then obstruct the renal tubules, which is why creatinine climbs.","week":"2"},{"labs":[["Serum calcium","up"],["Intact parathyroid hormone","down"],["PTH-related peptide","up"],["Serum phosphate","down"]],"opts":["Humoral hypercalcaemia of malignancy","Primary hyperparathyroidism","Tumour lysis syndrome","Ectopic ACTH syndrome"],"c":0,"why":"A squamous tumour secretes PTH-related peptide, which acts on PTH receptors to pull calcium out of bone and waste phosphate in the urine, and the rising calcium then suppresses the parathyroid glands by negative feedback. Suppressed intact PTH alongside a high calcium is the discriminator, because primary hyperparathyroidism keeps PTH inappropriately high.","week":"2"},{"labs":[["Serum sodium","down"],["Serum osmolality","down"],["Urine osmolality","up"],["Urine sodium","up"]],"opts":["Paraneoplastic SIADH from small cell lung cancer","Diabetes insipidus","Hypovolaemic hyponatraemia from vomiting","Psychogenic polydipsia"],"c":0,"why":"Ectopic ADH from the tumour forces the collecting duct to reabsorb free water, diluting the plasma while the kidney continues to excrete sodium normally, so the urine stays concentrated and sodium-rich in the face of dilute blood. Hypovolaemic hyponatraemia would instead show a low urine sodium because aldosterone is conserving it, and diabetes insipidus would give dilute urine with a high serum sodium.","week":"2"},{"labs":[["Plasma ACTH","up"],["Serum cortisol","up"],["Serum potassium","down"],["Serum bicarbonate","up"],["Blood glucose","up"]],"opts":["Ectopic ACTH secretion by small cell lung cancer","Adrenal cortical adenoma","Addison disease","Septic shock"],"c":0,"why":"Tumour-derived ACTH is not subject to cortisol negative feedback, so ACTH and cortisol rise together instead of moving in opposite directions. The very high cortisol load spills onto mineralocorticoid receptors and drives renal potassium and hydrogen loss, producing hypokalaemic metabolic alkalosis, while its gluconeogenic effect raises glucose.","week":"2"},{"labs":[["Arterial pH","up"],["PaCO2","down"],["Serum bicarbonate","n"],["Serum lactate","up"],["White cell count","up"]],"opts":["Early sepsis with respiratory alkalosis","Established septic shock with metabolic acidosis","Diabetic ketoacidosis","Opioid-induced respiratory depression"],"c":0,"why":"Circulating cytokines and fever stimulate the respiratory centre before acid has accumulated, so the patient blows off carbon dioxide and the pH rises. The still-normal bicarbonate alongside an already rising lactate is the clue that this is the early compensated phase rather than decompensated shock.","week":"2"},{"labs":[["Serum lactate","up"],["Arterial pH","down"],["Serum bicarbonate","down"],["Procalcitonin","up"],["Creatinine","up"]],"opts":["Septic shock with tissue hypoperfusion","Cardiogenic shock","Anaphylactic shock","Neurogenic shock"],"c":0,"why":"Once vasodilation and capillary leak drop the mean arterial pressure below the level that perfuses capillary beds, cells switch to anaerobic glycolysis and lactic acid consumes bicarbonate, so pH falls and creatinine rises with renal hypoperfusion. Procalcitonin rises specifically with bacterial infection, which separates this distributive picture from the other shock states.","week":"2"},{"labs":[["Platelet count","down"],["Prothrombin time","up"],["Activated partial thromboplastin time","up"],["Fibrinogen","down"],["D-dimer","up"]],"opts":["Disseminated intravascular coagulation","Immune thrombocytopenic purpura","Heparin-induced thrombocytopenia","Vitamin K deficiency"],"c":0,"why":"Sepsis makes endothelium and monocytes express tissue factor, so thrombin is generated throughout the circulation; the resulting microthrombi consume platelets and clotting factors, lengthening both clotting times and dropping fibrinogen. Secondary fibrinolysis then liberates D-dimer, and it is this combination of consumption plus fibrinolysis that no other thrombocytopenia reproduces.","week":"2"},{"labs":[["CSF amyloid beta-42","down"],["CSF total tau","up"],["CSF phosphorylated tau","up"],["CSF white cell count","n"],["CSF oligoclonal bands","n"]],"opts":["Alzheimer disease","Multiple sclerosis","Bacterial meningitis","Parkinson disease"],"c":0,"why":"Amyloid beta-42 falls in the CSF because it is being sequestered into insoluble plaques in the brain instead of remaining in solution, while tau rises as dying neurons release their hyperphosphorylated cytoskeletal protein. The normal cell count and absent oligoclonal bands exclude the inflammatory and infectious mimics.","week":"2"},{"labs":[["CSF oligoclonal bands","abn"],["CSF IgG index","up"],["CSF protein","up"],["CSF glucose","n"],["CSF white cell count","up"]],"opts":["Multiple sclerosis","Guillain-Barre syndrome","Bacterial meningitis","Amyotrophic lateral sclerosis"],"c":0,"why":"Clones of B cells trapped behind the blood-brain barrier manufacture immunoglobulin inside the central nervous system, so bands appear in the CSF that are not present in serum and the IgG index rises, with a mild lymphocytosis reflecting autoimmune demyelination. Bacterial meningitis would drop the glucose, and Guillain-Barre raises protein with a normal cell count and no bands.","week":"2"},{"labs":[["ALT","up"],["AST","up"],["Alkaline phosphatase","n"],["INR","up"],["Serum ammonia","up"]],"opts":["Free-radical hepatocellular necrosis from paracetamol overdose","Alcoholic hepatitis","Obstructive biliary disease","Metastatic liver disease"],"c":0,"why":"When the conjugation pathways saturate, paracetamol is oxidised to the reactive metabolite NAPQI, which exhausts glutathione and then attacks hepatocyte proteins and lipids as a free radical, causing centrilobular necrosis. The massive transaminase leak with a normal alkaline phosphatase points to hepatocellular death rather than obstruction, and the rising INR and ammonia show synthetic and detoxifying function has been lost.","week":"2"},{"labs":[["Absolute neutrophil count","down"],["Platelet count","down"],["Haemoglobin","down"],["Reticulocyte count","down"],["Temperature","up"]],"opts":["Chemotherapy-induced myelosuppression with febrile neutropenia","Acute leukaemia","Disseminated intravascular coagulation","Iron deficiency anaemia"],"c":0,"why":"Cytotoxic drugs kill any rapidly dividing cell and bone marrow precursors divide fastest, so all three lines fall together and the low reticulocyte count proves the marrow is not responding rather than being consumed peripherally. Neutrophils drop first because they have the shortest circulating life, which is why a fever at the nadir is an emergency and not a laboratory curiosity.","week":"2"},{"labs":[["Upper motor neuron signs","abn"],["Lower motor neuron signs","abn"],["Sensory examination","n"],["Cognition","n"],["Electromyography","abn"]],"opts":["Amyotrophic lateral sclerosis","Multiple sclerosis","Guillain-Barre syndrome","Myasthenia gravis"],"c":0,"why":"The disease destroys motor neurons in both the corticospinal tracts and the anterior horn, so spasticity and hyperreflexia coexist with wasting and fasciculations in the same patient. Sensory pathways and higher cortical function are spared, and that preserved sensation is the single finding that separates it from demyelinating disease.","week":"2"},{"labs":[["Serum troponin I","up"],["Creatine kinase-MB","up"],["Lactate dehydrogenase","up"],["White cell count","up"],["C-reactive protein","up"]],"opts":["Irreversible injury with coagulative necrosis","Physiological apoptosis","Reversible hydropic cell swelling","Cellular atrophy"],"c":0,"why":"Intracellular proteins only reach the bloodstream once the plasma membrane has actually failed, so a measurable enzyme leak marks the crossing from reversible to irreversible injury. Apoptosis packages its contents into membrane-bound bodies for phagocytosis, which is why it produces neither enzyme release nor the inflammatory response seen here.","week":"2"}],"pairs":[{"clue":"A long-term smoker's bronchial biopsy shows ciliated columnar epithelium replaced by orderly, mature stratified squamous epithelium with uniform nuclei.","a":"Metaplasia","b":"Dysplasia","why":"Metaplasia swaps one fully differentiated adult cell type for another that better tolerates the chronic stress, and the replacement cells remain uniform and mature. Dysplasia would show disordered growth with enlarged, hyperchromatic nuclei of variable size and shape.","week":"2","c":0},{"clue":"The left ventricular wall thickens over years of untreated hypertension, but the number of muscle cells is unchanged.","a":"Hypertrophy","b":"Hyperplasia","why":"Cardiac myocytes are permanent cells that have exited the cell cycle, so the only way to meet increased workload is to enlarge existing cells by synthesising more contractile protein. Hyperplasia requires a tissue still capable of mitosis, which cardiac muscle is not.","week":"2","c":0},{"clue":"A cervical biopsy shows atypical, disordered cells occupying only the lower third of the epithelium, the basement membrane is intact, and the changes regress once the causative infection clears.","a":"Dysplasia","b":"Carcinoma in situ","why":"Dysplasia is partial-thickness atypia that is still potentially reversible when the driving stimulus is removed. Carcinoma in situ is full-thickness atypia that no longer regresses, although it too has not yet breached the basement membrane.","week":"2","c":0},{"clue":"Injured cells swell, rupture, and spill their contents, drawing neutrophils into the surrounding tissue.","a":"Necrosis","b":"Apoptosis","why":"Necrosis is unregulated death following ATP failure, so membranes fail and the escaping intracellular contents act as danger signals that recruit inflammation. Apoptosis is ATP-dependent and parcels the cell into membrane-bound bodies that are quietly phagocytosed, so no inflammatory response occurs.","week":"2","c":0},{"clue":"Three days after a myocardial infarction the dead tissue is firm and pale, yet the outlines of the muscle fibres can still be recognised.","a":"Coagulative necrosis","b":"Liquefactive necrosis","why":"Ischaemic acidosis denatures the lysosomal enzymes along with the structural proteins, so digestion is blocked and the tissue architecture survives as a ghost outline. Liquefactive necrosis occurs where hydrolytic enzymes dominate, as in brain infarcts and abscesses, leaving a soft liquid mass.","week":"2","c":0},{"clue":"A cell shows swollen mitochondria and plasma membrane blebbing, but no membrane breaks and no calcium-dense deposits, and it returns to normal once blood flow is restored.","a":"Reversible cell injury","b":"Irreversible cell injury","why":"Reversible injury is essentially an ATP shortage that lets sodium and water into the cell, and it corrects the moment oxygen supply resumes. Irreversibility begins with true membrane rupture and massive calcium entry, at which point enzymes leak out and the cell cannot be salvaged.","week":"2","c":0},{"clue":"The pathology report describes how closely the tumour cells still resemble the tissue they arose from.","a":"Grading","b":"Staging","why":"Grade measures differentiation, that is how far the cells have drifted microscopically from the parent tissue. Staging measures anatomical extent through tumour size, nodal involvement and metastasis, and it is generally the stronger predictor of survival and the driver of treatment choice.","week":"2","c":0},{"clue":"A single mutated copy of the gene is sufficient, because the mutation leaves the protein permanently switched on and driving proliferation.","a":"Oncogene","b":"Tumour suppressor gene","why":"Oncogenes act by gain of function, so one altered allele behaves dominantly and is enough to accelerate growth. Tumour suppressors such as TP53 and BRCA act as brakes, so both alleles must be lost before control is released, which is the two-hit requirement.","week":"2","c":0},{"clue":"A slow-growing thyroid nodule is encapsulated and well differentiated, and it compresses adjacent tissue without invading it.","a":"Benign neoplasm","b":"Malignant neoplasm","why":"A fibrous capsule and preserved differentiation show the cells still respect their tissue boundary and expand rather than infiltrate. Malignancy is defined by invasion through that boundary and the capacity to metastasise, not simply by how fast the mass grows.","week":"2","c":0},{"clue":"A patient with osteosarcoma of the femur is found to have multiple lung nodules while the regional lymph nodes are clear.","a":"Haematogenous spread","b":"Lymphatic spread","why":"Sarcomas arise in connective tissue rich in thin-walled veins, so cells enter the venous return and lodge in the first capillary bed they reach, which for a limb tumour is the lung. Carcinomas of epithelial origin classically travel through lymphatics to regional nodes first.","week":"2","c":0},{"clue":"A patient with small cell lung cancer develops a serum sodium of 118 mmol/L with concentrated urine, and the brain MRI is normal.","a":"Paraneoplastic SIADH","b":"Hyponatraemia from cerebral metastasis","why":"The tumour cells themselves secrete ADH ectopically, so the effect is produced chemically at a distance and a clear brain scan does not exclude it. That remote hormonal mechanism is precisely what defines a paraneoplastic syndrome and separates it from local or metastatic tumour effects.","week":"2","c":0},{"clue":"Two days after multi-trauma surgery a patient has a temperature of 38.5 C, heart rate 110 and white cell count 15, but all cultures are negative and no source is found.","a":"Systemic inflammatory response syndrome","b":"Sepsis","why":"SIRS is the cytokine response itself and can be triggered by trauma, burns, pancreatitis or major surgery with no organism involved at all. Sepsis requires that the dysregulated response be driven by infection and be producing organ dysfunction.","week":"2","c":0},{"clue":"After 30 mL/kg of crystalloid the mean arterial pressure is still 58 mmHg on noradrenaline and the lactate is 4.1 mmol/L.","a":"Septic shock","b":"Sepsis without shock","why":"Septic shock is defined by circulatory and metabolic failure that persists after adequate fluid resuscitation, evidenced by vasopressor dependence together with a raised lactate. Sepsis alone still causes organ dysfunction, but its perfusion deficit corrects with fluid alone.","week":"2","c":0},{"clue":"A patient with diabetes describes burning, electric shock-like pain in both feet in a stocking distribution that barely responds to opioids but improves on gabapentin.","a":"Neuropathic pain","b":"Nociceptive pain","why":"Neuropathic pain is generated by damage to the nerve itself, producing ectopic impulses in a nerve distribution rather than stimulation of intact nociceptors, which is why membrane-stabilising drugs work and opioids largely do not. Nociceptive pain is aching or throbbing, follows identifiable tissue injury and responds well to opioids.","week":"2","c":0},{"clue":"A man having a myocardial infarction feels the pain in his left jaw and inner arm, and the chest wall itself is not tender.","a":"Referred pain","b":"Radiating pain","why":"Visceral afferents from the heart converge on the same dorsal horn neurons as somatic afferents from the jaw and arm dermatomes, so the brain misattributes the origin to the skin area sharing that spinal segment. Radiating pain instead travels outward along the anatomical course of a nerve from the original site.","week":"2","c":0},{"clue":"Six weeks after a below-knee amputation the patient describes cramping pain in the toes, while the surgical site is clean, soft and non-tender.","a":"Phantom limb pain","b":"Residual limb (stump) pain","why":"Phantom pain arises centrally from ectopic firing in the severed nerves and cortical remapping of the deafferented limb area, so it is perceived in tissue that no longer exists. Stump pain is local nociceptive pain from the wound, a neuroma or prosthesis pressure, and the stump itself would be tender.","week":"2","c":0},{"clue":"The tremor is worst when the hands rest in the lap, settles as the patient reaches for a cup, and comes with micrographia and a shuffling gait.","a":"Parkinson disease","b":"Essential tremor","why":"Degeneration of dopaminergic neurons in the substantia nigra leaves acetylcholine unopposed in the basal ganglia, producing a resting pill-rolling tremor with bradykinesia and rigidity. Essential tremor is an action tremor that appears with movement, spares gait and posture, and often improves briefly with alcohol.","week":"2","c":0},{"clue":"An 82-year-old with two years of steadily worsening short-term memory loss remains alert, attentive and oriented to the ward routine.","a":"Alzheimer disease","b":"Delirium","why":"Alzheimer disease progresses insidiously over months to years and attention is preserved until late, because the earliest damage is to hippocampal memory encoding. Delirium develops over hours to days with fluctuating consciousness and inattention as its defining feature, and it reverses when the underlying cause is treated.","week":"2","c":0}],"redflags":[{"s":"Day 10 after chemotherapy the patient has a temperature of 38.6 C and an absolute neutrophil count of 0.3.","act":1,"why":"Without neutrophils there is no pus and no localising sign, so fever may be the only warning before gram-negative bacteraemia. Blood cultures and broad-spectrum antibiotics within the first hour are what change survival.","week":"2"},{"s":"Mean arterial pressure 56 mmHg and lactate 4.4 mmol/L in a patient with pyelonephritis, unchanged after 30 mL/kg of fluid.","act":1,"why":"Hypotension and hyperlactataemia persisting after adequate fluid resuscitation define septic shock, meaning cells have already switched to anaerobic metabolism. Vasopressors and source control are needed now because organ damage accumulates minute by minute.","week":"2"},{"s":"A woman with metastatic breast cancer reports new severe mid-back pain with leg weakness and difficulty starting urination.","act":1,"why":"This is metastatic spinal cord compression, and cord ischaemia becomes irreversible within hours. Corticosteroids and urgent imaging are required before the deficit progresses to permanent paraplegia and neurogenic bladder.","week":"2"},{"s":"Twenty-four hours after starting chemotherapy for a bulky lymphoma the potassium is 6.5 mmol/L with rising phosphate and falling urine output.","act":1,"why":"Tumour lysis has released intracellular potassium into the circulation faster than an obstructed kidney can excrete it. At this level hyperkalaemia can produce ventricular arrhythmia and cardiac arrest with no further warning.","week":"2"},{"s":"A patient with squamous cell lung cancer has a corrected calcium of 3.6 mmol/L with confusion, polyuria and vomiting.","act":1,"why":"PTHrP-driven hypercalcaemia at this level causes an osmotic diuresis with profound dehydration, arrhythmia and depressed consciousness. Aggressive saline rehydration followed by a bisphosphonate is required rather than observation.","week":"2"},{"s":"A man with a mediastinal mass develops facial and upper limb swelling, distended neck veins and stridor when lying flat.","act":1,"why":"The tumour is obstructing the superior vena cava and now compromising the airway, so venous return from the head and ventilation are both threatened. This is one of the genuine oncological airway emergencies and needs immediate imaging and treatment.","week":"2"},{"s":"A septic patient is oozing from every cannula site with platelets of 38, a prolonged prothrombin time and a fibrinogen of 0.8 g/L.","act":1,"why":"Systemic thrombin generation has consumed the clotting factors and platelets, so the patient is thrombosing microvessels and bleeding at the same time. The coagulopathy will not settle until the septic source driving tissue factor expression is controlled.","week":"2"},{"s":"A patient with ALS has increasing orthopnoea, morning headaches and a forced vital capacity that has fallen below 50 percent of predicted.","act":1,"why":"Diaphragmatic weakness is causing nocturnal hypoventilation and carbon dioxide retention, which is why the headaches occur on waking. Untreated this progresses to respiratory arrest, and non-invasive ventilation is both urgent and the intervention that most prolongs life.","week":"2"},{"s":"A hospitalised patient with Parkinson disease is kept nil by mouth and misses 36 hours of levodopa, then becomes rigid and febrile with a creatine kinase of 4000.","act":1,"why":"Abrupt dopaminergic withdrawal can precipitate a parkinsonism-hyperpyrexia syndrome that behaves like neuroleptic malignant syndrome, with rhabdomyolysis and acute kidney injury. Dopaminergic therapy must be reinstated by an alternative route without delay.","week":"2"},{"s":"An 84-year-old nursing home resident has a temperature of 36.1 C, new confusion, mottled knees and a capillary refill of 4 seconds.","act":1,"why":"Older adults often mount no fever, so hypothermia and altered mentation are the sepsis presentation in this age group. Mottling and delayed refill already show failing peripheral perfusion, so waiting for a fever wastes the treatable window.","week":"2"},{"s":"A patient receiving doxorubicin passes red-orange urine on the day of the infusion, and the urinalysis shows no red cells.","act":0,"why":"The colour is the drug pigment itself being excreted, not blood, and it clears within one to two days. Explanation and reassurance are the correct response, and escalating it diverts attention from real complications such as cardiotoxicity.","week":"2"},{"s":"A 40-pack-year smoker's bronchial biopsy shows squamous metaplasia with no dysplasia or atypia.","act":0,"why":"Metaplasia is an adaptive and potentially reversible response to chronic irritation, and removing the stimulus can allow the normal epithelium to return. It signals raised long-term risk that warrants cessation support and surveillance rather than emergency intervention.","week":"2"},{"s":"A woman four weeks after mastectomy describes an intermittent tingling sensation of the removed breast, with a well-healed scar and no fever.","act":0,"why":"This is phantom sensation arising from the intact cortical representation of tissue that has been removed, and it is common and usually fades. It calls for explanation and reassurance, not investigation for recurrence or infection.","week":"2"},{"s":"A patient with moderate Alzheimer disease becomes agitated and restless every evening around dusk, in a pattern unchanged for several months.","act":0,"why":"Stable sundowning reflects the loss of circadian and cortical regulation in established disease and is managed environmentally with light, routine and orientation. An abrupt change in that established pattern would instead suggest superimposed delirium and would demand a search for infection, pain or hypoxia.","week":"2"}],"chains":[{"title":"Ischaemic cell death: reversible swelling to coagulative necrosis","start":"A thrombus occludes a coronary artery and oxygen delivery to the myocardium stops.","steps":["Oxidative phosphorylation halts and cellular ATP falls within minutes.","The ATP-dependent sodium-potassium pump fails, so sodium and water move into the cell and it swells, a stage that is still reversible.","Anaerobic glycolysis takes over, lactic acid accumulates and intracellular pH falls, causing chromatin clumping and detachment of ribosomes.","Lysosomal membranes rupture and calcium floods the cytosol, activating proteases, phospholipases and endonucleases.","Membrane integrity is lost, troponin and other enzymes leak into the blood, and the tissue becomes coagulative necrosis that provokes acute inflammation."],"why":"The entire clinical window sits between the second and fourth steps: reperfusion before membrane rupture salvages myocardium, whereas the appearance of enzymes in the blood is the bedside signal that the point of no return has already been crossed.","week":"2"},{"title":"Reperfusion and free radical injury","start":"Blood flow is restored to ischaemic myocardium after successful thrombolysis.","steps":["Oxygen returns to mitochondria that are already damaged and leaks electrons, generating superoxide and hydrogen peroxide.","These reactive species peroxidise membrane phospholipids and oxidise proteins and DNA faster than glutathione and superoxide dismutase can neutralise them.","The damaged membranes allow extracellular calcium to pour in, activating enzymes that degrade the cytoskeleton and remaining mitochondria.","Neutrophils drawn to the injury release their own oxidants and proteases, amplifying the damage.","The final infarct is larger than the area that was originally ischaemic."],"why":"It explains the paradox students find counter-intuitive, that restoring perfusion can extend the injury; the free radical burst rather than the ischaemia itself causes this extra layer of damage, which is why antioxidant capacity and controlled reperfusion matter clinically.","week":"2"},{"title":"Carcinogenesis: one mutation to invasive carcinoma","start":"A chemical carcinogen in tobacco smoke forms a DNA adduct in a bronchial epithelial cell.","steps":["The damage escapes repair and is fixed permanently into the genome when the cell next divides.","A proto-oncogene is converted into a constitutively active oncogene, so the cell proliferates without any external growth signal.","Both alleles of a tumour suppressor gene such as TP53 are subsequently lost, removing cell-cycle arrest and the apoptosis of damaged cells.","The unchecked clone accumulates further mutations and reactivates telomerase, becoming effectively immortal, and the epithelium progresses from dysplasia to carcinoma in situ.","The clone breaches the basement membrane and becomes an invasive carcinoma."],"why":"It shows why cancer requires multiple hits over years rather than a single event: the accelerator must be jammed on and the brakes must be cut, and loss of TP53 is the step that allows every earlier mutation to survive instead of being deleted.","week":"2"},{"title":"The metastatic cascade","start":"A malignant clone in a breast duct loses expression of the adhesion molecule E-cadherin.","steps":["The cells detach from one another and secrete matrix metalloproteinases that digest the basement membrane and surrounding stroma.","The tumour secretes angiogenic factors such as VEGF, growing a new capillary network that both feeds it and provides an escape route.","Cells intravasate into lymphatics and thin-walled venules and are carried to the first draining node or capillary bed.","Surviving cells adhere to distant endothelium, extravasate into the tissue and establish a supportive microenvironment.","The deposit proliferates at the secondary site, for example in bone, where osteolysis produces hypercalcaemia and pathological fracture."],"why":"Each step is a separate barrier the tumour must defeat, which is why metastasis is inefficient and occurs late; it also explains why a distant complication such as hypercalcaemia or a pathological fracture can be the first symptom of a primary tumour that was never noticed.","week":"2"},{"title":"Sepsis to septic shock to multiple organ dysfunction","start":"Gram-negative bacteria and their endotoxin enter the bloodstream from an infected urinary tract.","steps":["Bacterial molecular patterns bind toll-like receptors on macrophages, which release tumour necrosis factor alpha, interleukin-1 and interleukin-6.","These cytokines induce nitric oxide, producing widespread vasodilation and endothelial injury with increased capillary permeability.","Plasma leaks into the interstitium so preload and systemic vascular resistance fall together, and mean arterial pressure drops despite a high cardiac output.","Injured endothelium expresses tissue factor, triggering widespread microthrombi that consume platelets and clotting factors and further obstruct capillary flow.","Cells deprived of oxygen switch to anaerobic metabolism, lactate rises and the kidneys, lungs, liver and brain fail in sequence."],"why":"It shows that the damage in sepsis is inflicted by the host response rather than by the organism, which is why antibiotics alone do not reverse shock and why fluids, vasopressors and source control each target a different step in this same chain.","week":"2"},{"title":"Nerve transection to phantom limb pain","start":"Peripheral nerves are cut during a below-knee amputation.","steps":["The severed axons sprout disorganised endings that form a neuroma studded with abnormal sodium channels.","These channels fire spontaneously, sending continuous ectopic impulses into the dorsal horn of the spinal cord.","Sustained C-fibre input activates NMDA receptors in the dorsal horn, lowering the threshold of second-order neurons and producing central sensitisation.","The somatosensory cortex remaps, with neighbouring body areas invading the territory that used to represent the amputated limb.","Pain is consciously perceived in a limb that no longer exists and responds poorly to opioids."],"why":"The chain explains why this pain is physiologically real rather than imagined and why it must be treated centrally; once the generator has moved from tissue to cord and cortex, peripheral analgesia has nothing left to act on, which is the rationale for anticonvulsants, antidepressants and mirror therapy.","week":"2"},{"title":"Alzheimer disease from amyloid to cognitive decline","start":"Amyloid precursor protein is cleaved by beta and gamma secretase instead of by the normal non-amyloidogenic pathway.","steps":["The insoluble amyloid beta-42 fragment aggregates outside the neuron into neuritic plaques.","The plaques trigger chronic microglial activation, oxidative stress and injury to the surrounding synapses.","Inside the neuron, tau protein becomes hyperphosphorylated, detaches from microtubules and collapses into neurofibrillary tangles, so axonal transport fails.","Neurons die, beginning in the hippocampus and the cholinergic nucleus basalis, and acetylcholine levels fall.","The hippocampus and cortex atrophy, producing short-term memory loss first and then global cognitive and functional decline."],"why":"It orders the pathology in the sequence the symptoms appear and explains both drug classes: cholinesterase inhibitors prop up the failing acetylcholine of the fourth step and memantine blunts the glutamate excitotoxicity accompanying the same neuronal loss, while neither removes the plaque and tangle burden already laid down.","week":"2"}]},"3":{"labs":[{"labs":[["Serum calcium 8.1","down"],["Serum phosphate 2.1","down"],["Alkaline phosphatase 340","up"],["Parathyroid hormone","up"],["25-hydroxy vitamin D 9","down"]],"opts":["Osteoporosis","Osteomalacia","Osteoarthritis","Paget disease of bone"],"c":1,"why":"Without vitamin D, calcium and phosphate cannot be absorbed from the gut, so newly laid osteoid is never mineralized. The falling calcium drives a compensatory rise in parathyroid hormone, which wastes phosphate in the urine, and the frantic osteoblast activity pushes alkaline phosphatase up. Osteoporosis loses bone quantity rather than mineral, so its chemistry stays normal.","week":"3"},{"labs":[["Serum calcium","n"],["Serum phosphate","n"],["Alkaline phosphatase","n"],["DEXA T-score -3.1","abn"]],"opts":["Osteomalacia","Primary hyperparathyroidism","Osteoporosis","Multiple myeloma"],"c":2,"why":"Normal chemistry with an abnormal bone density scan is the whole signature. Resorption outpaces formation so there is less bone, but what remains is fully mineralized and nothing spills into the serum. Hyperparathyroidism would raise calcium and lower phosphate, and myeloma would raise calcium alongside anemia and renal impairment.","week":"3"},{"labs":[["Creatine kinase 48,000","up"],["Serum potassium 6.3","up"],["Serum calcium 7.2","down"],["Creatinine 2.4","up"],["Urine dipstick positive for blood with no red cells on microscopy","abn"]],"opts":["Rhabdomyolysis with acute kidney injury","Acute compartment syndrome without muscle necrosis","Fat embolism syndrome","Acute hemolytic transfusion reaction"],"c":0,"why":"Lysed myocytes dump potassium, phosphate and creatine kinase into the blood, and the released phosphate binds serum calcium so calcium falls. Filtered myoglobin forms casts that obstruct the tubules, raising creatinine. Myoglobin reacts on the dipstick as blood, so a positive dipstick with no red cells under the microscope is the discriminator.","week":"3"},{"labs":[["PaO2 52 on room air","down"],["Platelets 88,000","down"],["Hemoglobin 9.4","down"],["Chest film with diffuse bilateral infiltrates","abn"],["Fat globules in the urine","abn"]],"opts":["Pulmonary embolism from deep vein thrombosis","Aspiration pneumonia","Fat embolism syndrome","Tension pneumothorax"],"c":2,"why":"Marrow fat entering torn venous sinusoids at the fracture site is hydrolyzed to free fatty acids, which injure the alveolar-capillary membrane and produce a chemical pneumonitis, giving hypoxemia with bilateral infiltrates. Those same fatty acids trigger platelet aggregation and red cell clumping, so platelets and hemoglobin fall, which a simple venous clot does not cause.","week":"3"},{"labs":[["Serum uric acid 9.8","up"],["Synovial fluid with needle-shaped, negatively birefringent crystals","abn"],["Synovial white cell count 22,000","up"],["Synovial Gram stain negative","n"],["ESR","up"]],"opts":["Septic arthritis","Pseudogout","Gout","Rheumatoid arthritis"],"c":2,"why":"Crystal shape and birefringence settle it: monosodium urate forms needles that are negatively birefringent, whereas calcium pyrophosphate forms rhomboids that are positively birefringent. The synovial count is inflammatory but well under the 50,000 typical of infection, and the negative Gram stain argues against sepsis even though the joint looks infected.","week":"3"},{"labs":[["Rheumatoid factor","up"],["Anti-cyclic citrullinated peptide antibody","up"],["ESR 68","up"],["C-reactive protein","up"],["Hemoglobin 10.2 with normal cell size","down"]],"opts":["Osteoarthritis","Rheumatoid arthritis","Gout","Fibromyalgia"],"c":1,"why":"Anti-CCP is the specific marker because citrullinated self-proteins in the synovium are the antigen that starts the disease. The resulting immune complexes activate complement and release cytokines that raise ESR and CRP and suppress erythropoiesis, producing the normocytic anemia of chronic inflammation. Osteoarthritis is mechanical wear and generates none of these systemic markers.","week":"3"},{"labs":[["ESR","n"],["C-reactive protein","n"],["Rheumatoid factor","n"],["Synovial white cell count 900","n"],["Radiograph with joint space narrowing, osteophytes and subchondral sclerosis","abn"]],"opts":["Rheumatoid arthritis","Septic arthritis","Osteoarthritis","Systemic lupus erythematosus"],"c":2,"why":"Everything systemic is normal and only the film is abnormal, which is the point of this pattern. Osteoarthritis begins as cartilage failure under mechanical load rather than immune attack, so there is minimal synovitis and no acute phase response. The osteophytes and subchondral sclerosis are the attempts of bone to repair itself after losing its cartilage cushion.","week":"3"},{"labs":[["CSF opening pressure 320 mm H2O","up"],["CSF white cells 4,200 with 90 percent neutrophils","up"],["CSF protein 220","up"],["CSF glucose 22 with serum glucose 110","down"]],"opts":["Viral (aseptic) meningitis","Subarachnoid hemorrhage","Guillain-Barre syndrome","Bacterial meningitis"],"c":3,"why":"Bacteria consume glucose and provoke a neutrophil flood, so a low CSF glucose with neutrophil predominance is the discriminator. Viruses do not metabolize CSF glucose, so aseptic meningitis shows lymphocytes with a normal glucose. Guillain-Barre gives a high protein with almost no cells, the albuminocytologic dissociation.","week":"3"},{"labs":[["CSF opening pressure","up"],["CSF red cell count equal in tubes one and four","abn"],["Xanthochromia present in the supernatant","abn"],["CSF glucose","n"],["CSF white cells mildly raised","up"]],"opts":["Traumatic lumbar puncture","Subarachnoid hemorrhage","Bacterial meningitis","Ischemic stroke"],"c":1,"why":"A traumatic tap bleeds progressively less, so red cells clear from the first tube to the last and there has been no time for pigment to develop. In subarachnoid hemorrhage the blood has been circulating in the CSF for hours, so the count stays constant and hemoglobin has already broken down to bilirubin, producing the yellow xanthochromia. The normal glucose separates it from bacterial meningitis.","week":"3"},{"labs":[["Serum sodium 118","down"],["Serum osmolality 248","down"],["Urine osmolality 620","up"],["Urine sodium 70","up"],["Body weight and blood pressure unchanged","n"]],"opts":["Cerebral salt wasting","Central diabetes insipidus","Syndrome of inappropriate antidiuretic hormone","Adrenal insufficiency"],"c":2,"why":"Injured hypothalamic tissue releases antidiuretic hormone regardless of plasma osmolality, so water is retained while renal sodium handling stays intact, producing dilute blood with concentrated urine in a patient who is euvolemic. Cerebral salt wasting yields the same low sodium but with volume depletion, weight loss and high urine output, which is why volume status, not the sodium value, decides whether to restrict fluid or give saline.","week":"3"},{"labs":[["Urine output 420 mL per hour","up"],["Urine specific gravity 1.002","down"],["Serum sodium 152","up"],["Serum osmolality 312","up"]],"opts":["Syndrome of inappropriate antidiuretic hormone","Cerebral salt wasting","Hyperglycemic osmotic diuresis","Central diabetes insipidus"],"c":3,"why":"Rising intracranial pressure or pituitary stalk injury shuts off antidiuretic hormone release, so the collecting duct cannot reabsorb water. Free water pours out as dilute urine while the remaining plasma concentrates, giving the paired picture of hypernatremia with inappropriately dilute urine. An osmotic diuresis would instead raise the urine specific gravity because the urine is full of solute.","week":"3"},{"labs":[["Creatine kinase 14,000 in a four-year-old boy","up"],["Aldolase","up"],["AST and ALT","up"],["Gamma-glutamyl transferase","n"],["Dystrophin gene deletion on genetic testing","abn"]],"opts":["Viral myositis","Duchenne muscular dystrophy","Juvenile idiopathic arthritis","Acute viral hepatitis"],"c":1,"why":"Absent dystrophin leaves the sarcolemma unanchored to the cytoskeleton, so the membrane tears with every contraction and enzymes leak continuously, which is why creatine kinase is enormous from birth and long before weakness is obvious. The AST and ALT here come from muscle rather than liver, and the normal gamma-glutamyl transferase proves the liver is not the source.","week":"3"},{"labs":[["Creatine kinase 9,600","up"],["White cell count 17,000","up"],["Serum iron 22","down"],["Core temperature 40.2 C","up"],["Board-like lead-pipe muscle rigidity","abn"]],"opts":["Anticholinergic toxicity","Serotonin syndrome","Neuroleptic malignant syndrome","Sepsis from aspiration pneumonia"],"c":2,"why":"Abrupt dopamine D2 blockade in the basal ganglia produces sustained lead-pipe rigidity, and the same blockade in the hypothalamus removes the set point that would normally trigger heat loss, so heat is generated faster than it is dissipated. Continuous rigidity destroys muscle and releases creatine kinase, and a low serum iron is a characteristic acute phase feature. Serotonin syndrome instead begins within hours and causes hyperreflexia and clonus rather than rigidity.","week":"3"},{"labs":[["Hematocrit 56","up"],["Serum potassium 5.9","up"],["Serum sodium 129","down"],["Serum albumin 2.1","down"],["Urine output 12 mL per hour","down"]],"opts":["Emergent (fluid shift) phase of a major burn","Diuretic (fluid remobilization) phase of a major burn","Septic shock from burn wound infection","Contrast-induced acute kidney injury"],"c":0,"why":"Burn mediators make capillaries leak plasma and protein into the interstitium, so albumin falls while red cells are concentrated into a shrinking plasma volume and hematocrit rises. Dying cells release potassium as their sodium-potassium pumps fail, and sodium is trapped in the burn edema. Falling circulating volume drops renal perfusion and urine output, and every one of these values reverses once the diuretic phase begins.","week":"3"}],"pairs":[{"clue":"A teenager is struck in the temple by a baseball, is knocked out briefly, then walks and talks normally for an hour before becoming rapidly drowsy with a fixed dilated right pupil.","a":"Epidural hematoma","b":"Acute subdural hematoma","why":"The lucid interval belongs to arterial bleeding from the middle meningeal artery beneath a temporal skull fracture, which takes time to strip the dura away but then expands fast under arterial pressure. Subdural bleeding comes from low-pressure bridging veins, so consciousness is usually depressed from impact onward and never fully clears.","week":"3","c":0},{"clue":"An 82-year-old on warfarin has had a dull headache and slowly worsening confusion for three weeks; he fell in the bathroom last month and thought nothing of it.","a":"Chronic subdural hematoma","b":"Alzheimer disease","why":"Age-related atrophy stretches the bridging veins and widens the subdural space, so a trivial fall causes a slow venous ooze that takes weeks to produce symptoms, and anticoagulation lets it continue. The tell is a definable starting point plus headache; Alzheimer decline is measured in years and opens with memory loss rather than headache.","week":"3","c":0},{"clue":"Sudden severe headache with vomiting, a rapid fall in Glasgow Coma Scale score, and a blood pressure of 214/118.","a":"Hemorrhagic stroke","b":"Ischemic thrombotic stroke","why":"Blood escaping into brain tissue immediately adds volume to a closed vault, so headache, vomiting and depressed consciousness appear at onset from raised intracranial pressure. An ischemic infarct removes function without adding volume, so it is typically painless with a preserved level of consciousness until edema peaks days later.","week":"3","c":0},{"clue":"Right arm weakness and slurred speech that cleared completely within 40 minutes; diffusion-weighted MRI shows no infarct.","a":"Transient ischemic attack","b":"Minor ischemic stroke","why":"The definition rests on tissue rather than the clock: perfusion was restored before cells died, so imaging is clean and the deficit was reversible. If MRI shows infarction the event is a stroke even if the symptoms lasted only minutes, because tissue was permanently lost.","week":"3","c":0},{"clue":"Twelve hours after a head injury the blood pressure reads 198/58, the heart rate is 44, and breathing alternates between deep and absent.","a":"Rising intracranial pressure with Cushing triad","b":"Hypovolemic shock","why":"Cushing triad is a brainstem rescue reflex: systemic vasoconstriction raises systolic pressure to force blood past the rising intracranial pressure, and baroreceptors answer that surge with bradycardia, so the pulse pressure widens. Shock does the opposite, giving tachycardia, a narrow pulse pressure and a falling blood pressure.","week":"3","c":0},{"clue":"On painful stimulus the arms extend and internally rotate, the wrists pronate, and the feet plantar flex.","a":"Decerebrate posturing","b":"Decorticate posturing","why":"Extension everywhere means the lesion sits at or below the red nucleus in the midbrain or pons, leaving vestibulospinal extensor drive unopposed. Decorticate posturing flexes the arms toward the core because the corticospinal pathway is lost while the red nucleus still functions, so it indicates a higher and less ominous lesion.","week":"3","c":0},{"clue":"The right pupil becomes fixed and dilated while the left arm and leg become weak.","a":"Uncal (transtentorial) herniation","b":"Tonsillar (foramen magnum) herniation","why":"The medial temporal lobe slides over the tentorial edge and crushes the oculomotor nerve on the same side as the lesion, taking out parasympathetic pupil constriction first, while the corticospinal tract is compressed above its decussation and weakens the opposite side. Tonsillar herniation compresses the medulla and presents with apnea and cardiovascular collapse rather than a pupil sign.","week":"3","c":0},{"clue":"A young man is comatose from the moment of a high-speed rotational crash, has a Glasgow Coma Scale score of 5 for four days, and the CT scan looks almost normal.","a":"Diffuse axonal injury","b":"Concussion","why":"Rotational acceleration shears axons at the gray-white junction where tissue densities differ, so the damage is microscopic and scattered and imaging can look bland while the patient is deeply unconscious. Concussion is a transient functional disturbance of the same pathways with recovery over minutes to days and no persistent coma.","week":"3","c":0},{"clue":"Six hours after a tibial fracture is casted the pain is far worse than expected, passive extension of the toes is agonizing, the calf is tense and shiny, and the pedal pulse is easily felt.","a":"Acute compartment syndrome","b":"Expected post-fracture pain from a tight cast","why":"Compartment pressure only has to exceed capillary pressure of about 30 mmHg to stop tissue perfusion, far below what would obliterate an artery, so a present pulse feels reassuring but means nothing. Pain on passive stretch of the muscles inside the compartment is the earliest reliable sign, while pulselessness and paralysis mean muscle is already dying.","week":"3","c":0},{"clue":"Thirty-six hours after a femoral shaft fracture a previously well 24-year-old becomes breathless and confused with petechiae across the chest and axillae.","a":"Fat embolism syndrome","b":"Pulmonary embolism from deep vein thrombosis","why":"Only fat globules are small enough to pass into the skin and cerebral microcirculation, which is why the triad of hypoxemia, altered mental status and a petechial rash appears 24 to 72 hours after a long bone fracture. A venous thromboembolus lodges in the pulmonary arteries, produces no rash, and usually declares itself later with calf signs.","week":"3","c":0},{"clue":"A 66-year-old woman sustains a vertebral compression fracture lifting a suitcase; calcium, phosphate and alkaline phosphatase are all normal.","a":"Osteoporosis","b":"Osteomalacia","why":"Osteoporosis is too little bone that is chemically normal, so serum studies stay normal and only bone density is abnormal. Osteomalacia is a normal quantity of poorly mineralized bone, so vitamin D is low, calcium and phosphate fall and alkaline phosphatase climbs, usually with diffuse bone pain and proximal weakness rather than one fragility fracture.","week":"3","c":0},{"clue":"Aspirate from an acutely inflamed first metatarsophalangeal joint shows needle-shaped, negatively birefringent crystals.","a":"Gout","b":"Pseudogout","why":"Shape and birefringence are the entire discriminator: monosodium urate forms needles that are negatively birefringent, while calcium pyrophosphate forms rhomboids that are positively birefringent. Urate precipitates in cool distal joints such as the great toe, whereas pseudogout favors the knee and wrist of an older patient with chondrocalcinosis on the film.","week":"3","c":0},{"clue":"Symmetrical swelling of the metacarpophalangeal and proximal interphalangeal joints with two hours of morning stiffness that eases as the day goes on.","a":"Rheumatoid arthritis","b":"Osteoarthritis","why":"Immune-driven synovitis is worst after a night of immobility because inflammatory exudate accumulates, so stiffness is prolonged and movement improves it, and because the trigger is systemic the distribution is symmetrical and spares the distal interphalangeal joints. Osteoarthritis is mechanical, so stiffness lasts under 30 minutes, use makes it worse, and it targets the distal interphalangeal and weight-bearing joints asymmetrically.","week":"3","c":0},{"clue":"A sacral wound shows visible subcutaneous fat, with no exposed muscle, tendon or bone, and the entire base of the wound can be seen.","a":"Stage 3 pressure injury","b":"Unstageable pressure injury","why":"Staging depends on the deepest tissue that can actually be seen. Fat visible with an inspectable base is full-thickness skin loss, which is stage 3, whereas unstageable means slough or eschar obscures the base so depth cannot be judged until the wound is debrided.","week":"3","c":0},{"clue":"The skin over the heel is intact but shows a persistent deep maroon-purple discoloration and feels boggy and cooler than surrounding skin.","a":"Deep tissue pressure injury","b":"Stage 1 pressure injury","why":"Color is the discriminator. Stage 1 is non-blanchable erythema, a red inflammatory response in a still viable dermis, whereas maroon or purple reflects blood breakdown from muscle already necrosed at the bone interface beneath intact skin, and it commonly declares itself as a deep crater within days.","week":"3","c":0},{"clue":"A burn on the thigh is dry, waxy white and leathery, does not blanch, and the patient reports no pain in that area.","a":"Full-thickness burn","b":"Deep partial-thickness burn","why":"Painlessness is the giveaway: full-thickness injury destroys the dermal nerve endings along with the capillary bed, so the eschar is dry, inelastic and insensate and cannot heal from the edges without grafting. Deep partial-thickness burns spare some dermal appendages, so they blister, stay moist, blanch sluggishly and remain painful.","week":"3","c":0},{"clue":"A cellulitic-looking leg spreads over hours with pain out of all proportion to its appearance, dusky gray patches, crepitus, and a blood pressure of 84/50.","a":"Necrotizing fasciitis","b":"Cellulitis","why":"The infection tracks along the fascial plane and thromboses the perforating vessels, so nerves and skin die from below and pain outruns the visible signs before giving way to anesthesia, dusky skin and gas in the tissue. Simple cellulitis stays within the dermis and subcutaneous tissue, advances over days, and causes neither crepitus nor shock.","week":"3","c":0},{"clue":"An 8 mm lesion on the back is asymmetric with a notched border, contains brown, black and blue-gray areas, and has changed noticeably over four months.","a":"Melanoma","b":"Basal cell carcinoma","why":"Every ABCDE feature is present, and color variegation with rapid change reflects malignant melanocytes entering the vertical growth phase, which is what gives melanoma access to lymphatics and its lethality. Basal cell carcinoma is a slow, pearly, translucent papule with rolled edges and telangiectasias that invades locally but almost never metastasizes.","week":"3","c":0}],"redflags":[{"s":"Twelve hours after a head injury: blood pressure 200/58, heart rate 42, irregular gasping respirations.","act":1,"why":"This is Cushing triad, a late brainstem reflex meaning intracranial pressure is approaching arterial pressure and herniation is imminent. It calls for immediate escalation, airway control, head-of-bed elevation and osmotherapy, not another set of observations.","week":"3"},{"s":"Sudden thunderclap headache described as the worst of his life, with vomiting and neck stiffness.","act":1,"why":"Arterial blood entering the subarachnoid space irritates the meninges and raises intracranial pressure instantly. Rebleeding risk peaks within the first 24 hours and carries high mortality, so imaging and neurosurgical referral cannot be deferred.","week":"3"},{"s":"A generalized tonic-clonic seizure has continued for six minutes without the patient regaining consciousness.","act":1,"why":"Past about five minutes, GABA-A receptors are internalized and the seizure becomes self-sustaining and progressively benzodiazepine-resistant, while lactic acidosis, hyperthermia and excitotoxic neuronal death begin. Treatment is given now rather than waiting to see whether it stops.","week":"3"},{"s":"Facial droop, right arm drift and expressive aphasia that began 45 minutes ago.","act":1,"why":"The ischemic penumbra is still alive on collateral flow but dies over minutes to a few hours, and reperfusion therapy is strictly time-limited. Immediate imaging plus a glucose check to exclude a hypoglycemic mimic takes priority over everything else.","week":"3"},{"s":"Eight hours after a tibial fracture: pain unrelieved by opioids, agony on passive stretch of the toes, tense compartment, palpable pedal pulse.","act":1,"why":"Capillary flow has already stopped even though the artery remains open, and irreversible muscle necrosis begins at roughly four to six hours. Fasciotomy is the only treatment, and waiting for the pulse to disappear means waiting for dead muscle.","week":"3"},{"s":"Thirty-six hours after a femur fracture: respiratory rate 34, SpO2 87 percent, new confusion, petechiae over the chest.","act":1,"why":"Fat globules have reached the pulmonary and cerebral microcirculation, and free fatty acids are injuring the alveolar-capillary membrane. Untreated it progresses to acute respiratory distress syndrome, so oxygenation, ventilatory support and fracture immobilization are urgent.","week":"3"},{"s":"After a crush injury: tea-colored urine, creatine kinase 42,000, potassium 6.4 with peaked T waves on the monitor.","act":1,"why":"The immediate threat is cardiac rather than renal, because potassium released from lysed muscle destabilizes the myocardial membrane and can trigger ventricular fibrillation. Calcium for membrane stabilization, insulin with glucose to shift potassium, and aggressive fluids to flush myoglobin are all needed at once.","week":"3"},{"s":"House-fire victim with singed nasal hairs, soot in the mouth, hoarse voice and a brassy cough.","act":1,"why":"These findings mark thermal and chemical injury above the vocal cords, and the airway will swell progressively over the next several hours as fluid resuscitation proceeds. Intubation is performed early while the anatomy is still visible, not after stridor develops.","week":"3"},{"s":"Circumferential full-thickness burn around the chest, with rising ventilator pressures and shrinking tidal volumes.","act":1,"why":"Full-thickness eschar is inelastic and cannot expand as burn edema accumulates beneath it, so it acts as a tourniquet around the thorax and mechanically prevents chest expansion. Escharotomy is required urgently to restore ventilation.","week":"3"},{"s":"A patient states he has a plan to end his life tonight and has medication stockpiled at home.","act":1,"why":"A specific plan combined with available means converts passive ideation into imminent risk. The response is continuous observation, removal of means and immediate psychiatric evaluation; he cannot be discharged to be reassessed at a future appointment.","week":"3"},{"s":"Spreading dusky discoloration of the leg with crepitus, pain out of proportion to appearance, temperature 39.4 C and blood pressure 82/48.","act":1,"why":"Necrotizing infection along the fascial plane is thrombosing the vessels feeding the overlying skin and releasing exotoxin into the circulation. It advances in hours, and survival depends on emergency surgical debridement with antibiotics rather than observation.","week":"3"},{"s":"Burn day three: urine output has risen to 220 mL per hour and potassium has fallen to 3.4.","act":0,"why":"This is the expected diuretic phase, when capillary integrity returns and third-spaced fluid is remobilized into the circulation and excreted. It is managed by reducing the fluid rate and replacing potassium; the predictable risk now is fluid overload, not shock.","week":"3"},{"s":"Twenty minutes after a witnessed tonic-clonic seizure the patient is drowsy and disoriented but breathing well with normal oxygen saturation.","act":0,"why":"The postictal state reflects neuronal exhaustion and depleted neurotransmitter stores after synchronous discharge, and it typically clears within 30 to 60 minutes. Position for airway safety, protect from injury and observe; the emergency threshold is seizure duration, which was not crossed.","week":"3"},{"s":"A recreational runner has a creatine kinase of 900 the day after a marathon, with clear urine, normal creatinine and normal potassium.","act":0,"why":"Modest enzyme leak follows prolonged eccentric muscle work and does not by itself constitute rhabdomyolysis. With normal renal function, normal potassium and no pigment in the urine, oral hydration and rest are adequate.","week":"3"},{"s":"A 68-year-old has bony nodules at the distal interphalangeal joints, knee crepitus, and 15 minutes of morning stiffness.","act":0,"why":"Heberden nodes with brief stiffness that eases quickly are the mechanical pattern of osteoarthritis, a slow degenerative process with no systemic inflammation to chase. Management is analgesia, weight control and activity modification rather than urgent evaluation.","week":"3"},{"s":"A patient on maintenance lithium has a fine hand tremor; the serum level is 0.8 mEq/L and she is eating and drinking normally.","act":0,"why":"A fine tremor is a common dose-related effect within the therapeutic range and can be managed by adjusting dose timing. The findings that demand action are coarse tremor with ataxia, vomiting, slurred speech and confusion, which signal a toxic level usually driven by dehydration, sodium loss or a new diuretic or NSAID.","week":"3"}],"chains":[{"title":"Monro-Kellie doctrine to herniation","start":"An expanding epidural hematoma adds a fourth volume inside a rigid, closed cranial vault.","steps":["Cerebrospinal fluid is displaced into the spinal subarachnoid space and venous blood is shunted out of the cranium, so intracranial pressure stays near normal and the patient looks deceptively well.","Those compensatory reserves are exhausted, so each further milliliter of clot now raises intracranial pressure steeply and cerebral perfusion pressure, which is mean arterial pressure minus intracranial pressure, begins to fall.","The brainstem drives systemic vasoconstriction to force blood into the head, raising systolic pressure and widening the pulse pressure, while baroreceptors answer that surge with bradycardia and medullary compression makes respirations irregular.","Continued displacement forces the uncus of the temporal lobe over the tentorial edge, compressing the oculomotor nerve and midbrain on the side of the lesion.","The pupil on that side becomes fixed and dilated, the opposite limbs weaken and posture abnormally, and if the pressure is not relieved the medulla is coned into the foramen magnum and respirations stop."],"why":"Because the skull cannot expand, the brain buys time by surrendering cerebrospinal fluid and venous blood, and that borrowed time is exactly why deterioration appears sudden. Once compliance is spent the pressure-volume curve turns almost vertical, so the same slow bleed that produced no signs for an hour can produce herniation in minutes.","week":"3"},{"title":"Embolic occlusion to delayed deterioration in ischemic stroke","start":"A thrombus from a fibrillating left atrium lodges in the middle cerebral artery.","steps":["Regional blood flow falls below the threshold for oxidative metabolism, so neurons cannot generate ATP and the sodium-potassium pump fails.","Sodium and water flood into the cells, and the depolarized membranes release glutamate that opens calcium channels on neighboring neurons.","Intracellular calcium activates proteases, lipases and nitric oxide synthase, generating free radicals that kill the infarct core within minutes while the surrounding penumbra survives on collateral flow.","Water trapped inside dying cells produces cytotoxic edema that peaks around days three to five, so the infarct now behaves as a space-occupying mass.","Midline shift compresses the ventricles and the opposite hemisphere, raising intracranial pressure and dropping the level of consciousness days after the original deficit had stabilized."],"why":"The split between dead core and salvageable penumbra explains why reperfusion is worth chasing early and useless late. It also explains the classic trap of the stable stroke patient who deteriorates on day three, which is edema and mass effect rather than a second stroke.","week":"3"},{"title":"Fracture to fasciotomy: compartment syndrome and its sequelae","start":"A closed tibial shaft fracture bleeds into the fascia-bound anterior compartment of the leg.","steps":["The fascia cannot stretch, so the added blood and edema raise interstitial pressure above capillary perfusion pressure of roughly 30 mmHg.","Capillary flow ceases while arterial inflow continues, so muscle becomes ischemic and exquisitely painful on passive stretch even though the distal pulse remains palpable.","Ischemic tissue releases inflammatory mediators that increase capillary permeability, adding more fluid to the compartment and driving pressure higher in a self-reinforcing loop.","After four to six hours the myocytes lyse, releasing myoglobin, potassium, phosphate and creatine kinase into the circulation.","Myoglobin casts obstruct the renal tubules and cause acute kidney injury, the released potassium threatens lethal arrhythmia, and surviving muscle heals by fibrosis into a fixed Volkmann contracture."],"why":"The pressure that stops capillary flow is far lower than the pressure that stops arterial flow, which is why a pulse persists and why waiting for the textbook pulselessness guarantees dead muscle. The chain also shows how a limb problem converts directly into a cardiac and renal emergency.","week":"3"},{"title":"The two phases of burn danger","start":"A 40 percent total body surface area flame burn releases histamine, prostaglandins, bradykinin and cytokines into the circulation.","steps":["Capillary permeability rises throughout the body, so plasma and protein leak into the interstitium and edema forms even in unburned tissue, dropping serum albumin.","Circulating volume and cardiac output fall while hematocrit rises, because red cells are concentrated into a shrinking plasma volume.","Damaged cells and failing sodium-potassium pumps release potassium into the blood while sodium is sequestered in the burn edema, so potassium climbs and sodium falls.","Renal and splanchnic perfusion drop, urine output falls and burn shock develops unless crystalloid resuscitation replaces the losses across the first 24 hours.","At 24 to 48 hours capillary integrity is restored, third-spaced fluid returns to the vessels, hematocrit falls, brisk diuresis begins and potassium is washed out in the urine, so the danger flips from hypovolemic shock to fluid overload and hypokalemia."],"why":"One injury produces two opposite emergencies separated by about two days, and every laboratory value reverses at the changeover. Treating a day-three patient with day-one fluid orders causes pulmonary edema, which is why the phase rather than the burn size drives the fluid plan.","week":"3"},{"title":"Estrogen loss to fragility fracture in osteoporosis","start":"Estrogen production falls sharply at menopause.","steps":["Without estrogen's restraint, osteoblasts and marrow stromal cells express more RANK ligand and less osteoprotegerin, the decoy receptor that normally mops it up.","Free RANK ligand binds RANK on osteoclast precursors, increasing osteoclast recruitment, activation and survival.","Resorption now outpaces formation in every remodeling cycle, so trabeculae thin and the horizontal struts that brace them are perforated and lost.","Bone mass and microarchitecture deteriorate while the remaining matrix stays fully mineralized, so serum calcium, phosphate and alkaline phosphatase remain normal and only bone density is abnormal.","Trabecula-rich sites fail under ordinary loads, producing vertebral compression fractures with kyphosis and height loss, plus hip and wrist fractures from minor falls."],"why":"Osteoporosis is a quantity problem rather than a chemistry problem, which is precisely why the routine metabolic panel is normal and why DEXA is the diagnostic test. The RANK ligand pathway also explains why antiresorptive drugs aim at osteoclast recruitment rather than at calcium intake alone.","week":"3"},{"title":"Pressure injury forms from the bone outward","start":"Unrelieved pressure over the sacrum exceeds capillary closing pressure of about 32 mmHg.","steps":["Capillary blood flow stops, so oxygen and nutrient delivery and metabolic waste removal cease in the compressed tissue.","Muscle, which has the highest metabolic demand and lies directly against the bony prominence, necroses first while the skin surface still appears intact.","Relieving the pressure reperfuses the damaged bed and adds free-radical injury, so the area declares itself either as non-blanchable erythema or, when deep damage is extensive, as a maroon deep tissue injury under unbroken skin.","Continued pressure, shear and moisture breach the epidermis, producing first a shallow open ulcer and then a crater that exposes fat and eventually muscle, tendon or bone.","The open wound is colonized and can seed osteomyelitis and sepsis, and it closes only by contraction and scar because the dermal appendages needed for regeneration have been destroyed."],"why":"Damage starts at the bone-muscle interface and reaches the surface last, so what is visible always understates what has already been destroyed. That is why a small purple patch can convert to a deep crater within days, and why deep tissue injury and unstageable exist as separate categories from the numbered stages.","week":"3"},{"title":"Chronic stress to the antidepressant lag","start":"Prolonged psychosocial stress keeps the hypothalamic-pituitary-adrenal axis switched on, so cortisol stays high.","steps":["Sustained cortisol downregulates hippocampal glucocorticoid receptors, weakening the negative feedback that should shut the axis off, so cortisol climbs further.","High cortisol suppresses brain-derived neurotrophic factor, causing dendritic atrophy and reduced neurogenesis in the hippocampus and prefrontal cortex.","Monoamine transmission by serotonin, norepinephrine and dopamine falls at these damaged synapses while the amygdala escapes prefrontal restraint and becomes hyperactive.","The clinical picture emerges as depressed mood and anhedonia from blunted serotonin and dopamine reward signaling, with poor concentration, disturbed sleep and appetite, and amygdala-driven anxiety.","A selective serotonin reuptake inhibitor raises synaptic serotonin within hours, yet mood lifts only after two to four weeks because benefit depends on receptor downregulation and on brain-derived neurotrophic factor rebuilding synaptic connections."],"why":"The monoamine deficit is the consequence of a stress-driven structural change rather than a simple chemical shortage, which is why symptoms outlast the stressor and why drug levels rise long before mood does. Teaching the lag prevents the common patient error of abandoning the medication on day five for not working.","week":"3"}]},"4":{"labs":[{"labs":[["Serum sodium","down"],["Serum osmolality","down"],["Urine osmolality","up"],["Urine sodium","up"]],"opts":["Central diabetes insipidus","Syndrome of inappropriate ADH (SIADH)","Primary polydipsia","Addison disease"],"c":1,"why":"ADH is being released independently of osmolality, so the collecting duct keeps reabsorbing free water even though the plasma is already dilute. The mismatch of a low serum osmolality with a concentrated urine is the signature, and the high urine sodium tells you the patient is euvolaemic rather than volume depleted, because mild volume expansion suppresses aldosterone.","week":"4"},{"labs":[["Serum sodium","up"],["Serum osmolality","up"],["Urine osmolality","down"],["Urine specific gravity","down"],["Urine output","up"]],"opts":["Hyperosmolar hyperglycaemic state","Primary hyperaldosteronism","Central diabetes insipidus","SIADH"],"c":2,"why":"With no ADH the collecting duct stays impermeable to water, so enormous volumes of maximally dilute urine are lost while the plasma concentrates. Hyperosmolar hyperglycaemic state also raises plasma osmolality, but there the osmotic load is glucose and the urine is not dilute.","week":"4"},{"labs":[["TSH","down"],["Free T4","up"],["Thyroid-stimulating immunoglobulin","up"],["Radioactive iodine uptake","up"]],"opts":["Subacute (de Quervain) thyroiditis","TSH-secreting pituitary adenoma","Hashimoto thyroiditis","Graves disease"],"c":3,"why":"An autoantibody is switching on the TSH receptor, so the gland both synthesises hormone and traps iodine avidly, which is why uptake is high. Negative feedback is intact at the pituitary, so TSH is suppressed; a TSH-secreting adenoma would show a high TSH, and thyroiditis releases preformed hormone with a low uptake.","week":"4"},{"labs":[["TSH","up"],["Free T4","down"],["Anti-thyroid peroxidase antibodies","up"],["LDL cholesterol","up"]],"opts":["Hashimoto thyroiditis","Graves disease","Secondary hypothyroidism","Thyroid storm"],"c":0,"why":"A high TSH with a low free T4 proves the pituitary is working and shouting at a gland that cannot respond, which localises the lesion to the thyroid itself. Autoimmune lymphocytic destruction explains the anti-TPO antibodies, and the loss of thyroid hormone reduces LDL receptor expression so cholesterol rises.","week":"4"},{"labs":[["TSH","down"],["Free T4","down"],["Plasma ACTH","down"],["Morning cortisol","down"]],"opts":["Hashimoto thyroiditis","Secondary hypothyroidism from anterior pituitary failure","Primary adrenal insufficiency","Graves disease"],"c":1,"why":"This is the primary versus secondary rule in action: when the target hormone and its trophic hormone fall together, the lesion is above the gland. Loss of several anterior pituitary axes at once points to pituitary rather than thyroid disease, and in primary adrenal failure the ACTH would be high, not low.","week":"4"},{"labs":[["24-hour urinary free cortisol","up"],["Plasma ACTH","up"],["Fasting glucose","up"],["Serum potassium","down"]],"opts":["Cortisol-secreting adrenal adenoma","Exogenous glucocorticoid therapy","Cushing disease from an ACTH-secreting pituitary adenoma","Addison disease"],"c":2,"why":"Cortisol is high and ACTH has not been suppressed, so the drive must be coming from above the adrenal gland. An adrenal adenoma or exogenous steroid would both switch ACTH off, and the hypokalaemia reflects very high cortisol spilling over onto mineralocorticoid receptors in the distal nephron.","week":"4"},{"labs":[["Serum sodium","down"],["Serum potassium","up"],["Blood glucose","down"],["Plasma ACTH","up"],["Morning cortisol","down"]],"opts":["SIADH","Secondary adrenal insufficiency","Cushing syndrome","Primary adrenal insufficiency (Addison disease)"],"c":3,"why":"The whole adrenal cortex has failed, so aldosterone loss wastes sodium and retains potassium while cortisol loss removes the gluconeogenic drive. A high ACTH confirms the pituitary is intact and straining, and the same precursor molecule that raises ACTH also produces the bronze hyperpigmentation.","week":"4"},{"labs":[["Blood glucose","up"],["Arterial pH","down"],["Serum bicarbonate","down"],["Anion gap","up"],["Serum ketones","up"]],"opts":["Hyperosmolar hyperglycaemic state","Diabetic ketoacidosis","Hypoglycaemia","SIADH"],"c":1,"why":"Absolute insulin deficiency allows unrestrained lipolysis, and the liver converts the delivered fatty acids into ketoacids that consume bicarbonate and open the anion gap. The combination of hyperglycaemia with a true acidosis and measurable ketones is what separates this from the hyperosmolar state.","week":"4"},{"labs":[["Blood glucose","up"],["Serum osmolality","up"],["Serum sodium","up"],["Arterial pH","n"],["Serum ketones","n"]],"opts":["Diabetic ketoacidosis","Central diabetes insipidus","Hyperosmolar hyperglycaemic state","Thyroid storm"],"c":2,"why":"Residual endogenous insulin in type 2 diabetes is enough to suppress lipolysis but not hepatic glucose output, so ketones never form while glucose climbs much higher than in ketoacidosis. Here the normal pH and absent ketones are the discriminating results, and the danger comes from osmolality and profound water loss.","week":"4"},{"labs":[["C-peptide","down"],["GAD65 autoantibodies","up"],["HbA1c","up"],["Urine ketones","up"]],"opts":["Type 2 diabetes mellitus","Steroid-induced hyperglycaemia","Impaired fasting glucose","Type 1 diabetes mellitus"],"c":3,"why":"C-peptide is cleaved from proinsulin and released in equal amounts with endogenous insulin, so an undetectable level means the beta cells are gone rather than overworked. Islet autoantibodies confirm an autoimmune mechanism, and the absence of insulin is what permits ketogenesis.","week":"4"},{"labs":[["Corrected serum calcium","up"],["Parathyroid hormone","up"],["Serum phosphate","down"],["Urinary calcium","up"],["Alkaline phosphatase","up"]],"opts":["Primary hyperparathyroidism","Secondary hyperparathyroidism of chronic kidney disease","Hypoparathyroidism","Vitamin D deficiency"],"c":0,"why":"PTH should be shut off by a high calcium, so a raised PTH alongside a raised calcium means the gland is autonomous and ignoring the calcium-sensing receptor. PTH simultaneously blocks proximal phosphate reabsorption, which is why calcium and phosphate move in opposite directions; in kidney disease calcium is low and phosphate is high instead.","week":"4"},{"labs":[["Corrected serum calcium","down"],["Serum phosphate","up"],["Parathyroid hormone","down"],["Serum albumin","n"],["Serum magnesium","n"]],"opts":["Vitamin D deficiency","Post-surgical hypoparathyroidism","Secondary hyperparathyroidism","Primary hyperparathyroidism"],"c":1,"why":"Every other cause of hypocalcaemia drives PTH upwards, so a low calcium with a low PTH can only mean the parathyroid tissue itself has been removed, devascularised or bruised. Without PTH the kidney retains phosphate, which is why phosphate rises as calcium falls, and a normal albumin confirms the low calcium is real.","week":"4"},{"labs":[["Plasma free metanephrines","up"],["24-hour urinary catecholamines","up"],["Fasting glucose","up"],["Serum potassium","n"],["TSH","n"]],"opts":["Thyroid storm","Primary hyperaldosteronism","Phaeochromocytoma","Panic disorder with essential hypertension"],"c":2,"why":"A chromaffin cell tumour secretes catecholamines in bursts, and their metabolites, the metanephrines, remain elevated between attacks, which is why they are the test of choice. Catecholamines also drive glycogenolysis and suppress insulin release, explaining the hyperglycaemia; a normal TSH excludes thyrotoxicosis and a normal potassium argues strongly against an aldosterone-producing adenoma.","week":"4"},{"labs":[["FSH","up"],["LH","up"],["Oestradiol","down"],["Karyotype","abn"]],"opts":["Klinefelter syndrome","Hypogonadotrophic hypogonadism from hypopituitarism","Polycystic ovary syndrome","Turner syndrome"],"c":3,"why":"Streak gonads produce neither oestradiol nor inhibin, so nothing feeds back on the pituitary and gonadotrophins climb, giving hypergonadotrophic hypogonadism. If the pituitary were the problem, FSH and LH would be low alongside the low oestradiol, and the 45,X karyotype settles the diagnosis.","week":"4"}],"pairs":[{"clue":"A pedigree shows the trait in every generation, males and females affected roughly equally, and each child of an affected parent has a one in two chance of being affected.","a":"Autosomal dominant inheritance","b":"Autosomal recessive inheritance","why":"One mutant allele is enough to express a dominant disorder, so affected people appear in every generation without skipping. Recessive traits require two copies and therefore pass silently through unaffected carriers, producing gaps in the pedigree.","week":"4","c":0},{"clue":"Two unaffected parents have an affected son, the mother's brother is also affected, and nowhere on the pedigree does an affected father pass the disorder to a son.","a":"X-linked recessive inheritance","b":"Autosomal recessive inheritance","why":"The absence of male-to-male transmission is the discriminator, because a father hands his son a Y chromosome and never his X. Affected maternal uncles show the mutation travelling on the maternal X through unaffected carrier women.","week":"4","c":0},{"clue":"A newborn has classic features of Down syndrome, and the karyotype reports 46 chromosomes with extra chromosome 21 material fused to chromosome 14.","a":"Robertsonian translocation Down syndrome","b":"Trisomy 21 caused by maternal nondisjunction","why":"Total chromosome count separates them: free trisomy from nondisjunction gives 47 chromosomes, while translocation Down syndrome gives 46 with the extra 21 attached elsewhere. Only the translocation form carries a high recurrence risk, so the parents must be karyotyped.","week":"4","c":0},{"clue":"An adolescent has short stature, a webbed neck, widely spaced nipples, primary amenorrhoea and a coarctation of the aorta.","a":"Turner syndrome (45,X)","b":"Klinefelter syndrome (47,XXY)","why":"A phenotypically female patient with streak ovaries and short stature fits a single X chromosome. Klinefelter patients are phenotypically male and tall rather than short, and present after puberty with small firm testes, gynaecomastia and infertility.","week":"4","c":0},{"clue":"A 14-year-old has three weeks of polyuria, polydipsia and 6 kg of weight loss, with ketones in the urine and an undetectable C-peptide.","a":"Type 1 diabetes mellitus","b":"Type 2 diabetes mellitus","why":"The undetectable C-peptide proves there is no endogenous insulin at all, and only that absolute deficiency permits ketogenesis. Type 2 patients still secrete insulin, so C-peptide is normal or high and weight is usually gained rather than lost.","week":"4","c":0},{"clue":"One monozygotic twin develops type 1 diabetes and the other does not, although sequencing confirms their DNA sequences are identical.","a":"An epigenetic change such as DNA methylation or histone modification","b":"A new de novo germline mutation in the affected twin","why":"Discordance with no sequence difference means gene expression has changed, not gene structure, which is exactly what methylation and histone modification do. A de novo mutation would appear as an actual alteration in the DNA sequence.","week":"4","c":0},{"clue":"One parent cell divides and yields four genetically unique daughter cells, each with 23 chromosomes, after crossing over between homologues.","a":"Meiosis","b":"Mitosis","why":"Halving of the chromosome number plus recombination between homologues occurs only in meiosis, and it is the source of gamete diversity. Mitosis produces two diploid daughter cells genetically identical to the parent.","week":"4","c":0},{"clue":"Two carriers of an autosomal recessive disorder already have one affected child and ask about the risk in a fourth pregnancy.","a":"The risk stays 25 percent in every pregnancy, independent of previous children","b":"The risk is now lower because one of the four possible outcomes has already occurred","why":"Each conception is an independent event with the same Punnett square, so earlier outcomes do not use up the risk. The 25 percent figure is a per-pregnancy probability, not a quota spread across four children.","week":"4","c":0},{"clue":"Cleft lip, neural tube defects and pyloric stenosis cluster in families, no single-gene pattern fits, and recurrence risk rises with the number of affected relatives and the severity of the defect.","a":"Multifactorial inheritance","b":"Autosomal recessive inheritance","why":"Many small-effect genes plus environment push a family across a liability threshold, so risk is empiric and increases with family loading and defect severity. A recessive disorder gives a fixed 25 percent risk that does not change with how many relatives are affected.","week":"4","c":0},{"clue":"A woman who carries the haemophilia A mutation on one X chromosome has children with an unaffected man.","a":"Half the sons will be affected and half the daughters will be carriers","b":"All the daughters will be affected and all the sons will be carriers","why":"Sons receive one maternal X at random, so half inherit the mutant allele and, being hemizygous, are fully affected. Daughters always receive the father's normal X, which protects them, so they can only be carriers.","week":"4","c":0},{"clue":"Free T4 is low, and the TSH is low as well.","a":"Secondary (central) hypothyroidism from pituitary failure","b":"Hashimoto thyroiditis","why":"In primary gland failure the pituitary responds correctly and TSH rises, so a low TSH with a low T4 places the lesion above the gland. The rule is that in secondary disease the trophic hormone and the target hormone move in the same direction.","week":"4","c":0},{"clue":"A woman with a diffuse, smooth, non-tender goitre has exophthalmos and pretibial myxoedema.","a":"Graves disease","b":"Toxic multinodular goitre","why":"Only Graves involves an antibody that cross-reacts with orbital and dermal fibroblasts, which is why the eye and skin changes appear and can persist after the hormone levels are corrected. A nodular goitre overproduces hormone but is lumpy on palpation and never causes exophthalmos.","week":"4","c":0},{"clue":"Two days after a head injury a patient passes 9 litres of pale urine, with serum sodium 156 mmol/L and urine specific gravity 1.002.","a":"Central diabetes insipidus","b":"SIADH","why":"Both follow head injury, so the direction of the sodium is the discriminator. Loss of ADH means free water is excreted and sodium climbs with dilute urine, whereas SIADH retains free water so sodium falls and the urine is concentrated.","week":"4","c":0},{"clue":"A patient on long-term lithium has polyuria and hypernatraemia, and the urine still fails to concentrate after desmopressin is given.","a":"Nephrogenic diabetes insipidus","b":"Central diabetes insipidus","why":"The desmopressin trial separates them: in central disease the hormone is missing, so supplying it concentrates the urine at once. Nephrogenic tubules cannot respond to any amount of ADH because the receptor and aquaporin response is damaged.","week":"4","c":0},{"clue":"A patient with truncal obesity, purple striae and hyperglycaemia has a suppressed plasma ACTH and a 4 cm unilateral adrenal mass.","a":"ACTH-independent Cushing syndrome from an adrenal adenoma","b":"Cushing disease from a pituitary adenoma","why":"A suppressed ACTH shows that feedback is working normally and the cortisol is being made below the pituitary. In Cushing disease the ACTH is inappropriately normal or high and both adrenals are hyperplastic rather than one being a discrete mass.","week":"4","c":0},{"clue":"A patient has fatigue, salt craving, postural hypotension, bronze pigmentation of the palmar creases and buccal mucosa, sodium 128 and potassium 5.9 mmol/L.","a":"Primary adrenal insufficiency (Addison disease)","b":"Secondary adrenal insufficiency","why":"Hyperpigmentation and hyperkalaemia occur only when the adrenal cortex itself fails, because ACTH and its precursor rise and stimulate melanocytes while aldosterone is lost. Secondary insufficiency spares the renin-aldosterone axis and has a low ACTH, so potassium and skin colour stay normal.","week":"4","c":0},{"clue":"A 74-year-old with type 2 diabetes and a urinary infection has glucose 52 mmol/L, osmolality 355 mosm/kg, pH 7.34, negative ketones, and is profoundly dehydrated and drowsy.","a":"Hyperosmolar hyperglycaemic state","b":"Diabetic ketoacidosis","why":"Residual insulin is enough to block lipolysis but not hepatic glucose output, so glucose and osmolality climb far higher than in ketoacidosis while the pH stays near normal. The near-normal pH with absent ketones is the single separating fact.","week":"4","c":0},{"clue":"A patient with type 1 diabetes took their usual insulin, skipped lunch, and over about 15 minutes has become pale, sweaty, tremulous and confused.","a":"Hypoglycaemia","b":"Diabetic ketoacidosis","why":"Tempo and skin are the discriminators, because falling glucose triggers an immediate sympathetic surge that gives cool clammy skin within minutes. Ketoacidosis builds over hours to days and produces warm dry skin with Kussmaul breathing and acetone breath.","week":"4","c":0}],"redflags":[{"s":"A woman with known Addison disease has vomited for 12 hours with gastroenteritis. BP 76/44, HR 128, sodium 126 mmol/L, potassium 6.4 mmol/L, glucose 3.0 mmol/L.","act":1,"why":"This is an addisonian crisis: absent cortisol removes the permissive effect on catecholamines while absent aldosterone strips circulating volume, so shock deepens quickly. IV hydrocortisone and saline must be given immediately, before any confirmatory cortisol result returns.","week":"4"},{"s":"A patient with Graves disease has an untreated chest infection. Temperature 40.4 C, HR 168 in atrial fibrillation, agitated and disorientated.","act":1,"why":"Thyroid storm follows a surge of free hormone acting on upregulated beta receptors, producing hyperthermia and high output cardiac failure. Mortality is substantial without rapid beta blockade, thionamide, iodine given after the thionamide, and active cooling.","week":"4"},{"s":"An elderly woman with a thyroidectomy scar is found unresponsive in a cold flat. Temperature 32.1 C, HR 42, BP 84/50, shallow hypoventilation.","act":1,"why":"Myxoedema coma reflects total loss of thyroid hormone driven thermogenesis, cardiac contractility and respiratory drive, so carbon dioxide accumulates and consciousness falls. She needs IV thyroid hormone plus IV hydrocortisone first in case adrenal insufficiency coexists, with passive rewarming and ventilatory support.","week":"4"},{"s":"The first night after total thyroidectomy the patient has perioral and finger tingling, carpopedal spasm when the blood pressure cuff inflates, and now audible stridor.","act":1,"why":"The parathyroid glands have been bruised or removed, so calcium has fallen and neuromuscular membranes are hyperexcitable. Stridor means laryngospasm from tetany and threatens the airway, so IV calcium gluconate is needed at once.","week":"4"},{"s":"A 19-year-old with type 1 diabetes has glucose 29 mmol/L, pH 7.04, bicarbonate 6 mmol/L, deep sighing respirations and potassium 5.7 mmol/L.","act":1,"why":"This is established diabetic ketoacidosis needing immediate fluids and an insulin infusion. The potassium looks reassuring but total body stores are depleted, because acidosis has driven potassium out of cells; it will fall sharply once insulin starts, so replacement must begin as soon as it drops and urine output is confirmed.","week":"4"},{"s":"A nursing home resident with type 2 diabetes has glucose 51 mmol/L, osmolality 358 mosm/kg, sodium 152 mmol/L, no ketones, and is rousable only to pain.","act":1,"why":"Hyperosmolar hyperglycaemic state produces water deficits of many litres, and the osmotic gradient pulls water out of neurones, which is why consciousness tracks osmolality rather than glucose alone. Aggressive but controlled fluid resuscitation is the priority and mortality is higher than in ketoacidosis.","week":"4"},{"s":"A patient with type 1 diabetes is found at 03:00 sweating, combative and confused, with a capillary glucose of 2.0 mmol/L.","act":1,"why":"The brain has no glucose reserve, so neuroglycopenia causes neuronal injury within minutes and is far more urgent than any degree of hyperglycaemia. Treat immediately with oral glucose if the airway is safe, otherwise IV dextrose or intramuscular glucagon.","week":"4"},{"s":"A patient with small cell lung cancer has a serum sodium of 111 mmol/L and has just had a generalised seizure.","act":1,"why":"Sodium has fallen faster than the brain can extrude osmolytes, so water has entered neurones and the brain is swelling inside a fixed skull. Hypertonic saline is indicated, but correction must stay within roughly 8 to 10 mmol/L in 24 hours to avoid osmotic demyelination.","week":"4"},{"s":"Twelve hours after trans-sphenoidal pituitary surgery the patient has passed 600 mL of pale urine hourly for three hours, with sodium 154 mmol/L and urine specific gravity 1.001.","act":1,"why":"Surgical handling of the posterior pituitary has abolished ADH release, so free water is lost faster than a post-operative patient can drink it. Sodium will keep climbing towards seizure territory unless desmopressin and matched fluid replacement are started now.","week":"4"},{"s":"A patient with months of episodic headache, palpitations and drenching sweats arrives with BP 244/136, chest pain and blurred vision.","act":1,"why":"A catecholamine surge from a chromaffin tumour is causing hypertensive end-organ damage in the brain, heart and retina. Alpha blockade must be established before any beta blocker is given, because blocking beta mediated vasodilatation leaves alpha vasoconstriction unopposed and drives the pressure higher.","week":"4"},{"s":"A six-week-old with Down syndrome feeds for only two minutes at a time, sweats during feeds, is tachypnoeic and has a loud murmur.","act":1,"why":"These are the infant signs of heart failure from an atrioventricular septal defect, which is common in trisomy 21 because the extra chromosome disrupts endocardial cushion development. Feeding is an infant's exercise test, so a falling feeding tolerance signals decompensation and needs same-day cardiology assessment.","week":"4"},{"s":"A 58-year-old with type 2 diabetes has an HbA1c of 8.6 percent and a fasting glucose of 9.4 mmol/L, feels well, has no ketones and normal urine output.","act":0,"why":"This is chronic hyperglycaemia and a long-term complication risk, not a metabolic emergency, because there is no acidosis, hyperosmolality or dehydration. The correct response is treatment intensification, education and review rather than acute intervention.","week":"4"},{"s":"The morning after a hemithyroidectomy the patient's voice is hoarse, there is no stridor, and corrected calcium is 2.28 mmol/L.","act":0,"why":"Hoarseness alone points to recurrent laryngeal nerve irritation or intubation trauma, which is usually transient. With a patent airway and a normal calcium there is no tetany and no obstruction, so this is documented, voice rested and monitored.","week":"4"},{"s":"A 34-year-old reports six months of fatigue, 5 kg weight loss, salt craving and darkening of the palmar creases. BP 108/70 lying and 100/66 standing, and he is not acutely unwell.","act":0,"why":"This is chronic primary adrenal insufficiency, which needs early morning cortisol, ACTH and a stimulation test, plus education about sick day dosing once treatment starts. Because he is haemodynamically stable and has no intercurrent illness, the cortisol reserve has not yet been overwhelmed, so this is urgent workup rather than resuscitation.","week":"4"},{"s":"A 15-year-old girl with short stature and no breast development has never menstruated. FSH and LH are high and a karyotype is pending.","act":0,"why":"Primary amenorrhoea with high gonadotrophins indicates gonadal failure, most likely Turner syndrome, because streak gonads make no oestrogen or inhibin to feed back. The plan is growth hormone and oestrogen replacement planning with cardiac and renal imaging, which is time-sensitive but not an emergency today.","week":"4"},{"s":"A well 70-year-old on a long-standing SSRI has a sodium of 131 mmol/L, unchanged over six months, with no confusion, headache or gait disturbance.","act":0,"why":"Chronic mild hyponatraemia allows brain cells to extrude organic osmolytes and adapt, so there is no cerebral oedema and no acute risk. The real hazard here is over-rapid correction, so the response is to review the drug, restrict fluid if needed and recheck, not to give hypertonic saline.","week":"4"}],"chains":[{"title":"Nondisjunction to trisomy 21","start":"Homologous copies of chromosome 21 fail to separate during maternal meiosis I.","steps":["One oocyte receives two copies of chromosome 21 while its partner cell receives none.","Fertilisation of the disomic oocyte by a normal sperm produces a zygote with 47 chromosomes.","Every somatic cell now carries three copies of chromosome 21 and overexpresses the genes on it, including amyloid precursor protein.","Excess gene dosage disrupts neuronal migration and endocardial cushion formation, giving hypotonia, intellectual disability and atrioventricular septal defects.","Lifelong overproduction of amyloid precursor protein drives early onset Alzheimer type dementia in adulthood."],"why":"The lesion is a segregation error, not a mutation, so the phenotype comes entirely from having a normal gene set in triplicate. This also explains the maternal age effect, because oocytes sit arrested in meiosis I for decades and their spindle machinery deteriorates.","week":"4"},{"title":"X-linked recessive transmission in haemophilia A","start":"A phenotypically normal woman carries a loss-of-function factor VIII mutation on one of her two X chromosomes.","steps":["Her other X carries a normal allele, so she produces enough factor VIII to remain clinically unaffected.","Each son receives one maternal X at random, giving a one in two chance of inheriting the mutant allele, while every daughter receives her father's normal X.","A son who inherits the mutant X is hemizygous with no second X to compensate, so factor VIII activity falls to a small fraction of normal.","Without factor VIII the intrinsic pathway cannot amplify thrombin generation, so the aPTT is prolonged while the prothrombin time stays normal.","Bleeding is deep rather than superficial, producing haemarthroses and muscle haematomas after minor trauma."],"why":"Hemizygosity is the whole mechanism: a single recessive allele is fully expressed in a male because there is no second X to mask it. That is why the pedigree shows affected males linked through unaffected carrier females and never father to son.","week":"4"},{"title":"Beta cell destruction to diabetic ketoacidosis","start":"Autoimmune T cell destruction removes more than 90 percent of pancreatic beta cells.","steps":["Insulin secretion becomes absolutely deficient while glucagon acts unopposed.","Hepatic glycogenolysis and gluconeogenesis push blood glucose above the renal reabsorption threshold.","Glucose remaining in the tubule creates an osmotic diuresis, so water, sodium and potassium are lost and the patient becomes profoundly dehydrated.","Unrestrained lipolysis floods the liver with free fatty acids, which are converted to acetoacetate and beta-hydroxybutyrate.","Ketoacids consume bicarbonate and open the anion gap, producing Kussmaul respirations, acetone breath and a falsely reassuring serum potassium as hydrogen ions drive potassium out of cells."],"why":"Insulin is the only anti-lipolytic hormone, so it is the complete absence of insulin rather than the high glucose alone that opens the ketone pathway. That is why type 1 diabetes produces ketoacidosis while type 2 diabetes, with residual insulin, usually produces the hyperosmolar state instead.","week":"4"},{"title":"Ectopic ADH to hyponatraemic seizures","start":"A small cell lung carcinoma secretes ADH independently of plasma osmolality.","steps":["ADH inserts aquaporin-2 channels into the collecting duct, so free water is reabsorbed no matter how dilute the plasma already is.","Retained water dilutes the serum sodium and lowers serum osmolality while the urine remains inappropriately concentrated.","Mild volume expansion suppresses aldosterone and stimulates natriuretic peptides, so sodium is excreted and the patient stays euvolaemic rather than oedematous.","Plasma is now hypotonic relative to brain cells, so water moves into neurones and the brain swells inside a fixed skull.","Rising intracranial pressure produces headache and confusion, then seizures and the risk of herniation."],"why":"Every feature follows from water retention rather than sodium loss, which is why fluid restriction rather than salt loading is the treatment. It also explains the diagnostic signature of a concentrated urine at a time when the kidney should be producing maximally dilute urine.","week":"4"},{"title":"Thyroid-stimulating immunoglobulin to thyroid storm","start":"An IgG autoantibody binds and continuously activates the TSH receptor on thyroid follicular cells.","steps":["The gland synthesises T3 and T4 without regard to feedback, and the pituitary correctly suppresses TSH to undetectable levels.","Excess thyroid hormone raises the basal metabolic rate and upregulates beta-adrenergic receptors, producing tachycardia, tremor, heat intolerance and weight loss despite a good appetite.","The same antibody stimulates orbital fibroblasts to deposit glycosaminoglycans behind the eye, producing exophthalmos and lid lag.","A stressor such as infection, surgery or abrupt withdrawal of antithyroid medication releases a surge of free hormone and heightens catecholamine sensitivity.","Thermoregulation and cardiac reserve fail together, giving hyperpyrexia, delirium, atrial fibrillation and high output cardiac failure."],"why":"The drive is receptor stimulation from outside the feedback loop, which is why TSH is undetectable while the gland is hyperactive. It also explains why the eye disease follows the antibody titre rather than the hormone level and can persist after the patient is made euthyroid.","week":"4"},{"title":"Parathyroid adenoma to hypercalcaemic symptoms","start":"A parathyroid adenoma secretes PTH autonomously, ignoring the calcium-sensing receptor.","steps":["PTH increases osteoblast expression of RANKL, which activates osteoclasts and releases calcium and phosphate from bone.","In the kidney the same hormone increases distal calcium reabsorption, blocks proximal phosphate reabsorption and activates 1-alpha-hydroxylase.","Calcitriol then raises intestinal calcium absorption, so serum calcium climbs while serum phosphate falls.","The filtered calcium load exceeds tubular reabsorption, causing hypercalciuria with renal stones and a nephrogenic diuresis with polyuria and thirst.","High extracellular calcium raises the threshold for nerve and muscle depolarisation, giving constipation, muscle weakness, confusion and a shortened QT interval."],"why":"PTH raises calcium and lowers phosphate at the same time, so the two ions moving in opposite directions localises the lesion to the parathyroid gland. In kidney disease they move together, with low calcium and high phosphate, which is the mirror image students are asked to separate.","week":"4"},{"title":"Exogenous glucocorticoid to adrenal crisis","start":"A patient takes high dose prednisolone daily for six months for an inflammatory disease.","steps":["The exogenous steroid feeds back on the hypothalamus and anterior pituitary, suppressing CRH and then ACTH release.","Without ACTH trophic stimulation the zona fasciculata atrophies and loses the capacity to synthesise cortisol.","The steroid is stopped abruptly, and the atrophic cortex cannot restart cortisol production for weeks to months.","Cortisol deficiency removes the permissive effect on catecholamines and the gluconeogenic drive, so vascular tone and blood glucose both fall.","Vomiting, hypotension that does not respond to fluids alone, and hypoglycaemia follow, reversing only with IV hydrocortisone."],"why":"This is secondary adrenal insufficiency, so the renin-aldosterone axis and ACTH driven pigmentation are spared, which is exactly what separates it from Addison disease. It is also the mechanism behind the rule that long-term steroids are always tapered and doubled during illness.","week":"4"}]},"5":{"labs":[{"labs":[["MCV","down"],["Serum ferritin","down"],["Serum iron","down"],["TIBC","up"],["Transferrin saturation","down"]],"opts":["Iron deficiency anaemia","Anaemia of chronic disease","Thalassaemia minor","Sideroblastic anaemia"],"c":0,"why":"Ferritin mirrors stored iron, so a low ferritin means the stores are genuinely empty rather than merely sequestered. The liver responds to empty stores by making more transferrin, which raises TIBC while the iron available to saturate it falls, giving the classic low iron with high TIBC divergence.","week":"5"},{"labs":[["MCV","n"],["Serum ferritin","up"],["Serum iron","down"],["TIBC","down"],["CRP","up"]],"opts":["Anaemia of chronic disease","Iron deficiency anaemia","Acute blood loss anaemia","Aplastic anaemia"],"c":0,"why":"Inflammation drives hepcidin, which locks iron inside macrophages and blocks intestinal absorption, so circulating iron falls while stores stay full and ferritin, an acute phase reactant, rises. A low TIBC alongside low serum iron is the discriminator, because true deficiency would push TIBC up instead.","week":"5"},{"labs":[["MCV","up"],["Serum B12","down"],["Methylmalonic acid","up"],["Homocysteine","up"],["LDH","up"]],"opts":["Vitamin B12 deficiency","Folate deficiency","Alcohol related macrocytosis","Myelodysplastic syndrome"],"c":0,"why":"B12 is the cofactor for methylmalonyl CoA mutase as well as for methionine synthase, so losing it raises both methylmalonic acid and homocysteine. Folate deficiency blocks only the homocysteine pathway, which is why a raised methylmalonic acid separates the two and matters, since only B12 loss demyelinates the posterior columns.","week":"5"},{"labs":[["Reticulocyte count","up"],["Indirect bilirubin","up"],["LDH","up"],["Haptoglobin","down"],["Direct Coombs test","abn"]],"opts":["Autoimmune haemolytic anaemia","Aplastic anaemia","Acute gastrointestinal bleed","Megaloblastic anaemia"],"c":0,"why":"Red cells rupturing in the circulation spill haemoglobin and LDH, and the free haemoglobin is bound by haptoglobin, which is consumed and therefore falls. Heme breakdown floods the liver with unconjugated bilirubin faster than it can be conjugated, and a positive direct Coombs proves antibody is coating the cells rather than the marrow simply failing.","week":"5"},{"labs":[["Platelet count","down"],["PT/INR","up"],["aPTT","up"],["Fibrinogen","down"],["D-dimer","up"]],"opts":["Disseminated intravascular coagulation","Immune thrombocytopenic purpura","Liver failure coagulopathy","Heparin overdose"],"c":0,"why":"Widespread thrombin generation consumes platelets and clotting factors simultaneously, so every parameter deteriorates at once rather than in one pathway. A falling fibrinogen with a soaring D-dimer is the signature, because it shows the fibrinogen was converted into clot and then lysed rather than simply underproduced.","week":"5"},{"labs":[["Platelet count","down"],["PT/INR","n"],["aPTT","n"],["Bleeding time","up"],["Marrow megakaryocytes","up"]],"opts":["Immune thrombocytopenic purpura","Disseminated intravascular coagulation","Haemophilia A","Aplastic anaemia"],"c":0,"why":"Antibody mediated destruction removes circulating platelets in the spleen while the marrow keeps producing them, which is why megakaryocytes are increased rather than absent. Because only primary haemostasis is affected, the plasma factor pathways stay intact and both PT and aPTT remain normal.","week":"5"},{"labs":[["aPTT","up"],["PT/INR","n"],["Platelet count","n"],["Factor VIII activity","down"],["von Willebrand factor antigen","n"]],"opts":["Haemophilia A","von Willebrand disease","Vitamin K deficiency","Immune thrombocytopenic purpura"],"c":0,"why":"Factor VIII sits in the intrinsic pathway, so its loss prolongs aPTT alone and leaves the extrinsic PT untouched. A normal von Willebrand antigen is what excludes von Willebrand disease, where the missing carrier protein would drag factor VIII down secondarily and also impair platelet adhesion.","week":"5"},{"labs":[["PT/INR","up"],["aPTT","up"],["Platelet count","n"],["Fibrinogen","n"],["D-dimer","n"]],"opts":["Vitamin K deficiency or warfarin effect","Disseminated intravascular coagulation","von Willebrand disease","Thrombotic thrombocytopenic purpura"],"c":0,"why":"Vitamin K is required to carboxylate factors II, VII, IX and X, so losing it eventually affects both pathways, though PT moves first because factor VII has the shortest half life. Normal platelets, fibrinogen and D-dimer are decisive because they show nothing is being consumed, which is exactly what separates this from DIC.","week":"5"},{"labs":[["Troponin I","up"],["CK-MB","up"],["ECG ST segment","abn"],["Myoglobin","up"],["BNP","n"]],"opts":["Acute myocardial infarction","Stable angina","Acute pericarditis","Heart failure exacerbation"],"c":0,"why":"Troponin is a structural protein locked inside the myocyte, so it reaches the blood only when the cell membrane has actually died and ruptured. Reversible ischaemia in stable angina causes pain without necrosis, so troponin stays normal however severe the symptoms feel.","week":"5"},{"labs":[["BNP","up"],["Troponin I","n"],["Ejection fraction","down"],["Serum sodium","down"],["Creatinine","up"]],"opts":["Systolic heart failure","Acute myocardial infarction","Hypovolaemic shock","Chronic kidney disease alone"],"c":0,"why":"Ventricular wall stretch from volume overload triggers BNP release from the myocardium, so BNP tracks filling pressure rather than cell death. The low sodium and rising creatinine come from RAAS and ADH activation in response to poor forward flow, which retains free water and drops renal perfusion.","week":"5"},{"labs":[["Haemoglobin","up"],["Haematocrit","up"],["Red cell mass","up"],["Erythropoietin","down"],["JAK2 mutation","abn"]],"opts":["Polycythaemia vera","Secondary polycythaemia from COPD","Relative polycythaemia from dehydration","Chronic myeloid leukaemia"],"c":0,"why":"A JAK2 mutation makes the marrow proliferate independently of its growth signal, so the erythropoietin feedback loop suppresses EPO to almost nothing while red cell mass climbs. In secondary polycythaemia the hypoxic kidney is driving the process, so EPO would be high instead of low.","week":"5"},{"labs":[["Haemoglobin","down"],["Reticulocyte count","up"],["Peripheral smear","abn"],["Indirect bilirubin","up"],["Haemoglobin electrophoresis","abn"]],"opts":["Sickle cell disease","Iron deficiency anaemia","Aplastic anaemia","Acute blood loss"],"c":0,"why":"A single amino acid substitution makes deoxygenated haemoglobin polymerise, distorting the cell and shortening its lifespan to about twenty days, which drives both the reticulocytosis and the unconjugated hyperbilirubinaemia. Electrophoresis is definitive because it identifies the abnormal haemoglobin variant rather than merely proving cells are being destroyed.","week":"5"},{"labs":[["White cell count","up"],["Blast cells on smear","abn"],["Haemoglobin","down"],["Platelet count","down"],["Absolute neutrophil count","down"]],"opts":["Acute leukaemia","Severe bacterial sepsis","Infectious mononucleosis","Anaemia of chronic disease"],"c":0,"why":"Clonal blasts fill the marrow and crowd out normal haematopoiesis, so the total white count is high yet functional neutrophils, red cells and platelets all fall together. That combination of a high count with pancytopenia of the mature lines distinguishes malignancy from a reactive leucocytosis, where mature neutrophils rise and the other lines are spared.","week":"5"},{"labs":[["Lactate","up"],["Central venous oxygen saturation","down"],["Cardiac output","down"],["Systemic vascular resistance","up"],["Urine output","down"]],"opts":["Cardiogenic shock","Septic shock","Anaphylactic shock","Neurogenic shock"],"c":0,"why":"A failing pump drops cardiac output, so tissues extract far more oxygen than usual and venous saturation falls while anaerobic metabolism raises lactate. Compensatory sympathetic vasoconstriction pushes systemic vascular resistance up, the opposite of the distributive shocks where resistance collapses and venous saturation stays deceptively high.","week":"5"}],"pairs":[{"clue":"A patient bleeds after a dental extraction; aPTT is prolonged and the platelet count is normal, but bleeding time is also prolonged.","a":"von Willebrand disease","b":"Haemophilia A","why":"Von Willebrand factor does two jobs, carrying factor VIII and gluing platelets to injured endothelium, so its loss prolongs aPTT and bleeding time together. Haemophilia A affects only factor VIII, so platelet adhesion and bleeding time remain normal.","week":"5","c":0},{"clue":"Chest pain that has lasted forty minutes at rest and is not relieved by three sublingual nitroglycerin tablets.","a":"Acute myocardial infarction","b":"Stable angina","why":"Stable angina is a demand problem that resolves once demand falls, so rest and nitrates fix it within minutes. Pain that persists means supply is occluded rather than merely outstripped, and necrosis is already underway.","week":"5","c":0},{"clue":"A patient with dyspnoea, orthopnoea, bibasilar crackles and pink frothy sputum.","a":"Left sided heart failure","b":"Right sided heart failure","why":"The left ventricle backs blood up into the pulmonary circulation, so fluid collects in the lungs. Right sided failure backs up into the systemic veins instead, producing jugular distension, hepatomegaly and dependent oedema rather than crackles.","week":"5","c":0},{"clue":"Heart failure symptoms with pulmonary congestion but an ejection fraction measured at 60 percent.","a":"Diastolic heart failure with preserved ejection fraction","b":"Systolic heart failure","why":"A stiff hypertrophied ventricle cannot relax and fill, so stroke volume is low even though the fraction of that small volume ejected is normal. Ejection fraction measures emptying, not filling, which is why it misses the defect entirely here.","week":"5","c":0},{"clue":"Leg pain relieved by dangling the leg over the side of the bed, with a cool pale foot and absent pedal pulses.","a":"Peripheral arterial disease","b":"Chronic venous insufficiency","why":"Dependency recruits gravity to push arterial blood into an ischaemic limb, so hanging the leg down relieves arterial pain. Venous disease is the mirror image, because dependency worsens congestion and elevation is what brings relief.","week":"5","c":0},{"clue":"A brown, leathery pigmented ankle with a shallow weeping ulcer over the medial malleolus.","a":"Venous stasis ulcer","b":"Arterial ischaemic ulcer","why":"Chronic venous hypertension forces red cells into the tissue, where haemoglobin breaks down into haemosiderin and stains the skin brown. Arterial ulcers form at the most distal, least perfused points such as the toes, and they are deep, dry and punched out.","week":"5","c":0},{"clue":"Fever, chills and back pain beginning ten minutes into a unit of packed red cells, with dark urine.","a":"Acute haemolytic transfusion reaction","b":"Febrile non-haemolytic transfusion reaction","why":"ABO incompatible cells are lysed by preformed recipient antibodies, releasing free haemoglobin that darkens the urine and injures the renal tubules. A febrile non-haemolytic reaction is a cytokine response to donor leucocytes, so there is fever without haemolysis, haemoglobinuria or flank pain.","week":"5","c":0},{"clue":"Painless enlargement of a single cervical lymph node in a young adult with night sweats, and Reed-Sternberg cells on biopsy.","a":"Hodgkin lymphoma","b":"Acute lymphoblastic leukaemia","why":"Lymphoma begins as a solid mass in lymphoid tissue and spreads contiguously from node to node, so the presenting sign is a discrete node. Leukaemia begins in the marrow, so it declares itself with cytopenias and circulating blasts before any mass is palpable.","week":"5","c":0},{"clue":"An anaemic patient with a low MCV, a low ferritin and a raised TIBC.","a":"Iron deficiency anaemia","b":"Anaemia of chronic disease","why":"Empty stores drop the ferritin and drive compensatory transferrin production, which raises TIBC. Chronic disease sequesters iron rather than losing it, so ferritin is high and TIBC low even though the serum iron looks identical in both.","week":"5","c":0},{"clue":"A prolonged PT with a normal aPTT in a patient recently started on an oral anticoagulant.","a":"Warfarin therapy","b":"Heparin therapy","why":"Heparin potentiates antithrombin, which inactivates thrombin (factor IIa) and factor Xa of the COMMON pathway. Because the aPTT interrogates the intrinsic plus common pathways, heparin prolongs the aPTT while the PT and INR stay relatively unaffected at therapeutic doses. Warfarin instead blocks vitamin K dependent carboxylation of factors II, VII, IX and X, and factor VII has the shortest half life, so the PT and INR move first.","week":"5","c":0},{"clue":"Warm flushed skin, bounding pulses, hypotension and a high cardiac output in a febrile patient.","a":"Septic shock","b":"Cardiogenic shock","why":"Endotoxin driven vasodilation collapses systemic vascular resistance, so the heart compensates with a high output and the periphery stays warm early on. Cardiogenic shock has a failing pump with compensatory vasoconstriction, so the skin is cold, clammy and mottled.","week":"5","c":0},{"clue":"Hypotension and bradycardia with warm dry skin after a cervical spinal cord injury.","a":"Neurogenic shock","b":"Hypovolaemic shock","why":"Loss of sympathetic outflow removes vascular tone and the cardioaccelerator drive together, so the pulse falls rather than rises. Every other shock state leaves sympathetic reflexes intact, which is why tachycardia is the near universal early sign except here.","week":"5","c":0},{"clue":"A low platelet count with normal PT and aPTT and increased megakaryocytes in the marrow.","a":"Immune thrombocytopenic purpura","b":"Disseminated intravascular coagulation","why":"Antibody destruction removes platelets peripherally while the marrow compensates by making more, so megakaryocytes increase and plasma factors are untouched. DIC consumes platelets and factors together, so PT, aPTT and fibrinogen all deteriorate as well.","week":"5","c":0},{"clue":"Sudden unilateral calf swelling, warmth and tenderness three days after a long-haul flight.","a":"Deep vein thrombosis","b":"Cellulitis","why":"Prolonged immobility satisfies the stasis arm of the Virchow triad and lets a thrombus form, which obstructs outflow and swells the entire limb below the clot. Cellulitis is a spreading superficial infection with a defined erythematous border and systemic fever rather than limb-wide oedema.","week":"5","c":0},{"clue":"An elevated erythropoietin level in a patient with a haematocrit of 58 percent.","a":"Secondary polycythaemia","b":"Polycythaemia vera","why":"Chronic hypoxia from lung disease or altitude stimulates renal EPO production, so the elevated hormone is the cause of the raised red cell mass. In polycythaemia vera the marrow proliferates autonomously, so negative feedback suppresses EPO to a low level.","week":"5","c":0},{"clue":"Macrocytic anaemia with a low serum folate and a normal methylmalonic acid level.","a":"Folate deficiency","b":"Vitamin B12 deficiency","why":"Both vitamins are needed for DNA synthesis, so both enlarge the red cell, but only B12 converts methylmalonyl CoA to succinyl CoA. A normal methylmalonic acid therefore excludes B12 loss and predicts there will be no posterior column deficit.","week":"5","c":0},{"clue":"A rising jugular venous pressure, pitting ankle oedema and a tender enlarged liver, with clear lung fields.","a":"Right sided heart failure","b":"Left sided heart failure","why":"Failure of the right ventricle raises pressure behind it in the systemic venous system, engorging the neck veins, liver and dependent tissues. Clear lungs are the discriminator, because pulmonary congestion requires the left ventricle to be the failing chamber.","week":"5","c":0},{"clue":"Chest discomfort with ST elevation on ECG but a troponin drawn at presentation that is still within normal limits.","a":"Evolving ST elevation myocardial infarction","b":"Pericarditis","why":"Troponin takes roughly three to four hours after myocyte death begins to become detectable, so an early normal value cannot exclude infarction and must be repeated serially. The ECG reflects injury current in real time and therefore precedes the biomarker rise.","week":"5","c":0}],"redflags":[{"s":"Crushing substernal chest pain radiating to the jaw for thirty minutes with ST elevation in leads II, III and aVF.","act":1,"why":"ST elevation means full thickness injury from a totally occluded coronary artery, and myocardium dies progressively from the moment flow stops. Reperfusion within the first ninety minutes determines how much muscle survives.","week":"5"},{"s":"A transfusion recipient develops fever, flank pain and hypotension five minutes after the unit is started.","act":1,"why":"This is intravascular haemolysis from ABO incompatibility, and free haemoglobin precipitates in the renal tubules while the reaction triggers DIC. Stopping the infusion immediately limits the volume of incompatible cells delivered.","week":"5"},{"s":"Oozing from every venepuncture site and both intravenous lines in a septic patient, with a falling fibrinogen.","act":1,"why":"Simultaneous bleeding from multiple sites with consumed fibrinogen indicates DIC, where clotting factors have already been exhausted by widespread microthrombosis. Without treating the underlying trigger the patient bleeds and infarcts organs at the same time.","week":"5"},{"s":"A patient with heart failure develops sudden severe dyspnoea, pink frothy sputum and an oxygen saturation of 84 percent.","act":1,"why":"Pulmonary capillary pressure has exceeded the oncotic pressure holding fluid inside the vessel, so plasma is flooding the alveoli and gas exchange is failing in real time. Untreated flash pulmonary oedema progresses to respiratory arrest within minutes.","week":"5"},{"s":"Sudden pleuritic chest pain, dyspnoea and tachycardia in a postoperative patient with a swollen calf.","act":1,"why":"A leg thrombus has embolised to the pulmonary arteries, obstructing right ventricular outflow and creating dead space ventilation. A large embolus can cause obstructive shock and arrest before imaging is even completed.","week":"5"},{"s":"A limb that is pale, pulseless, painful, paraesthetic and cold below the knee.","act":1,"why":"Acute arterial occlusion gives skeletal muscle roughly six hours before irreversible necrosis begins. Every hour of delay converts a salvageable limb into an amputation.","week":"5"},{"s":"A sickle cell patient with severe chest pain, fever, hypoxia and a new pulmonary infiltrate.","act":1,"why":"Acute chest syndrome is vaso-occlusion within the pulmonary microcirculation, and the resulting hypoxia drives further sickling in a self-amplifying loop. It is the leading cause of death in sickle cell disease and needs oxygen, hydration and often exchange transfusion.","week":"5"},{"s":"Blood pressure of 210 over 130 with a severe headache, blurred vision and confusion.","act":1,"why":"Cerebral autoregulation has been overwhelmed, so systemic pressure is transmitted to the capillary bed and is producing cerebral oedema. This is hypertensive emergency with end organ damage, unlike asymptomatic severe hypertension.","week":"5"},{"s":"A patient in cardiogenic shock with a systolic pressure of 78, cold mottled skin and a lactate of 6.","act":1,"why":"The rising lactate proves tissues have already switched to anaerobic metabolism because the pump cannot deliver oxygen. Without immediate haemodynamic support the shock spirals, since coronary perfusion itself depends on the pressure that is falling.","week":"5"},{"s":"A neutropenic leukaemia patient with an absolute neutrophil count of 200 and a temperature of 38.5 degrees.","act":1,"why":"With no neutrophils the patient cannot form pus or localising signs, so fever may be the only evidence of overwhelming infection. Empiric antibiotics within the first hour is the intervention that changes mortality.","week":"5"},{"s":"A platelet count of 40 with spontaneous petechiae, gum bleeding and a new severe headache.","act":1,"why":"A headache in a profoundly thrombocytopenic patient must be treated as intracranial haemorrhage until proven otherwise, because there is no platelet reserve to seal a cerebral vessel. The mucosal bleeding confirms primary haemostasis has already failed.","week":"5"},{"s":"Mild flushing and a few urticarial hives thirty minutes into a transfusion, with normal vital signs and no respiratory symptoms.","act":0,"why":"An isolated urticarial reaction is a localised histamine response to donor plasma proteins and does not involve red cell destruction or airway compromise. The infusion is paused and an antihistamine given, but this is monitored rather than an emergency.","week":"5"},{"s":"A patient on warfarin with an INR of 2.6 and no bleeding.","act":0,"why":"An INR of 2 to 3 is the intended therapeutic window for most indications, so this reflects adequate anticoagulation rather than a complication. Reversing it would return the patient to the thrombotic risk the drug was prescribed to prevent.","week":"5"},{"s":"Reticulocyte count of 6 percent two weeks after starting iron replacement for iron deficiency anaemia.","act":0,"why":"A reticulocytosis is the marrow responding correctly to restored iron by releasing immature red cells, and it is the earliest sign treatment is working. A flat reticulocyte count in that setting would be the concerning result.","week":"5"},{"s":"Bilateral dependent ankle oedema that resolves overnight in a patient with chronic venous insufficiency.","act":0,"why":"Gravity dependent oedema that clears with elevation reflects incompetent venous valves rather than acute cardiac decompensation. It calls for compression, elevation and skin surveillance, not emergency intervention.","week":"5"},{"s":"Predictable exertional chest tightness that resolves within three minutes of rest in a patient with known stable angina.","act":0,"why":"A reproducible demand related pattern that resolves with rest means the plaque is stable and the ischaemia is reversible without necrosis. A change in that pattern, such as pain at rest or lasting longer, is what converts it into an emergency.","week":"5"}],"chains":[{"title":"Chronic blood loss to iron deficiency anaemia","start":"Chronic occult gastrointestinal bleeding from a colonic lesion","steps":["Daily iron lost in blood exceeds the small amount absorbed from the diet","Hepatic and macrophage iron stores are drawn down and serum ferritin falls","The liver upregulates transferrin production, raising TIBC while transferrin saturation drops","Erythroblasts cannot assemble adequate haemoglobin, so they divide extra times and emerge small and pale","Microcytic hypochromic anaemia reduces oxygen carrying capacity, producing fatigue, pallor and exertional dyspnoea"],"why":"This shows why the iron studies diverge in true deficiency, with ferritin and saturation falling while TIBC rises, and why the red cell indices change last rather than first.","week":"5"},{"title":"Deoxygenation to vaso-occlusive crisis in sickle cell disease","start":"A hypoxic, acidotic or dehydrated state in a patient homozygous for haemoglobin S","steps":["Deoxygenated haemoglobin S polymerises into rigid fibres inside the red cell","The cell distorts into a sickle shape and loses its normal deformability","Rigid cells lodge in capillaries and post-capillary venules, obstructing flow","Downstream tissue becomes ischaemic, which worsens local hypoxia and acidosis and drives further sickling","Infarction of bone, spleen or lung produces severe pain, and repeated episodes cause autosplenectomy and cumulative organ damage"],"why":"The teaching point is the self-amplifying loop, because the ischaemia caused by sickling creates the very conditions that cause more sickling, which is why oxygen and hydration are what break the crisis.","week":"5"},{"title":"Sepsis to disseminated intravascular coagulation","start":"Gram negative endotoxin in the bloodstream damages vascular endothelium","steps":["Tissue factor is exposed and released systemically, triggering the extrinsic pathway everywhere at once","Uncontrolled thrombin generation deposits fibrin microthrombi throughout the microcirculation","Circulating platelets and clotting factors including fibrinogen are consumed faster than they can be replaced","Plasmin is activated to lyse the fibrin, raising D-dimer and further degrading remaining clotting capacity","The patient bleeds from every puncture site while simultaneously infarcting kidneys, skin and lungs"],"why":"This explains the apparent paradox of clotting and bleeding coexisting, and why the diagnostic signature is a low fibrinogen with a high D-dimer rather than any single abnormal clotting time.","week":"5"},{"title":"Atherosclerotic plaque rupture to myocardial infarction","start":"Endothelial injury in a coronary artery from hypertension, smoking or hyperlipidaemia","steps":["LDL enters the intima, is oxidised, and is engulfed by macrophages that become foam cells","A lipid core with an overlying fibrous cap forms and progressively narrows the lumen","The cap ruptures, exposing thrombogenic collagen and lipid to flowing blood","Platelets adhere and aggregate and the coagulation cascade generates a fibrin rich occlusive thrombus","Flow stops, the myocytes downstream switch to anaerobic metabolism and then necrose, releasing troponin"],"why":"It shows that infarction is a plaque stability event rather than a gradual narrowing event, which is why a patient with modest stenosis can infarct and why troponin appears only once cell membranes break.","week":"5"},{"title":"Compensation to decompensation in left heart failure","start":"Loss of contractile myocardium reduces left ventricular stroke volume and cardiac output","steps":["Reduced renal perfusion is sensed by the juxtaglomerular apparatus and activates the renin angiotensin aldosterone system","Angiotensin II vasoconstricts and aldosterone retains sodium and water, raising both afterload and preload","The already failing ventricle must eject against higher resistance while handling a larger volume, so stroke volume falls further","Ventricular remodelling and hypertrophy raise wall stress and myocardial oxygen demand","Left atrial and pulmonary capillary pressures rise until fluid crosses into the alveoli, producing orthopnoea, crackles and pulmonary oedema"],"why":"This is the central irony of heart failure, that mechanisms designed to defend perfusion after acute haemorrhage become the engine of deterioration in chronic pump failure, which is why blocking them rather than stimulating the heart is therapeutic.","week":"5"},{"title":"Immobility to pulmonary embolism","start":"Prolonged immobility slows venous return in the deep veins of the calf","steps":["Stasis allows activated clotting factors to accumulate locally instead of being washed away","A fibrin and red cell rich thrombus forms on a valve cusp and propagates proximally","Outflow obstruction raises venous pressure distally, causing unilateral calf swelling, warmth and tenderness","A fragment detaches and travels through the vena cava and right heart into the pulmonary arterial tree","Perfusion is lost to still-ventilated alveoli, creating dead space, hypoxaemia and acute right ventricular strain"],"why":"It walks the Virchow triad from a single risk factor through to the lethal endpoint, and explains why the embolus causes hypoxia through a ventilation-perfusion mismatch rather than through any airway problem.","week":"5"},{"title":"Autoantibody to immune thrombocytopenic purpura","start":"A viral illness triggers production of IgG autoantibody against platelet glycoprotein IIb/IIIa","steps":["Antibody coats circulating platelets without activating them","Splenic macrophages recognise the bound Fc portion and phagocytose the coated platelets","The circulating platelet count falls while the marrow compensates by increasing megakaryocyte production","Primary haemostasis fails because too few platelets remain to form the initial plug","Petechiae, purpura and mucosal bleeding appear while PT and aPTT stay normal because the plasma factors are untouched"],"why":"This explains the discriminating laboratory picture, since the defect is confined to platelet numbers in the periphery, so the coagulation times stay normal and the marrow shows increased rather than absent megakaryocytes.","week":"5"}]},"6":{"labs":[{"labs":[["BUN:creatinine ratio","up"],["Urine sodium","down"],["FENa","down"],["Urine osmolality","up"],["Urine sediment","n"]],"opts":["Prerenal acute kidney injury","Acute tubular necrosis","Postrenal obstruction","Chronic kidney disease stage 4"],"c":0,"why":"The tubules are still alive and starved of perfusion, so aldosterone and ADH drive avid sodium and water reabsorption, giving urine sodium under 20 mmol/L, FENa under 1 percent and concentrated urine over 500 mOsm. Urea is reabsorbed passively along with that sodium and water while creatinine is not, which is what lifts the ratio above 20 to 1. The sediment stays bland because no tubular cells have died.","week":"6"},{"labs":[["FENa","up"],["Urine sodium","up"],["Urine osmolality","down"],["BUN:creatinine ratio","n"],["Muddy brown granular casts","abn"]],"opts":["Acute tubular necrosis","Prerenal azotaemia","Acute pyelonephritis","Nephrotic syndrome"],"c":0,"why":"Necrotic tubular cells cannot reabsorb sodium or generate a concentration gradient, so FENa exceeds 2 percent and urine osmolality drifts toward that of plasma (isosthenuria). Because water and urea are no longer being pulled back, the BUN to creatinine ratio falls back to roughly 10 to 1. The sloughed epithelium and Tamm-Horsfall protein cast in the tubular lumen and appear as muddy brown granular casts.","week":"6"},{"labs":[["Serum creatinine","up"],["Serum potassium","up"],["Post-void bladder residual volume","up"],["Renal ultrasound","abn"],["Urine sediment","n"]],"opts":["Postrenal acute kidney injury from bladder outlet obstruction","Acute tubular necrosis","Acute glomerulonephritis","Prerenal acute kidney injury"],"c":0,"why":"Back-pressure from an obstructed outflow tract raises hydrostatic pressure in Bowman capsule, which opposes filtration and drops GFR even though renal blood flow and the tubules themselves are initially intact, hence the bland sediment. The dilated collecting system on ultrasound and the large residual volume are the discriminators. Distal secretion is impaired by the pressure, so potassium climbs early.","week":"6"},{"labs":[["24 hour urine protein","up"],["Serum albumin","down"],["Serum cholesterol","up"],["Urine red cells","n"],["Blood pressure","n"]],"opts":["Nephrotic syndrome","Nephritic syndrome","Acute tubular necrosis","Lower urinary tract infection"],"c":0,"why":"Loss of the glomerular charge and size barrier lets albumin pour out at more than 3.5 g per day, dropping plasma oncotic pressure and producing oedema. The liver answers low oncotic pressure by increasing lipoprotein synthesis, which is why cholesterol rises. The absence of haematuria and hypertension is the clue that this is a leak, not an inflammatory glomerular injury.","week":"6"},{"labs":[["Urine red cells","up"],["Red cell casts","abn"],["Serum complement C3","down"],["Antistreptolysin O titre","up"],["Blood pressure","up"]],"opts":["Acute poststreptococcal glomerulonephritis","Minimal change nephrotic syndrome","Acute pyelonephritis","Renal calculus with haematuria"],"c":0,"why":"Immune complexes deposit in the glomerular capillary wall and consume complement, so C3 falls while the ASO titre records the preceding streptococcal infection. Red cell casts can only be moulded inside a tubule, so they prove the bleeding is glomerular rather than from a stone or the bladder. Inflammation drops GFR, salt and water are retained, and blood pressure rises.","week":"6"},{"labs":[["Urine leukocyte esterase","abn"],["Urine nitrites","abn"],["Urine white cells","up"],["White cell casts","n"],["Temperature","n"]],"opts":["Acute cystitis","Acute pyelonephritis","Acute glomerulonephritis","Asymptomatic bacteriuria"],"c":0,"why":"Gram-negative uropathogens reduce dietary nitrate to nitrite and the inflammatory response releases leukocyte esterase, so the dipstick is positive and there is pyuria. Infection confined to bladder mucosa produces no renal tubular inflammation, so casts are absent and there is no fever or systemic response. Asymptomatic bacteriuria has the same bacteriuria and often the same pyuria, so the dipstick cannot separate them. It is defined by the absence of dysuria, frequency and urgency, and is not treated except in pregnancy or before urological instrumentation.","week":"6"},{"labs":[["White cell casts","abn"],["Urine nitrites","abn"],["Serum white cell count","up"],["Temperature","up"],["C-reactive protein","up"]],"opts":["Acute pyelonephritis","Acute cystitis","Acute tubular necrosis","Nephrotic syndrome"],"c":0,"why":"Bacteria have ascended the ureter into the renal parenchyma, so neutrophils enter the tubular lumen and are cast into cylinders, which is the single finding that localises infection to the kidney. Parenchymal invasion produces a systemic inflammatory response with fever, leucocytosis and a raised CRP, none of which occurs with a bladder infection.","week":"6"},{"labs":[["eGFR","down"],["Serum phosphate","up"],["Serum calcium","down"],["Parathyroid hormone","up"],["Haemoglobin","down"]],"opts":["Chronic kidney disease with secondary hyperparathyroidism","Primary hyperparathyroidism","Acute tubular necrosis","Nephrotic syndrome"],"c":0,"why":"Lost nephron mass cannot excrete phosphate and cannot 1-alpha hydroxylate vitamin D, so phosphate rises while calcitriol and therefore serum calcium fall, driving a compensatory rise in PTH. The normocytic anaemia comes from failure of peritubular erythropoietin production. In primary hyperparathyroidism calcium would be high and phosphate low, which is the mirror image.","week":"6"},{"labs":[["Urine pH","up"],["Urine red cells","up"],["Urine culture for urease-producing Proteus","abn"],["Staghorn calculus on imaging","abn"]],"opts":["Struvite (magnesium ammonium phosphate) stone","Uric acid stone","Calcium oxalate stone","Cystine stone"],"c":0,"why":"Urease-producing organisms split urea into ammonia, which alkalinises the urine above pH 7 and allows magnesium ammonium phosphate to precipitate. Because the stone grows in the collecting system rather than passing, it fills the calyces as a staghorn and becomes a permanent reservoir of infection. Uric acid stones require acidic urine and are radiolucent; calcium oxalate stones form in acid to neutral urine without infection.","week":"6"},{"labs":[["pH","down"],["PaCO2","up"],["HCO3","up"],["PaO2","down"]],"opts":["Chronic respiratory acidosis with partial metabolic compensation","Acute respiratory alkalosis","Metabolic acidosis with respiratory compensation","Metabolic alkalosis"],"c":0,"why":"Alveolar hypoventilation retains CO2, which hydrates to carbonic acid and lowers pH, so a high PaCO2 with a low pH is respiratory acidosis by definition. The raised bicarbonate is the giveaway that this has been going on for days: renal tubules take time to generate and retain new bicarbonate, so a compensated picture means chronic disease with an acute exacerbation on top.","week":"6"},{"labs":[["pH","up"],["PaCO2","down"],["PaO2","down"],["Alveolar-arterial oxygen gradient","up"],["Chest radiograph","n"]],"opts":["Pulmonary embolism","Acute asthma exacerbation","Pneumonia","Anxiety hyperventilation"],"c":0,"why":"An embolus creates ventilated but unperfused alveoli, so ventilation is wasted as dead space while blood is redistributed to units with too little ventilation, widening the A-a gradient and producing hypoxaemia. Pain and hypoxaemia drive tachypnoea, blowing off CO2 and creating a respiratory alkalosis. Anxiety hyperventilation gives the same low CO2 and high pH but leaves PaO2 and the A-a gradient normal, and marked hypoxaemia with a clean film is the classic embolic signature.","week":"6"},{"labs":[["PaO2","down"],["PaO2/FiO2 ratio","down"],["Bilateral infiltrates on chest radiograph","abn"],["Pulmonary capillary wedge pressure","n"],["B-type natriuretic peptide","n"]],"opts":["Acute respiratory distress syndrome","Cardiogenic pulmonary oedema","Lobar pneumonia","Pulmonary embolism"],"c":0,"why":"The oedema of ARDS is leaked across an inflamed, permeable alveolar-capillary membrane, so filling pressures and BNP stay normal even though both lungs are flooded. Surfactant loss collapses alveoli that are still perfused, creating a large shunt and a PaO2/FiO2 ratio under 300 that does not correct with oxygen. A raised wedge pressure or BNP would instead point to a hydrostatic, cardiogenic cause.","week":"6"},{"labs":[["FEV1","down"],["FEV1/FVC ratio","down"],["Total lung capacity","up"],["Residual volume","up"],["DLCO","down"]],"opts":["Emphysema","Idiopathic pulmonary fibrosis","Asthma","Kyphoscoliosis"],"c":0,"why":"A reduced FEV1/FVC ratio defines obstruction, and loss of elastic recoil lets small airways collapse on expiration so air is trapped, raising residual volume and total lung capacity. Destruction of alveolar septa removes capillary surface area, which is why the diffusing capacity falls. Asthma obstructs without destroying alveoli, so its DLCO is normal, and restrictive disease would show reduced rather than increased volumes.","week":"6"},{"labs":[["FVC","down"],["FEV1","down"],["FEV1/FVC ratio","up"],["Total lung capacity","down"],["DLCO","down"]],"opts":["Pulmonary fibrosis (restrictive disease)","Chronic bronchitis","Emphysema","Acute asthma"],"c":0,"why":"Scarring stiffens the lung and lowers compliance, so every volume shrinks and the patient breathes rapidly and shallowly. FEV1 and FVC fall together but FVC falls proportionally more, so the ratio is preserved or high, which is the single measurement that separates restriction from obstruction. Fibrous thickening lengthens the diffusion path across the alveolar-capillary membrane, dropping DLCO.","week":"6"}],"pairs":[{"clue":"Three days of vomiting, creatinine 2.4, urine sodium 12 mmol/L, FENa 0.4 percent, no casts on microscopy.","a":"Prerenal acute kidney injury","b":"Acute tubular necrosis","why":"Living tubules answer hypoperfusion by hoarding sodium, so FENa stays under 1 percent and the sediment stays bland. In ATN the dead tubules leak sodium (FENa over 2 percent) and shed muddy brown granular casts.","week":"6","c":0},{"clue":"An 80 year old man with benign prostatic hyperplasia has creatinine 3.1, no urine for 12 hours and a bladder scan of 900 mL.","a":"Postrenal acute kidney injury","b":"Prerenal acute kidney injury","why":"Both give a bland sediment, but only obstruction produces a large residual volume and hydronephrosis. Here GFR falls because back-pressure in Bowman capsule opposes filtration, not because renal perfusion is low, and it reverses within minutes of catheterisation.","week":"6","c":0},{"clue":"Dysuria and frequency with pyuria and positive nitrites, temperature 37.0 C, no flank tenderness, no casts.","a":"Acute cystitis","b":"Acute pyelonephritis","why":"Casts can only be moulded inside renal tubules, so white cell casts, fever and costovertebral angle tenderness mark ascent into the kidney. Bladder infection inflames mucosa only and stays afebrile.","week":"6","c":0},{"clue":"Cola-coloured urine, periorbital puffiness, blood pressure 158/96 and red cell casts two weeks after a sore throat.","a":"Nephritic syndrome","b":"Nephrotic syndrome","why":"Nephritic disease is inflammatory: the capillary wall is breached so red cells and casts escape, and the abrupt fall in GFR retains salt and water, causing hypertension. Nephrotic disease is a non-inflammatory protein leak, so the sediment is quiet and the hallmark is proteinuria over 3.5 g per day with hypoalbuminaemia.","week":"6","c":0},{"clue":"Creatinine 4.2, haemoglobin 9.1, phosphate high, calcium low, ultrasound showing small echogenic kidneys.","a":"Chronic kidney disease","b":"Acute kidney injury","why":"Small echogenic kidneys, erythropoietin-deficient normocytic anaemia and secondary hyperparathyroidism all take months to develop. An acute injury leaves the kidneys normal or enlarged with a normal haemoglobin and a normal parathyroid hormone. Note that acute kidney injury can itself raise phosphate and lower calcium, so those two values do NOT separate acute from chronic; kidney size, haemoglobin and duration do.","week":"6","c":0},{"clue":"Sudden severe colicky right flank pain radiating to the groin, the patient cannot lie still, haematuria, temperature 36.9 C.","a":"Renal calculus with ureteric colic","b":"Acute pyelonephritis","why":"Colic waxes and wanes as ureteric peristalsis grips an obstructing stone, and the patient writhes because no position helps. Pyelonephritis is a constant dull flank ache with fever, rigors and costovertebral angle tenderness, and the patient lies still.","week":"6","c":0},{"clue":"Staghorn calculus filling the renal pelvis with urine pH 8.0 and a Proteus mirabilis culture.","a":"Struvite stone","b":"Calcium oxalate stone","why":"Urease-producing organisms split urea into ammonia, alkalinising the urine so magnesium ammonium phosphate precipitates and casts the whole collecting system. Calcium oxalate, the commonest stone overall, forms in acidic to neutral urine and is not infection driven.","week":"6","c":0},{"clue":"Day 12 after an episode of acute tubular necrosis, urine output has risen to 4.5 L per day and potassium has fallen to 3.0.","a":"Diuretic phase of acute kidney injury","b":"Recovery phase of acute kidney injury","why":"Regenerating tubules can pass filtrate again long before they can concentrate it or reabsorb electrolytes, so a large dilute diuresis with sodium and potassium wasting comes before true recovery. The danger in this phase is dehydration and hypokalaemia, not fluid overload.","week":"6","c":0},{"clue":"Stage 4 chronic kidney disease with haemoglobin 8.9, MCV 89, normal ferritin and a low reticulocyte count.","a":"Anaemia of chronic kidney disease","b":"Iron deficiency anaemia","why":"Damaged peritubular interstitial cells stop producing erythropoietin, so marrow output falls while cell size and iron stores stay normal. Iron deficiency would give microcytic hypochromic cells with a low ferritin and a high total iron binding capacity.","week":"6","c":0},{"clue":"Calcium 7.9, phosphate 6.4, parathyroid hormone 480, eGFR 18.","a":"Secondary hyperparathyroidism of chronic kidney disease","b":"Primary hyperparathyroidism","why":"In CKD the high PTH is a response to low calcium caused by phosphate retention and failed calcitriol production, so calcium is low and phosphate high. An autonomous parathyroid adenoma instead drives calcium up and wastes phosphate in the urine, so calcium is high and phosphate low.","week":"6","c":0},{"clue":"A 26 year old with episodic night-time wheeze; FEV1/FVC 0.62 that rises 18 percent after salbutamol, with a normal DLCO.","a":"Asthma","b":"COPD","why":"Asthmatic obstruction is reversible bronchospasm and mucosal inflammation of structurally intact alveoli, so gas transfer is normal and a bronchodilator restores flow. COPD obstruction is largely fixed, under 12 percent reversibility, and emphysematous destruction of alveolar walls lowers DLCO.","week":"6","c":0},{"clue":"Obese 62 year old, cyanosed, productive cough on most days for three months in each of two consecutive years, haematocrit 58, peripheral oedema.","a":"Chronic bronchitis","b":"Emphysema","why":"Chronic bronchitis is defined by exactly that cough history; mucus gland hypertrophy causes hypoventilation, so chronic hypoxaemia drives polycythaemia, cyanosis and cor pulmonale, the blue bloater. The emphysematous patient hyperventilates to keep saturations near normal and is thin and barrel-chested with a very low DLCO.","week":"6","c":0},{"clue":"PaO2 remains 55 mmHg after 15 minutes on 100 percent oxygen.","a":"Intrapulmonary shunt","b":"Dead space ventilation","why":"In a shunt, blood passes alveoli that are collapsed or fluid-filled, so it never meets the gas no matter how high the FiO2 is raised. Dead space and simple V/Q mismatch still have ventilated alveoli that can be enriched with oxygen, so supplemental oxygen corrects them.","week":"6","c":0},{"clue":"Sudden dyspnoea on post-operative day 2 with absent breath sounds at the left base, dull percussion and the trachea deviated toward the affected side.","a":"Atelectasis","b":"Pneumothorax","why":"Collapsed lung tissue occupies less volume, so it percusses dull and pulls the mediastinum and trachea toward it. Air in the pleural space adds volume, so it percusses hyperresonant and pushes the trachea away.","week":"6","c":0},{"clue":"Chest trauma, absent right breath sounds, hyperresonance, trachea deviated to the left, distended neck veins and BP 78/44.","a":"Tension pneumothorax","b":"Simple pneumothorax","why":"A one-way valve keeps forcing air into the pleural space until intrapleural pressure exceeds atmospheric, compressing the mediastinum and kinking the great veins so venous return and cardiac output collapse. A simple pneumothorax leaks a fixed volume and leaves haemodynamics and the trachea intact.","week":"6","c":0},{"clue":"Dull percussion at the right base with decreased breath sounds, decreased tactile fremitus and a tracheal shift away from the dull side.","a":"Pleural effusion","b":"Lobar pneumonia","why":"Fluid interposed between lung and chest wall damps transmitted vibration, so fremitus falls, and a large effusion pushes the mediastinum away. Consolidated lung is a better conductor, so pneumonia gives dullness with increased fremitus, bronchial breath sounds and no tracheal shift.","week":"6","c":0},{"clue":"Day 3 after hip replacement, sudden pleuritic pain and dyspnoea, SpO2 86 percent, clear lungs on auscultation, no fever, normal chest radiograph.","a":"Pulmonary embolism","b":"Pneumonia","why":"Severe hypoxaemia with a clean examination and a clean film points to a perfusion defect rather than an alveolar filling process. Pneumonia fills alveoli, so it produces fever, purulent sputum, crackles and a visible infiltrate.","week":"6","c":0},{"clue":"Bilateral infiltrates with a PaO2/FiO2 of 140, a normal BNP, normal heart size and a wedge pressure of 10 mmHg.","a":"Acute respiratory distress syndrome","b":"Cardiogenic pulmonary oedema","why":"ARDS oedema leaks across an inflamed, permeable alveolar-capillary membrane at normal filling pressures. Cardiogenic oedema is pushed out by raised hydrostatic pressure, so wedge pressure, BNP and heart size are all elevated.","week":"6","c":0}],"redflags":[{"s":"Chest trauma patient with absent right breath sounds, hyperresonance, trachea deviated to the left, distended neck veins and blood pressure 76/40.","act":1,"why":"This is a tension pneumothorax: rising intrapleural pressure compresses the mediastinum and kinks the great veins, so venous return fails and obstructive shock follows within minutes. Needle decompression comes before any imaging.","week":"6"},{"s":"Oliguric acute kidney injury with potassium 6.9, peaked T waves and a widening QRS on the monitor.","act":1,"why":"Hyperkalaemia raises resting membrane potential and inactivates sodium channels, so conduction slows toward ventricular fibrillation or asystole. Calcium to stabilise the myocardium, insulin with dextrose to shift potassium and urgent dialysis are all immediate.","week":"6"},{"s":"Status asthmaticus patient whose wheeze has disappeared and whose PaCO2 has climbed from 28 to 42 mmHg.","act":1,"why":"Wheeze requires turbulent airflow, so a silent chest means almost no air is moving. A normalising CO2 in a patient who was hyperventilating signals respiratory muscle fatigue and impending arrest, not improvement, so prepare for intubation.","week":"6"},{"s":"Post-operative man with 14 hours of anuria, suprapubic fullness and creatinine rising from 1.0 to 2.6.","act":1,"why":"Complete bladder outlet obstruction transmits back-pressure to the nephrons within hours, causing hydronephrosis, a falling GFR and hyperkalaemia. Bladder catheterisation is both the diagnostic test and the treatment and must not be delayed.","week":"6"},{"s":"Pyelonephritis with temperature 39.4 C, heart rate 126, blood pressure 84/50 and new confusion.","act":1,"why":"Gram-negative endotoxin has entered the circulation, producing vasodilation, capillary leak and septic shock with hypoperfusion of the kidney itself. Cultures, aggressive fluid resuscitation and antibiotics belong in the first hour.","week":"6"},{"s":"Stage 5 chronic kidney disease patient with a pericardial friction rub and pleuritic chest pain.","act":1,"why":"Uraemic toxins inflame the pericardium and a haemorrhagic effusion can accumulate quickly and tamponade the heart. Uraemic pericarditis is an absolute and urgent indication for dialysis.","week":"6"},{"s":"Chronic kidney disease patient with creatinine 9, new drowsiness, confusion and asterixis.","act":1,"why":"Retained nitrogenous waste crosses the blood-brain barrier and produces uraemic encephalopathy, which progresses to seizures and coma if the toxins are not cleared. This is an emergent dialysis indication rather than a neurological work-up.","week":"6"},{"s":"COPD carbon dioxide retainer placed on 10 L/min oxygen by mask, now drowsy, SpO2 99 percent, PaCO2 risen from 55 to 82.","act":1,"why":"High oxygen releases hypoxic pulmonary vasoconstriction so blood floods poorly ventilated units, blunts the hypoxic respiratory drive and displaces CO2 from haemoglobin by the Haldane effect. The result is carbon dioxide narcosis; titrate oxygen back to a target of 88 to 92 percent and reassess ventilation.","week":"6"},{"s":"Child 12 days after streptococcal pharyngitis with blood pressure 168/104, severe headache and blurred vision.","act":1,"why":"Acute glomerulonephritis drops GFR abruptly, retaining salt and water and raising blood pressure faster than cerebral autoregulation can adapt. This is a hypertensive emergency with a real risk of encephalopathy or seizure.","week":"6"},{"s":"ARDS patient whose PaO2 remains 48 mmHg on an FiO2 of 1.0.","act":1,"why":"Refractory hypoxaemia means a large intrapulmonary shunt, where blood perfuses collapsed or flooded alveoli and never contacts oxygen. More oxygen cannot fix it; the alveoli must be reopened with PEEP, low tidal volume ventilation and prone positioning.","week":"6"},{"s":"Day 3 after hip surgery, sudden pleuritic pain, SpO2 85 percent, heart rate 128, clear chest and a right ventricular heave.","act":1,"why":"A large embolus obstructs the pulmonary outflow tract, so right ventricular afterload spikes and the right heart dilates and fails, cutting left ventricular preload. Untreated this progresses to cardiogenic collapse and arrest.","week":"6"},{"s":"Stable COPD patient at a routine clinic visit, comfortable, SpO2 89 percent at rest, unchanged from his last three visits.","act":0,"why":"Chronic hypoxaemia is his compensated baseline and 88 to 92 percent is the intended target range in a retainer. Chasing a normal saturation with high-flow oxygen would risk hypercapnia, so compare with baseline and monitor.","week":"6"},{"s":"Day 11 after acute tubular necrosis, urine output 4 L in 24 hours, blood pressure 118/70, creatinine falling.","act":0,"why":"This is the expected diuretic phase: regenerating tubules can filter before they can concentrate, so a large dilute diuresis is a sign of recovery. Monitor fluid balance, sodium and potassium closely rather than trying to stop the polyuria.","week":"6"},{"s":"Creatinine rises from 0.9 to 1.1 two weeks after starting an ACE inhibitor in a chronic kidney disease patient with normal potassium.","act":0,"why":"Blocking angiotensin II dilates the efferent arteriole, which lowers intraglomerular pressure and produces a small predictable rise in creatinine. A rise under roughly 30 percent is acceptable and reflects the very mechanism that protects the kidney long term; recheck labs and continue.","week":"6"},{"s":"Known nephrotic syndrome with foamy urine and periorbital oedema on waking, stable weight, breathing comfortably.","act":0,"why":"Foam reflects heavy proteinuria and morning facial swelling reflects low plasma oncotic pressure in loose periorbital tissue, both expected features of the diagnosis. Escalate only for rapid weight gain, breathlessness or unilateral leg swelling suggesting renal vein thrombosis or embolism.","week":"6"},{"s":"A 4 mm distal ureteric stone with pain controlled on oral analgesia, no fever, normal creatinine and adequate urine output.","act":0,"why":"Stones under about 5 mm usually pass spontaneously and a partially obstructing stone with a functioning contralateral kidney does not threaten renal function. The emergency would be obstruction combined with infection, a solitary kidney or a rising creatinine, so monitor with fluids and strain the urine.","week":"6"}],"chains":[{"title":"Hypoperfusion to acute tubular necrosis","start":"Haemorrhage drops mean arterial pressure and renal blood flow.","steps":["Glomerular capillary hydrostatic pressure falls so GFR drops, and the juxtaglomerular apparatus activates renin, angiotensin II, aldosterone and ADH.","Intact tubules reabsorb sodium and water avidly, so urine sodium falls below 20 mmol/L, FENa below 1 percent and urine osmolality rises above 500, while urea dragged back with that water lifts the BUN to creatinine ratio above 20 to 1 with a bland sediment.","If perfusion is not restored, oxygen delivery fails in the metabolically demanding proximal tubule and thick ascending limb and those epithelial cells undergo ischaemic necrosis.","Sloughed cells and Tamm-Horsfall protein form muddy brown granular casts that obstruct the tubular lumen, while filtrate leaks back across the denuded basement membrane.","The tubule can no longer reabsorb sodium or concentrate urine, so FENa rises above 2 percent, urine osmolality drifts toward 300, the BUN to creatinine ratio returns to about 10 to 1, and the injury is intrarenal and no longer fluid responsive."],"why":"This is the most tested transition in renal pathophysiology because the same patient moves from a fully reversible state to established structural injury, and the renal indices flip only because the mechanism changed from living tubules hoarding sodium to dead tubules leaking it.","week":"6"},{"title":"Podocyte injury to the complications of nephrotic syndrome","start":"Immune or metabolic injury effaces podocyte foot processes and strips the anionic charge barrier of the glomerular filtration membrane.","steps":["Albumin, small but negatively charged and normally repelled, now crosses freely and urinary protein exceeds 3.5 g per day.","Serum albumin falls, plasma oncotic pressure drops, and Starling forces shift fluid out of capillaries into the interstitium, producing periorbital, dependent and eventually generalised oedema.","The fall in effective circulating volume activates renin, angiotensin II and aldosterone, which retain sodium and water and deepen the oedema.","Hepatocytes respond to low oncotic pressure by increasing lipoprotein synthesis, producing hyperlipidaemia, with filtered lipid appearing as fatty casts and oval fat bodies in the urine.","Antithrombin III and other regulatory proteins are lost in the urine alongside albumin, leaving a hypercoagulable state that classically causes renal vein thrombosis and pulmonary embolism."],"why":"Every feature of nephrotic syndrome, including the ones that look unrelated such as high cholesterol and clotting, traces back to a single event: non-selective loss of plasma proteins across a damaged filtration barrier.","week":"6"},{"title":"Nephron loss to renal bone disease","start":"Progressive nephron destruction drops GFR below roughly 30 mL/min.","steps":["Phosphate can no longer be excreted, so serum phosphate rises.","The damaged proximal tubule cannot 1-alpha hydroxylate 25-hydroxyvitamin D, so calcitriol falls and intestinal calcium absorption drops.","Serum calcium falls further as excess phosphate complexes with it and deposits in soft tissue.","The parathyroid glands sense the low ionised calcium and low calcitriol and secrete PTH continuously, producing secondary hyperparathyroidism.","Sustained PTH resorbs calcium from bone, causing renal osteodystrophy with bone pain and fragility fractures, while the high calcium-phosphate product drives vascular and valvular calcification."],"why":"Students memorise the pattern of high phosphate, low calcium and high PTH but miss the direction of causation: in CKD the PTH rise is compensatory and the calcium is low, which is exactly the reverse of primary hyperparathyroidism.","week":"6"},{"title":"Renin-angiotensin-aldosterone activation","start":"Reduced renal perfusion pressure is sensed by juxtaglomerular cells in the afferent arteriole while the macula densa detects a low sodium chloride load.","steps":["Renin is released and cleaves circulating angiotensinogen from the liver into angiotensin I.","Angiotensin converting enzyme on pulmonary capillary endothelium converts angiotensin I into angiotensin II.","Angiotensin II constricts systemic arterioles and preferentially constricts the efferent arteriole, raising blood pressure while propping up glomerular filtration pressure.","Angiotensin II stimulates adrenal aldosterone release, posterior pituitary ADH release and thirst, so the distal nephron and collecting duct retain sodium and water while secreting potassium.","Restored volume and pressure normally switch renin off, but in chronic kidney disease the stimulus never resolves, so persistent angiotensin II produces hypertension, glomerular hyperfiltration injury and progressive sclerosis."],"why":"The same loop explains a normal defence of blood pressure and why diseased kidneys cause hypertension that then damages the kidney further, and it is the reason ACE inhibitors protect nephrons by dilating the efferent arteriole and lowering glomerular pressure.","week":"6"},{"title":"Allergen to silent chest in asthma","start":"Inhaled allergen cross-links IgE bound to airway mast cells.","steps":["Mast cell degranulation releases histamine, leukotrienes and prostaglandins, which cause bronchial smooth muscle contraction, mucosal oedema and thick mucus secretion.","The airway lumen narrows, so resistance rises sharply and expiratory flow is limited, dropping FEV1 and the FEV1/FVC ratio and trapping air behind prematurely closing airways.","Poorly ventilated but still perfused alveoli create V/Q mismatch and hypoxaemia, and hypoxaemia plus irritant receptor firing drives tachypnoea, so PaCO2 falls and the early gas shows respiratory alkalosis.","Hyperinflation flattens the diaphragm and accessory muscles labour against high resistance until they fatigue, while mucus plugging shuts off whole segments.","Alveolar ventilation now falls, the wheeze disappears because too little air is moving, and PaCO2 climbs back into and then above the normal range while pH falls, signalling impending respiratory arrest."],"why":"The classic exam trap is the normalising PaCO2, which is exhaustion rather than improvement, and it only makes sense if the sequence from bronchospasm through compensatory hyperventilation to muscle fatigue is followed step by step.","week":"6"},{"title":"Emphysema to cor pulmonale","start":"Chronic cigarette smoke recruits neutrophils and macrophages and tips the protease-antiprotease balance so elastase digests alveolar septa.","steps":["Loss of elastic recoil and destruction of alveolar walls leaves small airways untethered, so they collapse during expiration.","Air is trapped, residual volume and total lung capacity rise, the diaphragm flattens and the work of breathing climbs, while lost alveolar-capillary surface area lowers DLCO.","Chronic alveolar hypoxia triggers hypoxic pulmonary vasoconstriction throughout both lungs, and the destroyed capillary bed removes vessels from the circuit altogether.","Pulmonary vascular resistance and pulmonary artery pressure rise, producing pulmonary hypertension.","The right ventricle hypertrophies against the load, then dilates and fails, giving cor pulmonale with a raised jugular venous pressure, hepatomegaly, ascites and peripheral oedema in a patient whose left ventricle is normal."],"why":"It links lung mechanics to right heart failure and explains why the oedema of cor pulmonale is fundamentally a pulmonary problem, which is why correcting the hypoxaemia rather than treating the heart is the therapeutic target.","week":"6"},{"title":"Sepsis to refractory hypoxaemia in ARDS","start":"A systemic insult such as sepsis floods the pulmonary circulation with inflammatory mediators that injure the alveolar-capillary membrane.","steps":["Activated neutrophils release proteases and reactive oxygen species and membrane permeability rises.","Protein-rich fluid leaks into the interstitium and then into the alveoli, where precipitated fibrin and cell debris form hyaline membranes.","Type II pneumocytes are damaged so surfactant production falls, surface tension rises and alveoli collapse, making the lung stiff with markedly reduced compliance.","Blood continues to perfuse alveoli that are flooded or collapsed, creating a large intrapulmonary shunt.","Because that blood never contacts gas, raising the FiO2 does not raise the PaO2, giving refractory hypoxaemia with a PaO2/FiO2 ratio under 300, bilateral infiltrates and normal cardiac filling pressures."],"why":"Recognising the shunt explains the defining clinical feature of ARDS, hypoxaemia that does not respond to oxygen, and therefore why treatment is PEEP and alveolar recruitment rather than simply more oxygen.","week":"6"}]},"7":{"labs":[{"labs":[["BUN","up"],["Serum creatinine","n"],["Haemoglobin","down"],["Stool occult blood","abn"]],"opts":["Acute kidney injury from dehydration","Upper GI bleed from a duodenal ulcer","Diverticular bleed in the sigmoid colon","Iron deficiency from menorrhagia"],"c":1,"why":"Blood that enters the gut proximal to the ligament of Treitz is digested, and the absorbed protein is converted to urea, so BUN climbs while the kidney itself stays normal and creatinine does not move. A BUN to creatinine ratio above 20 to 1 with a normal creatinine is therefore a bleeding sign, not a renal sign. A lower GI bleed does not raise BUN because the blood is passed before it can be digested and absorbed.","week":"7"},{"labs":[["Conjugated (direct) bilirubin","up"],["Alkaline phosphatase","up"],["GGT","up"],["Urine bilirubin","up"],["Urine urobilinogen","down"]],"opts":["Haemolytic anaemia","Gilbert syndrome","Posthepatic obstruction from a common bile duct stone","Acute hepatitis A"],"c":2,"why":"An obstructed duct forces already conjugated bilirubin back into the blood, and because that form is water soluble it is filtered into urine and darkens it. Nothing reaches the gut to be converted by bacteria, so urobilinogen falls and stools go pale. Alkaline phosphatase and GGT rise together because both are made by biliary epithelium that is induced by the pressure behind the stone.","week":"7"},{"labs":[["Unconjugated (indirect) bilirubin","up"],["Conjugated bilirubin","n"],["Urine bilirubin","n"],["LDH","up"],["Haptoglobin","down"]],"opts":["Haemolytic (prehepatic) jaundice","Choledocholithiasis","Alcoholic cirrhosis","Primary biliary cholangitis"],"c":0,"why":"Excess haem is delivered to a healthy liver faster than it can conjugate, so the unconjugated fraction rises alone. Unconjugated bilirubin travels bound to albumin and cannot be filtered, which is why the urine is clear despite deep jaundice. Haptoglobin is consumed mopping up free plasma haemoglobin and LDH leaks from the ruptured red cells, confirming that the problem is upstream of the liver.","week":"7"},{"labs":[["AST","up"],["ALT","up"],["AST to ALT ratio","abn"],["GGT","up"],["Mean corpuscular volume","up"]],"opts":["Acute viral hepatitis A","Non-alcoholic fatty liver disease","Paracetamol toxicity","Alcoholic hepatitis"],"c":3,"why":"Alcohol injures mitochondria, which are rich in AST, and depletes the pyridoxine that ALT synthesis depends on more heavily, so the ratio inverts to two to one or greater. GGT is directly induced by alcohol and macrocytosis reflects marrow toxicity and folate deficiency. Viral hepatitis reverses that pattern, with ALT exceeding AST and values often in the thousands rather than the hundreds.","week":"7"},{"labs":[["INR","up"],["Serum albumin","down"],["Platelets","down"],["Factor VIII activity","n"],["Serum ammonia","up"]],"opts":["Disseminated intravascular coagulation","Cirrhosis with hepatocellular failure","Immune thrombocytopenic purpura","Warfarin over-anticoagulation"],"c":1,"why":"The liver makes every clotting factor except von Willebrand factor and factor VIII, which come from endothelium, so factor VIII is preserved in liver failure but consumed in DIC. Low albumin shows synthetic failure sustained over weeks, and the thrombocytopenia comes from splenic sequestration in portal hypertension plus reduced thrombopoietin. Warfarin raises the INR but leaves albumin, platelets and ammonia untouched.","week":"7"},{"labs":[["Serum lipase","up"],["Serum amylase","up"],["Serum calcium","down"],["Blood glucose","up"],["WBC","up"]],"opts":["Acute cholecystitis","Perforated peptic ulcer","Acute pancreatitis","Small bowel obstruction"],"c":2,"why":"Premature activation of trypsin inside the gland starts autodigestion, spilling lipase and amylase into the circulation. Escaped lipase splits peripancreatic and mesenteric fat, and the liberated fatty acids chelate calcium as insoluble soap, which is why hypocalcaemia is a severity marker rather than an incidental finding. Islet damage plus the stress catecholamine and cortisol response pushes glucose up.","week":"7"},{"labs":[["Arterial pH","up"],["Serum bicarbonate","up"],["PaCO2","up"],["Serum potassium","down"],["Serum chloride","down"]],"opts":["Metabolic acidosis from severe diarrhoea","Respiratory alkalosis from pain and anxiety","Diabetic ketoacidosis","Hypochloraemic hypokalaemic metabolic alkalosis from gastric outlet obstruction"],"c":3,"why":"Protracted vomiting of gastric contents strips out hydrochloric acid, losing hydrogen and chloride together and leaving bicarbonate behind. The accompanying volume loss drives aldosterone, which reabsorbs sodium in exchange for potassium and hydrogen and so sustains the alkalosis instead of correcting it. The raised PaCO2 is appropriate respiratory compensation by hypoventilation, not a second primary disorder.","week":"7"},{"labs":[["Arterial pH","down"],["Serum bicarbonate","down"],["Anion gap","n"],["Serum chloride","up"],["Serum potassium","down"]],"opts":["Normal anion gap metabolic acidosis from severe diarrhoea","Lactic acidosis from bowel ischaemia","Diabetic ketoacidosis","Metabolic alkalosis from vomiting"],"c":0,"why":"Intestinal and pancreatic secretions below the pylorus are bicarbonate rich, so high volume diarrhoea loses base without adding any unmeasured acid anion. Chloride is retained to preserve electroneutrality, producing a hyperchloraemic acidosis with a normal gap, and potassium is lost in the stool as well. Ischaemia or ketoacidosis would add lactate or ketoacids and widen the gap, which is the discriminator here.","week":"7"},{"labs":[["Serum creatinine","up"],["Urine sodium","down"],["Urine sediment","n"],["Serum sodium","down"],["Urine output","down"]],"opts":["Acute tubular necrosis","Hepatorenal syndrome","Post-renal obstruction from prostatic enlargement","Acute glomerulonephritis"],"c":1,"why":"The kidneys are structurally normal, which is why the sediment is bland, but they are intensely vasoconstricted because splanchnic vasodilation in cirrhosis has collapsed the effective arterial volume. Avid sodium reabsorption drops urine sodium below 10 and ADH driven water retention dilutes serum sodium. Acute tubular necrosis would show muddy brown casts and a urine sodium above 40, because injured tubules can no longer reabsorb what they filter.","week":"7"},{"labs":[["LH","up"],["FSH","n"],["Total testosterone","up"],["Fasting insulin","up"],["Sex hormone binding globulin","down"]],"opts":["Premature ovarian insufficiency","Hypothalamic amenorrhoea","Polycystic ovary syndrome","Early pregnancy"],"c":2,"why":"A raised LH against a normal FSH drives theca cell androgen output, while hyperinsulinaemia both amplifies that drive and suppresses hepatic SHBG so more testosterone circulates free. Premature ovarian insufficiency looks quite different, with a high FSH and a low oestradiol because the follicles themselves have failed. Hypothalamic amenorrhoea suppresses both gonadotrophins, so LH and FSH are low.","week":"7"},{"labs":[["PSA","up"],["Alkaline phosphatase","up"],["Serum calcium","n"],["Haemoglobin","down"],["Serum creatinine","up"]],"opts":["Benign prostatic hyperplasia","Acute bacterial prostatitis","Testicular seminoma","Prostate cancer with bone metastases"],"c":3,"why":"Prostate cancer seeds bone through the vertebral venous plexus and produces osteoblastic lesions, so alkaline phosphatase rises with new bone formation and marrow replacement causes anaemia. Calcium stays normal or even low precisely because those lesions consume calcium, unlike the lytic metastases of myeloma or breast cancer. Benign hyperplasia raises PSA only modestly and leaves alkaline phosphatase normal, while the rising creatinine here reflects bladder outlet or ureteric obstruction.","week":"7"},{"labs":[["Serum vitamin B12","down"],["Ferritin","down"],["CRP","up"],["Serum albumin","down"],["Faecal calprotectin","up"]],"opts":["Ulcerative colitis limited to the rectum","Crohn disease of the terminal ileum","Irritable bowel syndrome","Coeliac disease"],"c":1,"why":"Vitamin B12 is absorbed only at the terminal ileum, so isolated B12 deficiency localises the lesion there rather than to the colon. A high faecal calprotectin proves neutrophils are in the mucosa and excludes irritable bowel syndrome, while the low albumin reflects protein losing enteropathy plus the acute phase response. Coeliac disease damages the proximal small bowel and typically spares B12 absorption.","week":"7"},{"labs":[["WBC with left shift","up"],["CRP","up"],["Urinalysis","n"],["Serum beta-hCG","n"],["Serum lipase","n"]],"opts":["Ruptured ectopic pregnancy","Acute pyelonephritis","Acute pancreatitis","Acute appendicitis"],"c":3,"why":"A modest neutrophil leucocytosis with a rising CRP fits early transmural appendiceal inflammation rather than a systemic infection. The normal results carry the diagnosis here, because a negative hCG removes ectopic pregnancy, a clean urinalysis removes urinary infection and a normal lipase removes pancreatitis. Be aware that an inflamed appendix lying against the ureter can produce a few red or white cells in urine without meaning infection.","week":"7"},{"labs":[["Haemoglobin","down"],["Mean corpuscular volume","down"],["Ferritin","down"],["Total iron binding capacity","up"],["Faecal occult blood","abn"]],"opts":["Anaemia of chronic disease from ulcerative colitis","Vitamin B12 deficiency","Occult bleeding from a right sided colon cancer","Acute haemorrhage from oesophageal varices"],"c":2,"why":"Slow chronic blood loss drains iron stores, so ferritin falls and the liver compensates by making more transferrin, which raises the total iron binding capacity, and the marrow turns out small pale cells. Anaemia of chronic disease gives the opposite iron picture, with a normal or high ferritin and a low binding capacity, because iron is sequestered rather than absent. Right sided colonic tumours bleed silently into liquid stool, so iron deficiency in an adult is a colonoscopy trigger.","week":"7"}],"pairs":[{"clue":"Burning epigastric pain that eases within minutes of eating and then wakes the patient at two in the morning.","a":"Duodenal ulcer","b":"Gastric ulcer","why":"Food buffers acid and relieves duodenal pain for two to three hours until the stomach empties and unbuffered acid hits the bulb again. Food stimulates acid secretion and worsens gastric ulcer pain, so those patients avoid eating and lose weight.","week":"7","c":0},{"clue":"Colonoscopy shows normal mucosa between inflamed segments, and imaging shows a fistula tracking to the bladder.","a":"Crohn disease","b":"Ulcerative colitis","why":"Crohn inflammation is transmural and discontinuous, so it burrows through the whole thickness of the wall to create fistulae, strictures and abscesses. Ulcerative colitis is confined to mucosa and submucosa and is continuous from the rectum upward, so it cannot fistulate.","week":"7","c":0},{"clue":"Black, tarry, foul smelling stool with a BUN that has doubled while creatinine is unchanged.","a":"Upper GI bleed","b":"Lower GI bleed","why":"Blood must sit in gastric acid and be worked on by gut bacteria for several hours to turn black and tarry, which only happens above the ligament of Treitz. That same digestion generates the absorbed nitrogen load that drives the isolated BUN rise.","week":"7","c":0},{"clue":"Sudden painless passage of a large volume of dark red blood per rectum in a 74-year-old who is afebrile with a soft abdomen.","a":"Diverticular bleeding","b":"Acute diverticulitis","why":"A diverticulum bleeds when the vasa recta stretched over its dome erodes, which is brisk and painless because no inflammation is involved. Diverticulitis is a micro-perforation, so it presents with pain, fever and leucocytosis and rarely bleeds significantly.","week":"7","c":0},{"clue":"Left lower quadrant pain, fever and leucocytosis in a 68-year-old with lifelong constipation and a low fibre diet.","a":"Acute diverticulitis","b":"Acute appendicitis","why":"Diverticula form where the vasa recta pierce the muscular wall and where luminal pressure is highest, overwhelmingly in the sigmoid, so the pain is left sided and the patient is older. Appendicitis is right lower quadrant, usually younger, and begins as poorly localised periumbilical pain that migrates.","week":"7","c":0},{"clue":"Ten years of heartburn, and biopsy of the distal oesophagus now shows columnar epithelium containing goblet cells.","a":"Barrett oesophagus","b":"Erosive reflux oesophagitis","why":"Erosive oesophagitis is acute injury to the native squamous lining and heals without any change in cell type. Barrett is metaplasia, a durable switch to acid resistant intestinal type epithelium that can progress through dysplasia to adenocarcinoma, which is why it earns endoscopic surveillance.","week":"7","c":0},{"clue":"Crampy pain in waves with distension, and bowel sounds that were high pitched and tinkling yesterday but are silent today.","a":"Mechanical small bowel obstruction that is decompensating","b":"Paralytic ileus","why":"A mechanical block first makes the bowel contract harder against it, giving colic and hyperactive tinkling sounds, and it only falls silent later as the muscle fatigues or the wall infarcts. An ileus is silent and non-colicky from the very beginning because peristalsis never starts.","week":"7","c":0},{"clue":"Dark cola coloured urine, pale putty coloured stools and generalised itching.","a":"Posthepatic obstructive jaundice","b":"Prehepatic haemolytic jaundice","why":"Only conjugated bilirubin is water soluble enough to be filtered into urine, and only a blocked duct stops pigment reaching the gut to colour the stool. In haemolysis the unconjugated pigment stays bound to albumin, so the urine is normal and the stool is if anything darker.","week":"7","c":0},{"clue":"Ascites with splenomegaly and dilated periumbilical veins, but a normal jugular venous pressure.","a":"Portal hypertension from cirrhosis","b":"Right sided heart failure","why":"Portal hypertension raises pressure only within the portal circuit, so it congests the spleen and opens portosystemic collaterals while the systemic veins stay normal. Right heart failure raises systemic venous pressure, so the neck veins are distended and there is hepatojugular reflux.","week":"7","c":0},{"clue":"Two days after a variceal bleed a cirrhotic patient becomes drowsy with a flapping tremor of the outstretched hands; pulse and blood pressure are normal.","a":"Hepatic encephalopathy","b":"Alcohol withdrawal delirium","why":"Asterixis with an obvious precipitant fits encephalopathy, because the digested blood is a huge protein load that colonic bacteria convert to ammonia. Withdrawal appears one to three days after the last drink with autonomic overdrive, tachycardia, hypertension, sweating and a fine rhythmic tremor rather than a flap.","week":"7","c":0},{"clue":"Right upper quadrant pain now in its eighth hour, temperature 38.4, and arrest of inspiration when the examiner presses under the costal margin.","a":"Acute cholecystitis","b":"Biliary colic","why":"Biliary colic is transient cystic duct obstruction by a stone that falls back, so pain settles within a few hours with no fever, no leucocytosis and no tenderness afterwards. When the stone stays impacted the trapped concentrated bile inflames the wall, producing sustained pain, a systemic response and a positive Murphy sign.","week":"7","c":0},{"clue":"Severe constant epigastric pain boring straight through to the back, relieved by sitting up and leaning forward.","a":"Acute pancreatitis","b":"Acute cholecystitis","why":"The pancreas is retroperitoneal, so its inflammation irritates structures directly behind it and leaning forward takes pressure off the coeliac plexus. Gallbladder pain sits in the right upper quadrant and refers to the right scapula and shoulder tip through phrenic and dermatomal pathways.","week":"7","c":0},{"clue":"Pelvic pain and deep dyspareunia that intensify in the days before each period and settle once bleeding finishes, with no fever or discharge.","a":"Endometriosis","b":"Pelvic inflammatory disease","why":"Ectopic endometrial implants respond to the same hormonal cycle as the uterine lining, so they proliferate, bleed and inflame in step with menstruation, which is why the pain is strictly cyclical. Pelvic inflammatory disease is an ascending infection with continuous pain, fever, purulent discharge and cervical motion tenderness.","week":"7","c":0},{"clue":"A 24-year-old with three periods a year, coarse chin and upper lip hair, and velvety dark skin in the axillae.","a":"Polycystic ovary syndrome","b":"Premature ovarian insufficiency","why":"Acanthosis nigricans and hirsutism together point to hyperinsulinaemia driving ovarian androgen excess while oestrogen production continues unopposed. Premature ovarian insufficiency is failure of the follicles themselves, so oestrogen falls and the woman reports hot flushes and vaginal dryness with a high FSH.","week":"7","c":0},{"clue":"A 70-year-old with hesitancy, weak stream and nocturia; the prostate is symmetrically enlarged, smooth and rubbery.","a":"Benign prostatic hyperplasia","b":"Prostate cancer","why":"Hyperplasia grows in the periurethral transition zone, so it compresses the urethra early and feels uniformly enlarged on examination. Carcinoma arises in the peripheral zone away from the urethra, so it feels hard, nodular or asymmetric and usually causes no voiding symptoms until it is locally advanced.","week":"7","c":0},{"clue":"A 14-year-old with sudden severe scrotal pain, a high riding transverse testis and no cremasteric reflex on that side.","a":"Testicular torsion","b":"Epididymitis","why":"Twisting of the spermatic cord shortens it, lifts the testis and abolishes the cremasteric reflex, and the resulting venous then arterial occlusion gives roughly a six hour window before infarction. Epididymitis builds over days with fever and dysuria, preserves the cremasteric reflex and eases when the scrotum is elevated.","week":"7","c":0},{"clue":"An INR of 2.4 that fails to correct after three days of parenteral vitamin K, with a low factor V and a low albumin.","a":"Hepatic synthetic failure","b":"Vitamin K deficiency from biliary obstruction","why":"Vitamin K is only a cofactor for factors II, VII, IX and X, so replacing it corrects a true deficiency within hours and leaves factor V and albumin normal. A failing liver cannot manufacture any of these proteins, so factor V and albumin fall together and vitamin K makes no difference.","week":"7","c":0},{"clue":"Sudden large volume painless haematemesis in a patient with splenomegaly, ascites and spider naevi.","a":"Bleeding oesophageal varices","b":"Mallory-Weiss tear","why":"Varices are high pressure portosystemic collaterals with no muscular support, so they rupture without warning and keep bleeding because portal pressure keeps driving flow. A Mallory-Weiss tear is a mucosal laceration caused by forceful retching, so it follows repeated vomiting, is usually modest and stops on its own.","week":"7","c":0}],"redflags":[{"s":"A patient with known peptic ulcer disease develops sudden severe abdominal pain, a rigid board-like abdomen and absent bowel sounds.","act":1,"why":"Acid and gastric contents have escaped through a perforated ulcer into the peritoneum, producing chemical peritonitis that becomes bacterial within hours. Rigidity and free air mean surgery now, because delay leads directly to septic shock.","week":"7"},{"s":"Known cirrhosis, vomiting bright red blood, blood pressure 84/50 and heart rate 128.","act":1,"why":"Portal pressure keeps driving flow through a ruptured varix, so the bleed does not tamponade itself, and the coexisting coagulopathy and thrombocytopenia prevent clot formation. This needs immediate resuscitation, vasoactive therapy and urgent endoscopy.","week":"7"},{"s":"A 15-year-old with sudden severe unilateral testicular pain, nausea, a high riding testis and an absent cremasteric reflex.","act":1,"why":"The twisted cord occludes venous drainage first and then arterial inflow, so the testis is actively infarcting while the patient waits. Salvage rates fall steeply beyond about six hours, making this a surgical emergency rather than an imaging-then-review problem.","week":"7"},{"s":"Twelve hours of right lower quadrant pain that abruptly eased, followed by return of diffuse abdominal pain with temperature 38.9 and heart rate 120.","act":1,"why":"The sudden relief is the appendix perforating and releasing its distending pressure, not the illness resolving. The spreading pain and fever are generalised peritonitis from faecal contamination of the cavity.","week":"7"},{"s":"A cirrhotic patient with chronic ascites now has a temperature of 38.5, diffuse abdominal tenderness and new confusion.","act":1,"why":"Gut organisms have translocated into protein poor ascitic fluid that has almost no opsonic defence, giving spontaneous bacterial peritonitis. Diagnostic paracentesis and antibiotics are needed within hours, because it precipitates encephalopathy and hepatorenal syndrome and carries high mortality if missed.","week":"7"},{"s":"Jaundice with right upper quadrant pain, rigors, blood pressure 88/54 and confusion.","act":1,"why":"This pentad means infected bile is trapped under pressure behind an obstructed duct and is being forced into the hepatic venous system, seeding the bloodstream. Antibiotics alone cannot work while the pressure remains, so the duct must be decompressed urgently.","week":"7"},{"s":"A patient with ulcerative colitis is passing fewer stools than yesterday but has a distended tympanic abdomen, temperature 38.8, heart rate 122 and a transverse colon measuring 7 cm on plain film.","act":1,"why":"Transmural inflammation has paralysed the colonic neuromuscular apparatus, so the colon dilates and thins toward perforation. Falling stool frequency here is deterioration, not improvement, and antimotility or opioid agents will make it worse.","week":"7"},{"s":"A patient being managed conservatively for adhesive small bowel obstruction develops constant rather than colicky pain, localised tenderness, fever and a rising lactate.","act":1,"why":"Constant pain with peritonism and lactate means the loop has strangulated and the wall is ischaemic rather than simply obstructed. Once the mucosal barrier fails, bacteria translocate and septic shock follows, so the window to resect viable bowel is short.","week":"7"},{"s":"A cirrhotic patient with encephalopathy becomes unrousable, no longer shows asterixis and is not protecting the airway.","act":1,"why":"Loss of asterixis at this stage means progression to coma rather than recovery, because the patient can no longer sustain the posture that reveals it. Astrocyte glutamine accumulation is causing cerebral oedema, and the immediate killer is aspiration, so the airway is secured while the precipitant is hunted.","week":"7"},{"s":"A woman with seven weeks of amenorrhoea has sudden unilateral pelvic pain, shoulder tip pain and a syncopal episode; the pregnancy test is positive.","act":1,"why":"Shoulder tip pain is diaphragmatic irritation from free blood in the peritoneum, which means a tubal pregnancy has ruptured. This is ongoing intra-abdominal haemorrhage and needs immediate resuscitation and surgery.","week":"7"},{"s":"A man with benign prostatic hyperplasia has been unable to pass urine for ten hours, has a tender suprapubic mass, a bladder scan of 900 mL and a creatinine that has risen from 90 to 180.","act":1,"why":"Back pressure from the obstructed bladder is now transmitted to the ureters and collecting systems, causing a postrenal acute kidney injury. Catheterisation relieves the obstruction and reverses the injury, whereas leaving it produces hydronephrosis and permanent nephron loss.","week":"7"},{"s":"A 62-year-old postmenopausal woman reports two weeks of painless vaginal spotting; observations and haemoglobin are normal.","act":0,"why":"There is no haemodynamic threat, so this is not a resuscitation problem, but postmenopausal bleeding is endometrial carcinoma until proven otherwise. The correct response is prompt transvaginal ultrasound and endometrial biopsy within days, and the error to avoid is reassurance rather than delay of minutes.","week":"7"},{"s":"A 28-year-old man has a painless, firm, non-tender lump within the body of the testis that does not transilluminate.","act":0,"why":"A solid intratesticular mass is highly suspicious for a germ cell tumour and needs ultrasound and urological referral within days, but nothing is ischaemic or haemorrhaging right now. The time-critical scrotum is the painful one, because torsion is the condition with an hours-long clock.","week":"7"},{"s":"A patient on lactulose for hepatic encephalopathy is passing three soft stools a day and asks to stop the drug.","act":0,"why":"Two to three soft stools daily is the therapeutic target, not an adverse effect, because lactulose acidifies the colon and traps ammonia as non-absorbable ammonium for excretion. Stopping it lets ammonia climb again, though more than four or five watery stools would warrant dose reduction to avoid dehydration and hypernatraemia.","week":"7"},{"s":"A well 19-year-old has a total bilirubin of 2.3 mg/dL that is entirely unconjugated during a flu-like illness; ALT, alkaline phosphatase and haemoglobin are normal.","act":0,"why":"Reduced UGT1A1 conjugating capacity in Gilbert syndrome is unmasked by fasting, stress or intercurrent illness and produces mild isolated unconjugated hyperbilirubinaemia. Normal transaminases exclude hepatocellular injury, a normal haemoglobin excludes haemolysis and the absent conjugated fraction excludes obstruction, so reassurance is the correct management.","week":"7"},{"s":"A patient started on ferrous sulfate three days ago reports black stools; faecal occult blood is negative, haemoglobin is unchanged and vitals are normal.","act":0,"why":"Iron and bismuth colour stool black without the sticky tarry texture and offensive smell that digested blood produces. A negative occult blood test with a stable haemoglobin rules out bleeding, so the iron is continued and the patient is educated about the expected colour change.","week":"7"}],"chains":[{"title":"Cirrhosis to a bleeding oesophageal varix","start":"Chronic hepatocyte injury drives fibrosis and regenerative nodules that distort the hepatic sinusoids.","steps":["Resistance to blood flowing through the liver rises, and portal venous pressure climbs above its normal 5 to 10 mmHg.","Portal blood is diverted backwards into portosystemic collateral channels, the most important of which are the submucosal veins of the lower oesophagus and gastric fundus.","Those thin walled veins dilate into varices that bulge into the lumen with no muscular support around them.","A varix ruptures, and because portal pressure keeps pushing blood through it while the failing liver cannot supply clotting factors or platelets, the bleeding does not self-limit.","Massive painless haematemesis with hypovolaemic shock results, and the swallowed blood then becomes a protein load that precipitates encephalopathy."],"why":"Every variceal complication traces back to one number, the portal pressure gradient, which is why treatment aims at lowering portal pressure rather than at the vein itself.","week":"7"},{"title":"Portal hypertension to ascites and hepatorenal syndrome","start":"Established cirrhosis with portal hypertension and falling hepatic albumin synthesis.","steps":["Nitric oxide released in the congested splanchnic bed causes marked arterial vasodilation, so blood pools in the abdominal circulation.","Effective arterial blood volume falls even though total body water is increased, and the baroreceptors read this as hypovolaemia.","Renin angiotensin aldosterone and antidiuretic hormone are activated, retaining sodium and free water and worsening the overload.","High sinusoidal hydrostatic pressure combined with low plasma oncotic pressure pushes that retained fluid into the peritoneal cavity as ascites, while ADH driven water retention dilutes the serum sodium.","Sustained renal arteriolar vasoconstriction from the same neurohormonal drive lowers glomerular filtration in structurally normal kidneys, which is hepatorenal syndrome."],"why":"This links the liver chapter to the renal material, because the kidney here is a victim of circulatory sensing rather than intrinsic disease, which explains the bland sediment, the urine sodium under 10 and why treatment targets the circulation with albumin and vasoconstrictors.","week":"7"},{"title":"A gastrointestinal bleed to hepatic encephalopathy","start":"A cirrhotic patient bleeds from a varix, delivering a large protein load in the form of blood into the gut lumen.","steps":["Urease producing colonic bacteria deaminate that protein and generate a surge of ammonia.","Ammonia absorbed into portal blood bypasses the liver through portosystemic shunts, and the hepatocytes it does reach have too little urea cycle capacity to clear it.","Ammonia crosses the blood brain barrier, where astrocytes detoxify it by combining it with glutamate to form glutamine.","Glutamine is osmotically active, so astrocytes swell, cerebral oedema develops and excitatory and inhibitory neurotransmission is deranged.","Asterixis, a reversed sleep-wake pattern and confusion progress through stupor to coma."],"why":"Understanding the ammonia to glutamine to astrocyte swelling step explains why lactulose and rifaximin work at the level of the colon, and why bleeding, constipation, infection and dehydration are the classic precipitants.","week":"7"},{"title":"A common bile duct stone to a prolonged INR","start":"A gallstone migrates out of the gallbladder and impacts in the common bile duct.","steps":["Bile can no longer reach the duodenum, so conjugated bilirubin regurgitates from the hepatocytes back into the blood.","Because conjugated bilirubin is water soluble it is filtered into the urine and darkens it, while the absence of pigment in the gut leaves stools pale.","Without bile salts in the intestinal lumen, dietary fat cannot be emulsified into micelles, so fat and the fat soluble vitamins A, D, E and K are malabsorbed.","Vitamin K deficiency halts the gamma carboxylation of factors II, VII, IX and X, and factor VII falls first because its half life is only about six hours.","The prothrombin time and INR rise, and they correct within hours of parenteral vitamin K because the hepatocytes themselves are still functioning."],"why":"This chain deliberately connects the biliary content to the coagulation material from earlier in the course, and the response to vitamin K is exactly what separates an obstructive coagulopathy from true hepatocellular failure.","week":"7"},{"title":"Helicobacter pylori to a bleeding duodenal ulcer","start":"Helicobacter pylori colonises the gastric antrum and its inflammation destroys somatostatin producing D cells.","steps":["Loss of somatostatin removes the brake on G cells, so gastrin rises and the parietal cell mass secretes more acid.","The duodenal bulb receives an acid load beyond what its mucus and bicarbonate can neutralise, and protective gastric metaplasia develops that the organism then colonises in turn.","Mucosal defence is overwhelmed and an ulcer erodes down through the mucosa and submucosa.","An ulcer on the posterior wall of the bulb erodes into the gastroduodenal artery that lies directly behind it.","Brisk arterial haemorrhage follows, producing melaena, a falling haemoglobin and a BUN that rises out of proportion to creatinine as the blood is digested and absorbed."],"why":"Anatomy decides the complication, because posterior ulcers bleed from the gastroduodenal artery behind them while anterior ulcers, with only peritoneum in front, perforate instead.","week":"7"},{"title":"Faecolith to generalised peritonitis in appendicitis","start":"A faecolith or lymphoid hyperplasia obstructs the narrow appendiceal lumen.","steps":["Mucus secretion continues behind the blockage, so intraluminal pressure rises and the appendix distends, and visceral afferents refer this poorly localised pain to the periumbilical region.","Rising wall pressure exceeds venous and then capillary pressure, so the wall becomes congested and oedematous while trapped bacteria proliferate.","Inflammation reaches the serosa and irritates the adjacent parietal peritoneum, so the pain shifts and localises sharply at McBurney point with guarding and rebound.","Arterial supply is finally compromised, and the wall infarcts and becomes gangrenous.","The gangrenous wall perforates, the distending pressure and the localised pain are suddenly relieved, and spilled faecal content produces diffuse peritonitis and sepsis."],"why":"The migration of pain from periumbilical to right lower quadrant is simply the transition from visceral to parietal innervation, and the deceptive moment of relief at perforation is the trap that catches students and clinicians alike.","week":"7"},{"title":"Insulin resistance to anovulation and endometrial risk in PCOS","start":"Peripheral insulin resistance with compensatory hyperinsulinaemia.","steps":["Insulin acts on ovarian theca cells to amplify LH driven androgen production, and simultaneously suppresses hepatic synthesis of sex hormone binding globulin.","Free testosterone therefore rises sharply, producing hirsutism, acne and acanthosis nigricans.","Excess intraovarian androgen arrests follicles at the small antral stage, so no dominant follicle emerges and there is no mid-cycle LH surge.","Without ovulation there is no corpus luteum and therefore no progesterone, so the endometrium sees oestrogen from the many small follicles and from adipose aromatisation with nothing to oppose it.","The result is oligomenorrhoea with anovulatory infertility and, over years, endometrial hyperplasia and an increased risk of endometrial carcinoma."],"why":"Placing insulin at the head of the chain explains why weight loss and metformin improve ovulation, and why cyclic progestogen is given to protect an endometrium that never sees a luteal phase.","week":"7"}]}};
